script:
frappe.ui.form.on("SIV", {

    refresh(frm) {

        if (frm.doc.docstatus === 1) {

            if (frm.doc.status === "Active") {

                frm.add_custom_button("Make Inactive", function () {
                    frm.set_value("status", "Inactive");
                    frm.save();
                }).addClass("btn-danger");

            } else {

                frm.add_custom_button("Make Active", function () {
                    frm.set_value("status", "Active");
                    frm.save();
                }).addClass("btn-success");

            }

        }

    }

});

frappe.ui.form.on("Sales Order", {
    refresh(frm) {
        // Apply filter inside child table
        frm.fields_dict["items"].grid.get_field("item_code")
            .get_query = function(doc, cdt, cdn) {

                let row = locals[cdt][cdn];

                if (!row.custom_component_type) {
                    return {
                        filters: { name: "__none__" } // show empty list
                    };
                }

                return {
                    filters: {
                        item_group: row.custom_component_type  // filter items by Item Group
                    }
                };
            };
    }
});

// Clear link_part_number when item_group is changed (inside child table)
frappe.ui.form.on("Sales Order Item", {
    custom_component_type(frm, cdt, cdn) {
        frappe.model.set_value(cdt, cdn, "item_code", null);
    }
});

frappe.ui.form.on('Project', {

    refresh(frm) {
        frm.trigger("apply_hold_release");
    },

    hold_release(frm) {
        frm.trigger("apply_hold_release");
    },

    apply_hold_release(frm) {

        if (frm.doc.hold_release) {
            // Mark project as inactive / on hold
            frm.set_value("status", "On Hold");

            frappe.msgprint({
                title: __("Project On Hold"),
                message: __("This project will be hidden from selection until released."),
                indicator: "orange"
            });

        } else {
            // Release project
            frm.set_value("status", "Open");

            frappe.msgprint({
                title: __("Project Released"),
                message: __("This project is now visible for selection."),
                indicator: "green"
            });
        }
    }
});

frappe.ui.form.on('PRJ_SUB', {

    refresh(frm) {
        frm.trigger("apply_hold_release");
    },

    hold_and_release(frm) {
        frm.trigger("apply_hold_release");
    },

    apply_hold_release(frm) {

        if (frm.doc.hold_and_release) {

            // Put on hold
            frm.set_value("status", "Inactive");

            frappe.show_alert({
                message: __("PRJ_SUB is On Hold and hidden everywhere"),
                indicator: "orange"
            });

        } else {

            // Release
            frm.set_value("status", "Active");

            frappe.show_alert({
                message: __("PRJ_SUB is Released and visible"),
                indicator: "green"
            });
        }
    }
});

frappe.ui.form.on("SIV", {
    refresh(frm) {
        enforce_row_limit(frm);
    },

    table_bnpa_add(frm) {
        enforce_row_limit(frm);
    },

    table_bnpa_remove(frm) {
        enforce_row_limit(frm);
    }
});

function enforce_row_limit(frm) {
    const MAX_ROWS = 2;
    const count = frm.doc.table_bnpa?.length || 0;

    if (count >= MAX_ROWS) {
        frm.add_custom_css(`
            .form-grid[data-fieldname="table_bnpa"] .grid-add-row,
            .form-grid[data-fieldname="table_bnpa"] .grid-add-multiple-rows,
            .form-grid[data-fieldname="table_bnpa"] .btn-open-row {
                display: none !important;
            }
        `);
    } else {
        frm.add_custom_css(`
            .form-grid[data-fieldname="table_bnpa"] .grid-add-row,
            .form-grid[data-fieldname="table_bnpa"] .grid-add-multiple-rows,
            .form-grid[data-fieldname="table_bnpa"] .btn-open-row {
                display: inline-block !important;
            }
        `);
    }
}

frappe.ui.form.on("Purchase Order Item", {
    item_code(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (!row.item_code) return;

        frappe.call({
            method: "ursc_cms_app.api.get_last_po_cost",
            args: {
                item_code: row.item_code
            },
            callback(r) {
                if (r.message !== null) {
                    frappe.model.set_value(cdt, cdn, "rate", r.message);
                } else {
                    frappe.msgprint(
                        "No previous Purchase Order found. Please enter cost manually."
                    );
                }
            }
        });
    }
});

frappe.ui.form.on("SRN SPECIAL POSTING", {
    refresh(frm) {
        frm.set_query("program", function () {
            return {
                filters: [
                    ["Warehouse", "is_group", "=", 1],
                    ["Warehouse", "parent_warehouse", "in", ["ISITE - N", "URSC - N"]]
                ]
            };
        });
    }
});

//comp type + stock grade --> date codes
frappe.ui.form.on("Add BAN", {

    component_type(frm) {
        frm.trigger("load_date_codes");
    },

    stock(frm) {
        frm.trigger("load_date_codes");
    },

    load_date_codes(frm) {

        // reset date code
        frm.set_value("date_code", "");
        frm.set_df_property("date_code", "options", "");

        if (!frm.doc.component_type || !frm.doc.stock) return;

        frappe.call({
            method: "ursc_cms_app.item_api.get_date_codes_by_component_and_stock",
            args: {
                component_type: frm.doc.component_type,
                stock: frm.doc.stock
            },
            callback(r) {
                const rows = r.message || [];

                if (!rows.length) {
                    frappe.msgprint("No Date Codes found for selected Component Type and Stock Grade");
                    return;
                }

                // rows = [['DC001'], ['DC002']]
                const options = rows
                    .map(d => d[0])
                    .filter(Boolean)
                    .join("\n");

                frm.set_df_property("date_code", "options", options);
            }
        });
    }

});

frappe.ui.form.on("SRN SPECIAL POSTING", {

    refresh(frm) {
        // Make MDB Part No read-only in child table
        if (frm.fields_dict.table_wvxq) {
            frm.fields_dict.table_wvxq.grid.update_docfield_property(
                "mdb_part_no",
                "read_only",
                1
            );
        }
    }
});


frappe.ui.form.on("SRN SPECIAL POST TABLE", {

    basic_mdb(frm, cdt, cdn) {
        set_mdb_part_no(cdt, cdn);
    },

    quality_copy(frm, cdt, cdn) {
        set_mdb_part_no(cdt, cdn);
    }
});


// =======================================
// Helper: MDB Part No = Basic Part No + Quality
// =======================================
function set_mdb_part_no(cdt, cdn) {

    const row = locals[cdt][cdn];

    if (!row.basic_mdb || !row.quality_copy) {
        frappe.model.set_value(cdt, cdn, "mdb_part_no", "");
        return;
    }

    const mdb_part_no = `${row.basic_mdb}-${row.quality_copy}`;

    frappe.model.set_value(cdt, cdn, "mdb_part_no", mdb_part_no);
}

frappe.ui.form.on("PRJ_CARDS", {
    select_project(frm) {

        // Clear field if no project selected
        if (!frm.doc.select_project) {
            frm.set_df_property("custom_select_project_reference_name", "options", "");
            frm.set_value("project_ref_name", "");
            return;
        }

        // Fetch custom_select_project_reference_name from Project doctype
        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Project",
                name: frm.doc.select_project
            },
            callback: function (r) {
                if (r.message) {

                    let ref_options = r.message.custom_select_project_reference_name || "";

                    // Set options in Select field
                    frm.set_df_property(
                        "project_ref_name",
                        "options",
                        ref_options
                    );

                    // Clear previously selected value
                    frm.set_value("project_ref_name", "");
                }
            }
        });
    }
});

frappe.ui.form.on('Cross Reference', {
    refresh(frm) {
        // Wait for the form to be fully rendered
        setTimeout(() => {
            initializeComponentFilter(frm);
        }, 500);
    },

    component_type(frm) {
        // This event fires when component_type field changes
        if (frm.doc.component_type) {
            filterComponentsByType(frm, frm.doc.component_type);
        } else {
            clearFilter(frm);
        }
    }
});

// Store the component data
let allComponentsData = [];

// Initialize the component filter
function initializeComponentFilter(frm) {
    console.log('Initializing component filter for Cross Reference form...');

    // Get the table field
    const tableField = frm.get_field('table_ymoi');
    if (!tableField) {
        console.error('Table field "table_ymoi" not found');
        return;
    }

    // Extract data from the existing table rows in the form
    extractTableData(frm);

    // Add custom CSS for styling
    addCustomStyles();

    // If component_type field has a value, filter immediately
    if (frm.doc.component_type) {
        setTimeout(() => {
            filterComponentsByType(frm, frm.doc.component_type);
        }, 300);
    }
}

// Extract data from table rows in the form
function extractTableData(frm) {
    allComponentsData = [];

    if (frm.doc.table_ymoi && frm.doc.table_ymoi.length > 0) {
        frm.doc.table_ymoi.forEach((row, index) => {
            if (row.mdb_part_number) {
                allComponentsData.push({
                    idx: row.idx,
                    component_type: row.component_type || '',
                    mdb_part_number: row.mdb_part_number || '',
                    pcb_part_number: row.pcb_part_number || '',
                    date_code: row.date_code || '',
                    manufacturer: row.manufacturer || '',
                    cross_ref_part_number: row.cross_ref_part_number || '',
                    row_data: row
                });
            }
        });
    }

    console.log(`Extracted ${allComponentsData.length} components from form table`);
    return allComponentsData;
}

// Filter components by type
function filterComponentsByType(frm, selectedType) {
    if (!selectedType || selectedType.trim() === '') {
        clearFilter(frm);
        return;
    }

    // Filter data based on selected component type
    const filteredData = allComponentsData.filter(item => {
        // Case-insensitive exact match
        return item.component_type && 
               item.component_type.toLowerCase() === selectedType.toLowerCase();
    });

    console.log(`Filtered ${filteredData.length} items for type: ${selectedType}`);

    // Update the table to show only filtered items
    updateTableWithFilteredData(frm, filteredData);
}

// Update the table with filtered data
function updateTableWithFilteredData(frm, filteredData) {
    // Clear the current table
    frm.clear_table('table_ymoi');

    if (filteredData.length === 0) {
        // Add a "no data" row
        frm.add_child('table_ymoi', {
            mdb_part_number: 'No components found for selected type'
        });
        frm.refresh_field('table_ymoi');
        return;
    }

    // Add filtered rows back to the table
    filteredData.forEach(item => {
        frm.add_child('table_ymoi', {
            component_type: item.component_type,
            mdb_part_number: item.mdb_part_number,
            pcb_part_number: item.pcb_part_number,
            date_code: item.date_code,
            manufacturer: item.manufacturer,
            cross_ref_part_number: item.cross_ref_part_number
        });
    });

    frm.refresh_field('table_ymoi');

    // Add click handlers to MDB Part Number links
    addPartNumberClickHandlers(frm);
}

// Clear filter and show all data
function clearFilter(frm) {
    // Clear the table
    frm.clear_table('table_ymoi');

    // Add all data back
    allComponentsData.forEach(item => {
        frm.add_child('table_ymoi', {
            component_type: item.component_type,
            mdb_part_number: item.mdb_part_number,
            pcb_part_number: item.pcb_part_number,
            date_code: item.date_code,
            manufacturer: item.manufacturer,
            cross_ref_part_number: item.cross_ref_part_number
        });
    });

    frm.refresh_field('table_ymoi');

    // Add click handlers
    addPartNumberClickHandlers(frm);
}

// Add click handlers to MDB Part Number links
function addPartNumberClickHandlers(frm) {
    // Wait for the table to be rendered
    setTimeout(() => {
        const tableRows = document.querySelectorAll('[data-fieldname="table_ymoi"] tbody tr');

        tableRows.forEach(row => {
            const mdbPartCell = row.querySelector('td[data-fieldname="mdb_part_number"]');
            if (mdbPartCell) {
                const link = mdbPartCell.querySelector('a');
                if (link) {
                    // Remove existing listeners to avoid duplicates
                    const newLink = link.cloneNode(true);
                    mdbPartCell.replaceChild(newLink, link);

                    newLink.addEventListener('click', (e) => {
                        e.preventDefault();
                        const partNumber = newLink.textContent.trim();
                        showPartDetails(frm, partNumber);
                    });
                } else {
                    // Convert text to link if not already a link
                    const text = mdbPartCell.textContent.trim();
                    if (text && text !== 'No components found for selected type') {
                        const link = document.createElement('a');
                        link.href = '#';
                        link.textContent = text;
                        link.className = 'mdb-part-link';
                        link.style.cssText = 'color: #007bff; cursor: pointer; text-decoration: none;';
                        link.addEventListener('click', (e) => {
                            e.preventDefault();
                            showPartDetails(frm, text);
                        });
                        mdbPartCell.innerHTML = '';
                        mdbPartCell.appendChild(link);
                    }
                }
            }
        });
    }, 100);
}

// Show part details
function showPartDetails(frm, partNumber) {
    // Find the part in our data
    const part = allComponentsData.find(item => item.mdb_part_number === partNumber);

    if (part) {
        frappe.msgprint({
            title: 'Part Details',
            message: `
                <div style="padding: 10px;">
                    <p><strong>MDB Part Number:</strong> ${part.mdb_part_number}</p>
                    <p><strong>Component Type:</strong> ${part.component_type}</p>
                    <p><strong>PCB Part Number:</strong> ${part.pcb_part_number}</p>
                    <p><strong>Date Code:</strong> ${part.date_code}</p>
                    <p><strong>Manufacturer:</strong> ${part.manufacturer}</p>
                    <p><strong>Cross Ref Part Number:</strong> ${part.cross_ref_part_number}</p>
                </div>
            `,
            indicator: 'blue'
        });
    } else {
        frappe.msgprint({
            title: 'Part Not Found',
            message: `Could not find details for part: ${partNumber}`,
            indicator: 'red'
        });
    }
}

// Add custom CSS styles
function addCustomStyles() {
    if (!document.getElementById('component-filter-styles')) {
        const style = document.createElement('style');
        style.id = 'component-filter-styles';
        style.textContent = `
            .mdb-part-link {
                color: #007bff !important;
                text-decoration: none !important;
                cursor: pointer !important;
                font-weight: 500 !important;
                padding: 2px 4px !important;
                border-radius: 3px !important;
                transition: all 0.2s !important;
            }

            .mdb-part-link:hover {
                color: #0056b3 !important;
                text-decoration: underline !important;
                background-color: #f0f8ff !important;
            }

            /* Highlight the component type field when filtered */
            [data-fieldname="component_type"].filtered {
                background-color: #e7f3ff !important;
                border-color: #007bff !important;
            }

            /* Style for the table */
            [data-fieldname="table_ymoi"] table {
                width: 100% !important;
            }

            [data-fieldname="table_ymoi"] td {
                padding: 8px !important;
                vertical-align: middle !important;
            }
        `;
        document.head.appendChild(style);
    }
}

// Refresh the filter when new rows are added
frappe.ui.form.on('Cross Reference Item', {
    form_render(frm, cdt, cdn) {
        // This fires when a table row is rendered
        setTimeout(() => {
            if (frm.doc.component_type) {
                extractTableData(frm);
                filterComponentsByType(frm, frm.doc.component_type);
            }
        }, 200);
    }
});

// Utility function to get all unique component types
function getAvailableComponentTypes(frm) {
    const types = new Set();

    if (frm.doc.table_ymoi && frm.doc.table_ymoi.length > 0) {
        frm.doc.table_ymoi.forEach(row => {
            if (row.component_type) {
                types.add(row.component_type);
            }
        });
    }

    return Array.from(types);
}

// Optional: Add a button to refresh the filter
function addRefreshButton(frm) {
    frm.add_custom_button(__('Refresh Filter'), function() {
        extractTableData(frm);
        if (frm.doc.component_type) {
            filterComponentsByType(frm, frm.doc.component_type);
            frappe.show_alert({
                message: __('Filter refreshed'),
                indicator: 'green'
            });
        }
    }, __('Tools'));
}

