frappe.ui.form.on("SIV req for SRN Table", {
    async link_part_no(frm, cdt, cdn) {
        const row = locals[cdt][cdn];

        // 🔹 Reset the Basic MDB field
        frappe.model.set_value(cdt, cdn, "basic_mdb", "");

        // If no Item is selected, just reset and return
        if (!row.link_part_no) {
            frappe.meta.get_docfield("SIV req for SRN Table", "basic_mdb", frm.doc.name).options = [];
            frm.refresh_field("table_hxvq"); // <-- replace with your parent table fieldname if different
            return;
        }

        try {
            // 🔹 Fetch Item document (including its child table)
            const { message: item_doc } = await frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Item",
                    name: row.link_part_no,
                },
            });

            // 🔹 If no Basic MDB entries exist
            if (!item_doc || !item_doc.custom_srv_number || item_doc.custom_srv_number.length === 0) {
                frappe.msgprint(`⚠️ No Basic MDBs found for this Item.`);
                frappe.meta.get_docfield("SIV req for SRN Table", "basic_mdb", frm.doc.name).options = [];
                frm.refresh_field("table_hxvq");
                return;
            }

            // 🔹 Extract Basic MDB entries
            const mdb_list = item_doc.custom_srv_number
                .map(d => d.enter_basic_mdb)
                .filter(Boolean);

            if (mdb_list.length === 0) {
                frappe.msgprint(`⚠️ No valid MDB entries found for this Item.`);
                return;
            }

            // 🔹 Dynamically set dropdown options for the current row (this is key fix!)
            const df = frappe.meta.get_docfield("SIV req for SRN Table", "basic_mdb", frm.doc.name);
            df.options = ["", ...mdb_list].join("\n");

            // Force-refresh the grid field itself to show options
            const grid = frm.fields_dict["table_hxvq"].grid; // <-- replace with your parent table fieldname
            const field = grid.grid_rows_by_docname[row.name].get_field("basic_mdb");
            field.df.options = ["", ...mdb_list].join("\n");
            field.refresh();

            // Auto-select first MDB
            frappe.model.set_value(cdt, cdn, "basic_mdb", mdb_list[0]);

            // ✅ Show alert (still working)
            frappe.show_alert({
                message: `Loaded ${mdb_list.length} MDB(s): ${mdb_list.join(", ")}`,
                indicator: "green",
            });

        } catch (error) {
            console.error(error);
            frappe.msgprint("❌ Error fetching MDBs from selected Item.");
        }
    },
});

frappe.ui.form.on("Radiation_Shield_Approve", {
    // Trigger when RAD Test ID is selected
    rad_test_id(frm) {
        if (!frm.doc.rad_test_id) return;

        frappe.db.get_doc("Radiation_Test_Data_Entry", frm.doc.rad_test_id)
            .then(test_doc => {
                // Clear previous rows
                frm.clear_table("table_appr");

                // Fill parent fields
                frm.set_value("project", test_doc.project);
                frm.set_value("subsystem", test_doc.subsystem);
                frm.set_value("package", test_doc.package);
                frm.set_value("card", test_doc.card);

                // Get the child table data from the Test Data Entry
                const test_items = test_doc.table_fnlz || [];

                if (!test_items.length) {
                    frappe.msgprint({
                        title: "No Data Found",
                        message: "⚠️ No component test data found for this RAD Test ID.",
                        indicator: "red"
                    });
                    frm.refresh_field("table_appr");
                    return;
                }

                // Process and auto-approve components
                test_items.forEach(item => {
                    let row = frm.add_child("table_appr");
                    row.type = item.type || "";
                    row.symbol = item.symbol || "";
                    row.part_number = item.part_number || "";
                    row.mount_on = item.mount_on || "";
                    row.tid_hardness = item.tid_hardness_krad || 0;
                    row.rdm = item.rdm_ || 0;
                    row.radiation_shielding = item.radiation_shielding || "";
                    row.tid_level = item.tid_dose_krad || 0;
                    row.component_id = frm.doc.rad_test_id;
                    row.link_id = item.link_id || "";
                    row.pstyle = item.package || "";
                    row.count = 1;

                    // 🧠 Auto Approval Logic
                    if (row.tid_hardness >= 200 && row.rdm <= 10) {
                        row.approval_status = "Approved";
                        frappe.msgprint({
                            title: "Component Accepted",
                            message: `✅ Component <b>${row.part_number || row.type}</b> has been <b>Accepted</b>.<br>
                                      <b>TID:</b> ${row.tid_hardness} krad<br>
                                      <b>RDM:</b> ${row.rdm} %`,
                            indicator: "green"
                        });
                    } 
                    else if (row.tid_hardness >= 100 && row.rdm <= 15) {
                        row.approval_status = "Pending";
                        frappe.msgprint({
                            title: "Component Pending Review",
                            message: `🕓 Component <b>${row.part_number || row.type}</b> requires further <b>Review</b>.<br>
                                      <b>TID:</b> ${row.tid_hardness} krad<br>
                                      <b>RDM:</b> ${row.rdm} %`,
                            indicator: "orange"
                        });
                    } 
                    else {
                        row.approval_status = "Rejected";
                        frappe.msgprint({
                            title: "Component Rejected",
                            message: `❌ Component <b>${row.part_number || row.type}</b> has been <b>Rejected</b>.<br>
                                      <b>TID:</b> ${row.tid_hardness} krad<br>
                                      <b>RDM:</b> ${row.rdm} %`,
                            indicator: "red"
                        });
                    }
                });

                frm.refresh_field("table_appr");

                // Final summary popup
                frappe.msgprint({
                    title: "Evaluation Complete",
                    message: `✅ All ${test_items.length} component(s) have been evaluated successfully.`,
                    indicator: "green"
                });
            })
            .catch(err => {
                console.error("Error fetching Radiation Test Data:", err);
                frappe.msgprint({
                    title: "Error",
                    message: "❌ Failed to fetch test data. Please check the console for details.",
                    indicator: "red"
                });
            });
    }
});

frappe.ui.form.on('Radiation_Test_Data_Entry', {
    refresh(frm) {
        // Run only when creating a new record
        if (frm.is_new()) {
            // 1️⃣ Auto-fill today's date
            if (!frm.doc.test_date) {
                frm.set_value("test_date", frappe.datetime.get_today());
            }

            // 2️⃣ Auto-generate RAD Test ID
            if (!frm.doc.rad_test_id) {
                const today = frappe.datetime.get_today().replaceAll("-", "");
                const randomNum = Math.floor(1000 + Math.random() * 9000);
                frm.set_value("rad_test_id", `RAD-${today}-${randomNum}`);
            }
        }

        // 3️⃣ Make Test ID read-only after generation
        if (frm.doc.rad_test_id) {
            frm.set_df_property("rad_test_id", "read_only", 1);
