        const doctype_name = "Radiation_Shield_Approve";

        // 🔹 Fetch record by matching field value, not document name
        frappe.db.get_list(doctype_name, {
            fields: ["name", "project", "subsystem", "package", "card"],
            filters: { rad_test_id: frm.doc.rad_test_id },
            limit: 1
        }).then(res => {
            if (!res.length) {
                frappe.msgprint({
                    title: "❌ Error",
                    message: `No record found in <b>${doctype_name}</b> with RAD Test ID <b>${frm.doc.rad_test_id}</b>.`,
