                });
                return;
            }

            const approve_name = res[0].name;

            // ✅ Now get full document with child table
            frappe.db.get_doc(doctype_name, approve_name).then(approve_doc => {
                // ✅ Fill parent fields
                frm.set_value("project", approve_doc.project || "");
                frm.set_value("subsystem", approve_doc.subsystem || "");
                frm.set_value("package", approve_doc.package || "");
                frm.set_value("card", approve_doc.card || "");

