// 🔧 Helper function
async function set_custom_srv_number_from_item(frm, cdt, cdn, from_auto_fetch = false) {
    const row = locals[cdt][cdn];
    if (!row.item_code) return;

    try {
        // Fetch Item document including child table
        const { message: item_doc } = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Item",
                name: row.item_code,
            },
        });

        if (!item_doc || !item_doc.custom_srv_number?.length) return;

        // Extract list of enter_basic_mdb values
        const base_parts = item_doc.custom_srv_number.map(d => d.enter_basic_mdb);

        // Update dropdown options dynamically
        frm.fields_dict.items.grid.update_docfield_property(
            "custom_srv_number",
            "options",
            ["", ...base_parts]
        );

        // ✅ If item fetched automatically and field blank, set the first saved enter_basic_mdb
        if (from_auto_fetch && (!row.custom_srv_number || row.custom_srv_number === "")) {
            frappe.model.set_value(cdt, cdn, "custom_srv_number", base_parts[0] || "");
        }

        // ✅ If manually selected and empty, also set first saved enter_basic_mdb
        if (!from_auto_fetch && (!row.custom_srv_number || row.custom_srv_number === "")) {
            frappe.model.set_value(cdt, cdn, "custom_srv_number", base_parts[0] || "");
        }

    } catch (err) {
        console.error("⚠️ Error fetching Item:", err);
        frappe.msgprint("⚠️ Unable to fetch Base Part Number from Item.");
    }
}

frappe.ui.form.on("PRJ_CARDS", {
  refresh(frm) {
    if (!frm.fields_dict.add_card_html) return;

    // --- Build Add Card Button ---
    const $w = frm.fields_dict.add_card_html.$wrapper;
    $w.empty().html(`
   <div>
  <button class="btn btn-primary" id="add-card-btn">
      ADD CARD
  </button>
</div>

    `);

    // --- Helper: Get Alphabet Sequence
    function getAlphaSequence(index, isUpper) {
      const letters = isUpper ? "ABCDEFGHIJKLMNOPQRSTUVWXYZ" : "abcdefghijklmnopqrstuvwxyz";
      let seq = "";
      while (index >= 0) {
        seq = letters[index % 26] + seq;
        index = Math.floor(index / 26) - 1;
      }
      return seq;
    }

    // --- Helper: Build Card Name
    function buildCardName(base, suffix, i) {
      if (!suffix) return `${base}${i}`;
      if (/^[A-Za-z]+$/.test(suffix)) {
        const isUpper = suffix === suffix.toUpperCase();
        return `${base}${getAlphaSequence(i - 1, isUpper)}`;
      }
      if (/[A-Za-z]+$/.test(suffix)) {
        const match = suffix.match(/([A-Za-z]+)$/);
        const letterPart = match ? match[1] : "";
        const prefix = suffix.slice(0, suffix.length - letterPart.length);
        const isUpper = letterPart === letterPart.toUpperCase();
        return `${base}${prefix}${getAlphaSequence(i - 1, isUpper)}`;
      }
      return `${base}${suffix}${i}`;
    }

    // --- Sync from Child Table
    frm.created_cards = (frm.doc.table_aahd || []).map(row => ({
      name: row.card_name,
      status: row.status || "Initial",
    }));

    // --- Sync to Child Table
    function syncToChildTable() {
      frm.clear_table("table_aahd");
      frm.created_cards.forEach(c => {
        const row = frm.add_child("table_aahd");
        row.card_name = c.name;
        row.status = c.status;
      });
      frm.refresh_field("table_aahd");
      renderActionButtons();
    }

    // --- Add Card Click ---
    $w.find("#add-card-btn").off("click").on("click", function () {
      if (frm.doc.select_card === "New") {
        const cardName = (frm.doc.card_names || "").trim();
        if (!cardName) {
          frappe.msgprint("Please enter Card Name.");
          return;
        }
        frm.created_cards.push({ name: cardName, status: "Initial" });
        frm.set_value("card_names", "");
        syncToChildTable();
        frappe.show_alert({ message: "Card Added", indicator: "green" });

      } else if (frm.doc.select_card === "Select From ECard") {
        const base = (frm.doc.ecad_card_name || "").trim();
        const count = parseInt(frm.doc.card_name || 0);
        const suffix = (frm.doc.card_count_suffix || "").trim();

        if (!base || !count) {
          frappe.msgprint("Please fill ECAD Card Name and Card Count.");
          return;
        }

        for (let i = 1; i <= count; i++) {
          const name = buildCardName(base, suffix, i);
          if (!frm.created_cards.some(c => c.name === name)) {
            frm.created_cards.push({ name, status: "Initial" });
          }
        }
        syncToChildTable();
        frappe.show_alert({ message: `${count} Card(s) Generated`, indicator: "green" });
      } else {
        frappe.msgprint("Please select a valid Card Type (New / Select From ECard).");
      }
    });

    // --- Render Action Buttons ---
    function renderActionButtons() {
      setTimeout(() => {
        (frm.fields_dict.table_aahd?.grid?.grid_rows || []).forEach((rowObj, i) => {
          const $cell = $(rowObj.grid_form?.fields_dict?.action?.$wrapper);
          if (!$cell.length) return;

          const status = rowObj.doc.status || "Initial";

          // Highlight based on status
          const colorClass =
            status === "Approved" ? "success" :
            status === "Rejected" ? "danger" :
            "secondary";

          $cell.empty().html(`
            <div style="text-align:center;">
              <button type="button" class="btn btn-xs btn-success child-action" data-idx="${i}" data-action="approve" title="Approve">✔</button>
              <button type="button" class="btn btn-xs btn-warning child-action" data-idx="${i}" data-action="initial" title="Reset">↩</button>
              <button type="button" class="btn btn-xs btn-danger child-action" data-idx="${i}" data-action="reject" title="Reject">✖</button>
              <div style="margin-top:4px;">
                <span class="badge bg-${colorClass}" style="font-size:10px;">${status}</span>
              </div>
            </div>
          `);
        });
      }, 300);
    }

    renderActionButtons();

    // --- Handle Child Button Clicks ---
    $(document).off("click", ".child-action").on("click", ".child-action", function () {
      const idx = $(this).data("idx");
      const action = $(this).data("action");
      const row = frm.doc.table_aahd[idx];
      if (!row) return;

      // Update status
      switch (action) {
        case "approve":
          row.status = "Approved";
          break;
        case "reject":
          row.status = "Rejected";
          break;
        case "initial":
          row.status = "Initial";
          break;
      }

      frm.refresh_field("table_aahd");
      renderActionButtons();
    });

    // --- Toggle Fields based on Selection
    frm.toggle_display("card_names", frm.doc.select_card === "New");
    frm.toggle_display("ecad_card_name", frm.doc.select_card === "Select From ECard");
    frm.toggle_display("card_name", frm.doc.select_card === "Select From ECard");
    frm.toggle_display("card_count_suffix", frm.doc.select_card === "Select From ECard");
  },

  select_card(frm) {
    frm.toggle_display("card_names", frm.doc.select_card === "New");
    frm.toggle_display("ecad_card_name", frm.doc.select_card === "Select From ECard");
    frm.toggle_display("card_name", frm.doc.select_card === "Select From ECard");
    frm.toggle_display("card_count_suffix", frm.doc.select_card === "Select From ECard");
  }
});

