// ============================================================
// Load all Purchase Orders (active + inactive)
// ============================================================
function load_purchase_orders(frm) {
    const wrapper = frm.fields_dict.html_table.$wrapper;

    // ✅ Remove previous content and event handlers
    wrapper.off(); // detaches old click/change handlers
    wrapper.empty().html("<p class='text-muted mt-2'>Loading all Purchase Orders...</p>");

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Purchase Order",
            filters: [["docstatus", "=", 1]],
            fields: ["name", "supplier", "transaction_date", "status", "custom_po_flag"],
            limit_page_length: 200,
            ignore_permissions: 1
        },
        callback: function (r) {
            const pos = r.message || [];
            if (!pos.length) {
                wrapper.html("<p class='text-muted'>No Purchase Orders found.</p>");
                return;
            }

            // --- Build Table ---
            let html = `
                <div style="margin-bottom:12px;">
                    <input id="po-search" type="text" class="form-control"
                        placeholder="🔍 Search by PO Number, Supplier, or Status..."/>
                </div>
                <div style="max-height:420px; overflow-y:auto; border-radius:10px;
                    box-shadow:0 1px 8px rgba(0,0,0,0.08); background:#ffffff;">
                    <table class="table table-hover table-sm mb-0" id="po-table">
                        <thead style="position:sticky; top:0; background:#1e3a8a; color:white;">
                            <tr>
                                <th style="width:40px;">✔</th>
                                <th>PO Number</th>
                                <th>Supplier</th>
                                <th>Date</th>
                                <th>Status</th>
                                <th>Flag</th>
                                <th style="width:90px;">Action</th>
                            </tr>
                        </thead>
                        <tbody>
            `;

            pos.forEach(po => {
                const flagColor = po.custom_po_flag ? "success" : "danger";
                const rowBg = po.custom_po_flag ? "#ecfdf5" : "#fef2f2";

                html += `
                    <tr class="po-row" data-po="${po.name}"
                        style="transition:background-color 0.2s ease; background:${rowBg};">
                        <td><input type="checkbox" class="po-select" data-po="${po.name}"></td>
                        <td><b>${po.name}</b></td>
                        <td>${po.supplier || ""}</td>
                        <td>${frappe.datetime.str_to_user(po.transaction_date)}</td>
                        <td><span class="badge badge-info">${po.status}</span></td>
                        <td><span class="badge badge-${flagColor}">${po.custom_po_flag}</span></td>
                        <td><button class="btn btn-sm btn-outline-primary view-items" data-po="${po.name}">
                            View Items</button></td>
                    </tr>`;
            });

            html += `</tbody></table></div>`;
            wrapper.html(html);

            // ✅ Re-bind handlers safely after clearing old ones

            // --- Search Filter ---
            wrapper.find("#po-search").on("keyup", function () {
                const val = $(this).val().toLowerCase();
                $("#po-table tbody tr").filter(function () {
                    $(this).toggle($(this).text().toLowerCase().indexOf(val) > -1);
                });
            });

            // --- Checkbox Tracking ---
            wrapper.on("change", ".po-select", function () {
                const selected = [];
                wrapper.find(".po-select:checked").each(function () {
                    selected.push($(this).data("po"));
                });
                frm.set_value("po_list", selected.join(","));
                frm.dirty();
            });

            // --- View Items Toggle ---
            wrapper.on("click", ".view-items", function () {
                const po_name = $(this).data("po");
                const current_row = $(this).closest("tr");
                const existing_child = wrapper.find(`#items-${po_name}`);

                // collapse if open
                if (existing_child.length) {
                    existing_child.remove();
                    $(this).removeClass("btn-secondary").addClass("btn-outline-primary");
                    return;
                }

                // close all other child rows
                wrapper.find("tr.child-row").remove();
                wrapper.find(".view-items").removeClass("btn-secondary").addClass("btn-outline-primary");

                $(this).removeClass("btn-outline-primary").addClass("btn-secondary");
                $(this).prop("disabled", true);

                frappe.call({
                    method: "ursc_cms_app.api.get_po_items",
                    args: { po_name },
                    callback: function (r) {
                        $(this).prop("disabled", false);
                        const rows = r.message || [];
                        if (!rows.length) return;

                        let items_html = `
                            <tr class="child-row" id="items-${po_name}">
                                <td colspan="7">
                                    <div style="max-height:260px; overflow-y:auto;">
                                        <table class="table table-bordered table-sm mb-0"
                                            style="background:#f8fafc; border-radius:8px;">
                                            <thead style="position:sticky; top:0; background:#2563eb; color:white;">
                                                <tr>
                                                    <th style="width:40px;">✔</th>
                                                    <th>Item Code</th>
                                                    <th>Item Name</th>
                                                    <th>Short Closing Qty</th>
                                                    <th>PO Flag</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                        `;

                        rows.forEach(it => {
                            const itemBg = it.custom_po_flag ? "#e6fffa" : "#fff7ed";
                            const badgeClass = it.custom_po_flag ? "success" : "danger";
                            items_html += `
                                <tr style="background:${itemBg};">
                                    <td><input type="checkbox" class="item-select"
                                        data-item="${it.name}" data-po="${po_name}"></td>
                                    <td><b>${it.item_code}</b></td>
                                    <td>${it.item_name}</td>
                                    <td>${it.qty}</td>
                                    <td><span class="badge badge-${badgeClass}">${it.custom_po_flag}</span></td>
                                </tr>`;
                        });

                        items_html += `</tbody></table></div></td></tr>`;
                        current_row.after(items_html);
                    }.bind(this)
                });
            });
        }
    });
}


// ============================================================
// Process Invalidate / Validate Action
// ============================================================
function process_selection(frm, action_type) {
    const wrapper = frm.fields_dict.html_table.$wrapper;
    const selected_pos = [];
    const selected_items = [];

    wrapper.find(".po-select:checked").each(function () {
        selected_pos.push($(this).data("po"));
    });
    wrapper.find(".item-select:checked").each(function () {
        selected_items.push($(this).data("item"));
    });

    if (!selected_pos.length && !selected_items.length) {
        frappe.msgprint("Please select at least one Purchase Order or Item.");
        return;
    }

    // --- Filter out already processed ones ---
    const filtered_pos = [];
    const filtered_items = [];

    selected_pos.forEach(po => {
        const row = wrapper.find(`tr[data-po='${po}']`);
        const flag = row.find(".badge-success").length ? 1 : 0;
        if ((action_type === "invalidate" && flag === 1) ||
            (action_type === "validate" && flag === 0)) {
            filtered_pos.push(po);
        }
    });

    selected_items.forEach(item => {
        const row = wrapper.find(`.item-select[data-item='${item}']`).closest("tr");
        const flag = row.find(".badge-success").length ? 1 : 0;
        if ((action_type === "invalidate" && flag === 1) ||
            (action_type === "validate" && flag === 0)) {
            filtered_items.push(item);
        }
    });

    const skipped = (selected_pos.length - filtered_pos.length) +
                    (selected_items.length - filtered_items.length);
    if (skipped > 0) {
        frappe.show_alert({
            message: `${skipped} record(s) skipped: already ${action_type === "invalidate" ? "invalidated" : "validated"}.`,
            indicator: "yellow"
        });
    }

    if (!filtered_pos.length && !filtered_items.length) {
        frappe.msgprint(`No eligible records to ${action_type}.`);
        return;
    }

    frappe.call({
        method: "ursc_cms_app.api.invalidate_po_items",
        args: {
            parent_pos: JSON.stringify(filtered_pos),
            item_names: JSON.stringify(filtered_items),
            action_type
        },
        callback: function (r) {
            const msg = r.message?.message || `${action_type} completed successfully.`;
            frappe.show_alert({
                message: msg,
                indicator: action_type === "invalidate" ? "orange" : "green"
            });

            frm.set_value("action_type", action_type === "invalidate" ? "Invalidate" : "Validate");
            frm.set_value("po_list", filtered_pos.join(","));
            frm.set_value("item_ref_list", filtered_items.join(","));
            frm.save();

            filtered_pos.forEach(po => {
                wrapper.find(`tr[data-po='${po}']`).fadeOut(400, function () {
                    $(this).remove();
                });
                wrapper.find(`#items-${po}`).remove();
            });
        }
    });
}

