frappe.ui.form.on("SIV Request for SRN", {
    refresh(frm) {
        // ----------------------------------------------------------------
        // 🔹 Auto-fill request date when new
        // ----------------------------------------------------------------
        if (frm.is_new()) {
            if (!frm.doc.request_date) {
                frm.set_value("request_date", frappe.datetime.get_today());
            }

            // 🔹 Auto-generate a temporary unique request number before save
            if (!frm.doc.request_no) {
                let randomNum = Math.floor(10000 + Math.random() * 90000);
                frm.set_value("request_no", "REQ-" + randomNum);
            }
        }

        // ----------------------------------------------------------------
        // 🔹 WAREHOUSE SELECTION LOGIC (3-Level)
        // ----------------------------------------------------------------

        // 1️⃣ STORE FIELD → Show children of "STORE - N" (e.g. ISITE - N, URSC - N)
        frm.set_query("store", function () {
            return {
                filters: {
                    parent_warehouse: "STORE - N",
                    is_group: 1
                }
            };
        });

        // 2️⃣ PROGRAM FIELD → Show children of selected Store
        frm.set_query("program", function () {
            if (frm.doc.store) {
                return {
                    filters: {
                        parent_warehouse: frm.doc.store,
                        is_group: 1
                    }
                };
            } else {
                frappe.msgprint("Please select a Store first.");
                return { filters: { name: "No Warehouse" } };
            }
        });

        // 3️⃣ STOCK FIELD → Show children of selected Program
        frm.set_query("stock", function () {
            if (frm.doc.program) {
                return {
                    filters: {
                        parent_warehouse: frm.doc.program,
                        is_group: 0
                    }
                };
            } else {
                frappe.msgprint("Please select a Program first.");
                return { filters: { name: "No Warehouse" } };
            }
        });

        // 🔹 Clear dependent fields when parent warehouse changes
        frm.fields_dict.store.df.onchange = () => {
            frm.set_value("program", "");
            frm.set_value("stock", "");
        };
        frm.fields_dict.program.df.onchange = () => {
            frm.set_value("stock", "");
        };

        // ----------------------------------------------------------------
        // 🔹 WORKFLOW + APPROVAL LOGIC
        // ----------------------------------------------------------------
        if (frm.doc.workflow_state === "Pending Approval" && frappe.user.has_role("Stock Manager")) {
            frm.set_read_only();
            frm.enable_save(); // keeps Approve/Reject buttons active
        }

        // 🟢 Optional: Sync status field with workflow_state
        if (frm.fields_dict.status && frm.doc.workflow_state && frm.doc.status !== frm.doc.workflow_state) {
            frm.set_value("status", frm.doc.workflow_state);
        }

        // Show alert for pending approvals
        show_pending_approvals_alert();
    },

    // ----------------------------------------------------------------
    // 🔹 Fetch Items Based on Request Type (TO-SCR or Flight G1)
    // ----------------------------------------------------------------

});

// ----------------------------------------------------------------
// 🔹 Function: Show Pending Approvals Alert for Stock Manager
// ----------------------------------------------------------------
function show_pending_approvals_alert() {
    if (frappe.user.has_role("Stock Manager")) {
        frappe.db.count("SIV Request for SRN", {
            filters: { status: "Pending Approval" }
        }).then(count => {
            if (count > 0) {
                const message = `🔴 You have ${count} SIV Request(s) pending for approval. Click to review.`;

                const alert = frappe.show_alert({
                    message: message,
                    indicator: "red"
                }, 10);

                alert.$toast.find(".frappe-toast-message")
                    .css("cursor", "pointer")
                    .on("click", () => {
                        frappe.set_route("List", "SIV Request for SRN", {
                            "status": "Pending Approval"
                        });
                    });
            }
        });
    }
}

frappe.ui.form.on("SIV Req Table", {
    component_code(frm, cdt, cdn) {
        let d = locals[cdt][cdn];

        // Ensure parent form and stock are selected
        if (!frm.doc || !frm.doc.stock) {
            frappe.msgprint("Please select a Stock warehouse in the parent form first.");
            frappe.model.set_value(cdt, cdn, "component_code", "");
            return;
        }

        // Dynamic query for component_code field
        frm.fields_dict.items.grid.get_field("component_code").get_query = function(doc, cdt, cdn) {
            const warehouse = frm.doc.stock;

            // 🟡 CASE 1: If warehouse is Flight-G1 → show only items older than 5 years
            if (warehouse.toLowerCase().includes("flight-g1")) {
                return {
                    query: "ursc_cms_app.ursc_cms_app.doctype.siv_req_table.siv_req_table.get_old_flight_items",
                    filters: {
                        warehouse: warehouse
                    }
                };
            }

            // 🟢 CASE 2: For all other warehouses → show all items in that warehouse
            return {
                query: "erpnext.controllers.queries.item_query",
                filters: {
                    warehouse: warehouse
                }
            };
        };
    }
});

