frappe.ui.form.on("Item", {
    refresh: function(frm) {

        frm.add_custom_button("Stock Summary Report", function() {
            if(!frm.doc.item_code) {
                frappe.msgprint("Please select an Item first.");
                return;
            }

            // Get linked Project name
            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Project",
                    fieldname: ["project_name"],
                    filters: { name: frm.doc.project }
                },
                callback: function(project_res) {
                    let project_name = project_res.message ? project_res.message.project_name : "-";

                    // Get all batches for the item
                    frappe.call({
                        method: "frappe.client.get_list",
                        args: {
                            doctype: "Batch",
                            filters: { item: frm.doc.item_code },
                            fields: ["name", "batch_id", "expiry_date"]
                        },
                        callback: function(batch_res) {
                            let batches = batch_res.message || [];

                            // Get stock ledger entries for qty and valuation rate
                            frappe.call({
                                method: "frappe.client.get_list",
                                args: {
                                    doctype: "Stock Ledger Entry",
                                    filters: { item_code: frm.doc.item_code },
                                    fields: ["batch_no", "actual_qty", "valuation_rate"]
                                },
                                callback: function(sle_res) {
                                    let sle = sle_res.message || [];
                                    let batch_qty_map = {};
                                    let batch_rate_map = {};

                                    sle.forEach(e => {
                                        if(e.batch_no) {
                                            batch_qty_map[e.batch_no] = (batch_qty_map[e.batch_no] || 0) + e.actual_qty;
                                            batch_rate_map[e.batch_no] = e.valuation_rate;
                                        }
                                    });

                                    // Build HTML for portrait A4 report
                                    let html = `
                                        <html>
                                        <head>
                                            <title>Stock Summary Report</title>
                                            <style>
                                                @media print {
                                                    @page { size: A4 portrait; margin: 20mm; }
                                                }
                                                body { font-family: Arial, sans-serif; margin: 20px; }
                                                h2 { text-align: center; }
                                                table { width: 100%; border-collapse: collapse; margin-top: 20px; }
                                                th, td { border: 1px solid #000; padding: 6px; text-align: left; }
                                                th { background-color: #f2f2f2; }
                                                tr:nth-child(even) { background-color: #f9f9f9; }
                                                .total-row td { font-weight: bold; text-align: right; }
                                                .print-btn { display: block; margin: 30px auto 0; padding: 8px 16px; font-size: 14px; }
                                            </style>
                                        </head>
                                        <body>
                                            <h2>Stock Summary Report</h2>
                                            <p><b>Project:</b> ${project_name}</p>
                                            <p><b>Item Code:</b> ${frm.doc.item_code} &nbsp;&nbsp; <b>Item Name:</b> ${frm.doc.item_name}</p>
                                            <table>
                                                <tr>
                                                    <th>Batch ID</th>
                                                    <th>Expiry Date</th>
                                                    <th>Qty</th>
                                                    <th>Valuation Rate</th>
                                                    <th>Amount</th>
                                                </tr>
                                    `;

                                    let total_qty = 0;
                                    let total_amount = 0;

                                    batches.forEach(b => {
                                        let qty = batch_qty_map[b.name] || 0;
                                        let rate = batch_rate_map[b.name] || 0;
                                        let amount = qty * rate;

                                        html += `
                                            <tr>
                                                <td>${b.batch_id}</td>
                                                <td>${b.expiry_date || '-'}</td>
                                                <td>${qty}</td>
                                                <td>${rate.toFixed(2)}</td>
                                                <td>${amount.toFixed(2)}</td>
                                            </tr>
                                        `;

                                        total_qty += qty;
                                        total_amount += amount;
                                    });

                                    html += `
                                        <tr class="total-row">
                                            <td colspan="2" style="text-align:right">Total</td>
                                            <td>${total_qty}</td>
                                            <td></td>
                                            <td>${total_amount.toFixed(2)}</td>
                                        </tr>
                                    </table>

                                    <button class="print-btn" onclick="window.print()">Print</button>

                                    </body>
                                    </html>
                                    `;

                                    // Open report in new tab/window
                                    let w = window.open();
                                    w.document.write(html);
                                    w.document.close();
                                }
                            });

                        }
                    });

                }
            });

        });

    }
});

