    let clear_btn = frm.add_custom_button(__('Clear'), function() {
      frappe.confirm(
        __('Clear all fields and start fresh? Unsaved data will be lost.'),
        function() {
          frappe.new_doc(frm.doctype);
        }
      );
    });
    $(clear_btn).removeClass('btn-default btn-primary')
                 .addClass('btn-danger')
                 .css({'font-weight': 'bold'});

    // Show "Next -> BIN" only after save
    if (!frm.is_new()) {
      let next_bin_btn = frm.add_custom_button(__('Next -> BIN'), function() {
        frappe.new_doc('SRN BINNING');
      });
      $(next_bin_btn).removeClass('btn-default btn-primary')
                     .addClass('btn-success')
                     .css({'font-weight': 'bold','margin-left': '5px'});
    }

    // Menu handling
    if (frm.is_new()) {
      frm.page.clear_menu();
      frm.page.menu_btn_group && $(frm.page.menu_btn_group).hide();
    } else {
      frm.page.menu_btn_group && $(frm.page.menu_btn_group).show();
      setTimeout(() => {
        const remove_items = ["Customize","Edit Doctype","Copy to Clipboard","Duplicate","Links"];
        remove_items.forEach(item => {
          frm.page.menu.find(`a:contains("${item}")`).parent().remove();
        });
      }, 100);
    }
  },

  // Basic guard for SRN reference
  srn_ref_no(frm) {
    if (!frm.doc.srn_ref_no) {
      frappe.throw(__('Invalid SRN Number – Please Enter a Valid Entry.'));
    }
  },

  // Triggered after save to refresh form and show Next -> BIN
  after_save(frm) {
    frm.reload_doc();
  }
});

