async function fetch_to_screen(frm) {
  try {
    const res = await frappe.call({
      method: 'frappe.client.get_list',
      args: {
        doctype: 'TO_SCREEN_STOCK',
        filters: { status: 'To-Screen' },
        fields: ['mdb_part_no','comp_code','qty','stock_name','date_code','exp_date','mfr_name','card_no','location','batch_no'],
        limit_page_length: 500
      }
    });
    if (!res.message?.length) {
      frappe.msgprint(__('Unable to Fetch Details – Retry or Contact Support.'));
      return;
    }
    frm.clear_table('table_agsm');
    res.message.forEach(d => {
      const row = frm.add_child('table_agsm');
      row.comp_code = d.comp_code;
      row.mdb_part_no = d.mdb_part_no;
      row.qty = d.qty;
      row.stock = d.stock_name;
      row.date_code = d.date_code;
      row.exp_date = d.exp_date;
      row.mfr_name = d.mfr_name;
      row.card_no = d.card_no;
      row.mdb_id = d.mdb_part_no;
      row.status = 'Pending';
    });
    await frm.refresh_field('table_agsm');
  } catch {
    frappe.msgprint(__('Unable to Fetch Details – Retry or Contact Support.'));
  }
}

async function do_workflow(frm, action) {
  await frappe.xcall('frappe.model.workflow.apply_workflow', { doc: frm.doc, action });
  await frm.reload_doc();
  frappe.show_alert({ message: __(action) + ' done', indicator: 'green' });
}

async function perform_qc(frm) {
  const rows = frm.doc.table_agsm || [];
  if (!rows.length) frappe.throw(__('No components to QC.'));
  rows.forEach(r => { if (!r.status || r.status === 'Pending') r.status = 'Pass'; });
  await frm.save();
  await do_workflow(frm, 'Perform QC');
}

async function create_srn_from_selection(frm) {
  const rows = (frm.doc.table_agsm || []).filter(r => r.status === 'Pass' && parseFloat(r.qty) > 0);
  if (!rows.length) frappe.throw(__('No approved components to create SRN.'));
  const srn = await frappe.call({
    method: 'frappe.client.insert',
    args: {
      doc: {
        doctype: 'SRN_POST',
        srn_ref_no: frm.doc.srn_ref_no,
        project: frm.doc.project,
        posted_from: frm.doc.posted_from,
        screened_at: frm.doc.screened_at,
        table_agsm: rows.map(r => ({
          doctype: 'SRN POST TABLE',
          mdb_part_no: r.mdb_part_no,
          comp_type: r.comp_code,
          qty: r.qty,
          stock_name: r.stock,
          date_code: r.date_code,
          exp_date: r.exp_date,
          mfr_name: r.mfr_name,
          card_no: r.card_no
        }))
      }
    }
  });
  if (srn?.message?.name) {
    frappe.show_alert({ message: __('SRN created: ') + srn.message.name, indicator: 'green' });
    frm.set_value('srn_post_ref', srn.message.name);
    await frm.save();
  } else frappe.msgprint(__('Failed to create SRN.'));
}

async function post_srn(frm) {
  const posting_type = frm.doc.posting_type || 'Complete';
  let srn_name = frm.doc.srn_post_ref;
  if (!srn_name) {
    await create_srn_from_selection(frm);
    srn_name = frm.doc.srn_post_ref;
    if (!srn_name) { frappe.msgprint(__('Unable to create SRN.')); return; }
  }
  await upsert_cardex_from_rows(frm);
  await post_to_stock_entry_from_rows(frm, posting_type);
  await do_workflow(frm, 'Post SRN');
}

