frappe.ui.form.on('SRN BINNING', {
  refresh(frm) {
    // --- Filter SRN REF NO to show only Submitted + Not Binned SRN_POSTs ---
    frm.set_query('srn_ref_no', function () {
      return new Promise(async (resolve) => {
        try {
          // Step 1️⃣: Get all srn_ref_no already used in SRN BINNING
          const binned_res = await frappe.call({
            method: 'frappe.client.get_list',
            args: {
              doctype: 'SRN BINNING',
              fields: ['srn_ref_no'],
              filters: [['srn_ref_no', 'is', 'set']],
              limit_page_length: 1000
            }
          });

          const already_binned = (binned_res.message || [])
            .map(d => d.srn_ref_no)
            .filter(Boolean);

          // Step 2️⃣: Return filter — only Submitted SRN_POSTs not yet binned
          const filters = [
            ['workflow_state', '=', 'Submitted'],
            ['name', 'not in', already_binned.length ? already_binned : ['']]
          ];

          resolve({ filters });

        } catch (err) {
          console.error('❌ Error in filter:', err);
          frappe.msgprint('⚠️ Failed to filter SRN_REF_NO list.');
          resolve({});
        }
      });
    });

    // --- Optional Clear Button ---
    const clear_btn = frm.add_custom_button(__('Clear'), function () {
      frappe.confirm(
        __('Clear all fields and start fresh? Unsaved data will be lost.'),
        () => frappe.new_doc(frm.doctype)
      );
    });

    $(clear_btn)
      .removeClass('btn-default btn-primary')
      .addClass('btn-danger')
      .css({ 'font-weight': 'bold' });
  },

  // --- When SRN REF NO is selected ---
  srn_ref_no(frm) {
    if (!frm.doc.srn_ref_no) return;

    // Fetch components from SRN POST TABLE
    frappe.call({
      method: 'frappe.client.get_list',
      args: {
        doctype: 'SRN POST TABLE',
        filters: { parent: frm.doc.srn_ref_no, status: 'Pass' },
        fields: [
          'mdb_part_no',
          'comp_code',
          'qty',
          'stock_name',
          'date_code',
          'exp_date',
          'mfr_name',
          'card_no',
          'batch_no'
        ],
        limit_page_length: 500
      },
      callback(res) {
        frm.clear_table('table_agsm');
        (res.message || []).forEach(d => {
          const row = frm.add_child('table_agsm');
          row.comp_code = d.comp_code;
          row.mdb_part_no = d.mdb_part_no;
          row.qty = d.qty;
          row.stock = d.stock_name;
          row.date_code = d.date_code;
          row.exp_date = d.exp_date;
          row.mfr_name = d.mfr_name;
          row.card_no = d.card_no;
          row.batch_no = d.batch_no;
          row.status = 'Pending';
        });
        frm.refresh_field('table_agsm');
      }
    });
  }
});

frappe.ui.form.on('BASIC MDB', {
    refresh(frm) {

        function load_saved_records() {
            const wrapper = frm.get_field('saved_records').$wrapper;
            wrapper.empty(); // Clear existing HTML

            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'BASIC MDB',
                    fields: [
                        'name',
                        'select_component',
                        'linkpartno',
                        'select_pstyle_save',
                        'basic_mdb',
                        'partno_descripton',
                        'status'
                    ],
                    filters: {
                        status: ['!=', 'Inactive'] // ✅ Show only Active records
                    },
                    limit_page_length: 50
                },
                callback: function(r) {
                    if (r.message && r.message.length) {
                        let html = `<table class="table table-bordered">
                                        <tr>
                                            <th>Sr. No.</th>
                                            <th>Select Component Type</th>
                                            <th>Enter Link Part NO</th>
                                            <th>Select Pstyle</th>
                                            <th>Enter Basic MDB</th>
                                            <th>Partno Description</th>
                                            <th>Status</th>
                                            <th>Edit</th>
                                            <th>Copy</th>
                                            <th>Delete</th>
                                        </tr>`;
                        r.message.forEach((row, index) => {
                            const status = row.status || 'Active';
                            html += `<tr data-name="${row.name}">
                                        <td>${index + 1}</td>
                                        <td>${row.select_component || ''}</td>
                                        <td>${row.linkpartno || ''}</td>
                                        <td>${row.select_pstyle_save || ''}</td>
                                        <td>${row.basic_mdb || ''}</td>
                                        <td>${row.partno_descripton || ''}</td>
                                        <td class="status-cell">${status}</td>
                                        <td><button class="btn btn-xs btn-primary edit-btn" data-name="${row.name}">Edit</button></td>
                                        <td><button class="btn btn-xs btn-success copy-btn" data-name="${row.name}">Copy</button></td>
                                        <td><button class="btn btn-xs btn-danger delete-btn" data-name="${row.name}">Delete</button></td>
                                    </tr>`;
                        });
                        html += `</table>`;
                        wrapper.html(html);

                        // EDIT button
                        wrapper.find('.edit-btn').on('click', function() {
                            frappe.set_route('Form', 'BASIC MDB', $(this).data('name'));
                        });

                        // COPY button
                        wrapper.find('.copy-btn').on('click', function() {
                            const docname = $(this).data('name');
                            frappe.call({
                                method: 'frappe.client.get',
                                args: { doctype: 'BASIC MDB', name: docname },
                                callback: function(r) {
                                    if (r.message) {
                                        const doc = r.message;

                                        // Create a new doc with same field values
                                        const new_doc = frappe.model.get_new_doc('BASIC MDB');
                                        new_doc.select_component = doc.select_component;
                                        new_doc.linkpartno = doc.linkpartno;
                                        new_doc.select_pstyle = doc.select_pstyle;
                                        new_doc.basic_mdb = doc.basic_mdb;
                                        new_doc.partno_descripton = doc.partno_descripton;
                                        new_doc.status = 'Active';

                                        frappe.set_route('Form', 'BASIC MDB', new_doc.name);

                                        frappe.show_alert({
                                            message: __('🧩 Record copied — edit and save as new'),
                                            indicator: 'blue'
                                        });
                                    }
                                }
                            });
                        });

                        // SOFT DELETE button (mark as Inactive)
                        wrapper.find('.delete-btn').on('click', function() {
                            const docname = $(this).data('name');
                            frappe.confirm(
                                'Are you sure you want to mark this record as Inactive?',
                                function() {
                                    frappe.call({
                                        method: 'frappe.client.set_value',
                                        args: {
                                            doctype: 'BASIC MDB',
                                            name: docname,
                                            fieldname: 'status',
                                            value: 'Inactive'
                                        },
                                        callback: function() {
                                            frappe.show_alert({
                                                message: __('⚠️ Record marked as Inactive'),
                                                indicator: 'orange'
                                            });
                                            load_saved_records(); // ✅ Refresh table to hide it
                                        }
                                    });
                                }
                            );
                        });
                    } else {
                        wrapper.html('<p>No active records found</p>');
                    }
                }
            });
        }

        load_saved_records();
    }
});

frappe.ui.form.on('Project Packege Approval', {
    refresh: function(frm) {

        // Set default workflow status for new records
        if (frm.is_new() && !frm.doc.work_flow_status) {
            frm.set_value('work_flow_status', 'Pending for Approval');
            frm.set_value('status', 'Inactive'); // default inactive
        }

        // Disable Save until decision
        frm.disable_save();

        // Show buttons only if current status = Active or Pending
        if (['Active', 'Pending for Approval'].includes(frm.doc.status)) {

            // Approve Button
            frm.add_custom_button(__('Approve'), function() {
                frm.set_value('work_flow_status', 'Approved');
                frm.set_value('status', 'Active');
                frappe.msgprint(__('Work Flow Status set to "Approved". Please click Save to confirm.'));
                frm.enable_save();
            }, __('Actions'));

            // Reject Button
            frm.add_custom_button(__('Reject'), function() {
                frappe.prompt([{
                    fieldname: 'remarks',
                    label: 'Remarks (mandatory)',
                    fieldtype: 'Small Text',
                    reqd: true
                }], function(values) {
                    frm.set_value('remarks', values.remarks);
                    frm.set_value('work_flow_status', 'Rejected');
                    frm.set_value('status', 'Inactive');
                    frappe.msgprint(__('Work Flow Status set to "Rejected". Please click Save to confirm.'));
                    frm.enable_save();
                }, __('Enter Remarks'), __('Reject'));
            }, __('Actions'));
        }
    },

    before_save: function(frm) {
        // Only allow save if a decision is made
        if (!['Approved', 'Rejected'].includes(frm.doc.work_flow_status)) {
            frappe.throw(__('Please choose "Approved" or "Rejected" before saving.'));
        }

        // Ensure pack_code is set
        if (!frm.doc.pack_code) {
            frappe.throw(__('Please select a Package before saving.'));
        }
    },

    after_save: function(frm) {
        // Map status based on workflow
        let package_status = (frm.doc.work_flow_status === 'Approved') ? 'Active' : 'Inactive';

        // Directly update the Package linked via pack_code
        frappe.call({
            method: 'frappe.client.set_value',
            args: {
                doctype: 'Packeges',
                name: frm.doc.pack_code, // directly using pack_code link
                fieldname: {
                    work_flow_status: frm.doc.work_flow_status,
                    status: package_status,
                    remarks: frm.doc.remarks || ''
                }
            },
            callback: function() {
                frappe.show_alert(__(`${frm.doc.work_flow_status}! Package updated successfully.`));
            }
        });
    }
});

