frappe.ui.form.on("Material Request Item", {
    async item_code(frm, cdt, cdn) {
        const row = frappe.get_doc(cdt, cdn);

        // Clear existing options
        frm.fields_dict.items.grid.update_docfield_property(
            "custom_base_part_number",
            "options",
            []
        );
        frappe.model.set_value(cdt, cdn, "custom_base_part_number", "");

        if (!row.item_code) return;

        try {
            // Fetch the Item document with its child table
            const { message: item_doc } = await frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Item",
                    name: row.item_code,
                },
            });

            if (!item_doc || !item_doc.custom_base_part_number) {
                frappe.msgprint(`⚠️ No Base Part Numbers found for this Item.`);
                return;
            }

            // Extract base part numbers from the child table
            const base_parts = item_doc.custom_base_part_number.map(
                (d) => d.base_part_number
            );

            // Set the options dynamically for the field
            frm.fields_dict.items.grid.update_docfield_property(
                "custom_base_part_number",
                "options",
                ["", ...base_parts]
            );

        } catch (error) {
            console.error(error);
            frappe.msgprint("Error fetching Base Part Numbers.");
        }
    },
});

