frappe.ui.form.on("Stock Entry", {
    refresh: function(frm) {
        if (!frm.is_new() && frm.doc.docstatus === 0) {
            // Add custom "Get Items From Purchase Receipt" button
            frm.add_custom_button(__('Purchase Receipt'), function() {
                frm.events.get_items_from_purchase_receipt(frm);
            }, __("Get Items From"));
        }
    },

    get_items_from_purchase_receipt: function(frm) {
        frappe.prompt(
            [
                {
                    fieldtype: 'Link',
                    label: 'Purchase Receipt',
                    fieldname: 'purchase_receipt',
                    options: 'Purchase Receipt',
                    reqd: 1
                }
            ],
            function(data) {
                frappe.call({
                    method: "frappe.client.get",
                    args: {
                        doctype: "Purchase Receipt",
                        name: data.purchase_receipt
                    },
                    callback: function(r) {
                        if (r.message) {
                            let pr = r.message;

                            // Clear old items
                            frm.clear_table("items");

                            (pr.items || []).forEach(d => {
                                let row = frm.add_child("items");
                                row.item_code = d.item_code;
                                row.item_name = d.item_name;
                                row.uom = d.uom;
                                row.qty = d.qty;
                                row.conversion_factor = d.conversion_factor;
                                row.stock_uom = d.stock_uom;
                                row.s_warehouse = d.warehouse; // Use PR warehouse
