frappe.ui.form.on('Stock Entry Detail', {
    custom_exp_date: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (row.custom_exp_date) {
            let exp_date = frappe.datetime.str_to_obj(row.custom_exp_date);
            let today = frappe.datetime.now_date();
            let five_years_later = frappe.datetime.add_years(today, 5);

            if (exp_date < today || exp_date > five_years_later) {
                frappe.model.set_value(cdt, cdn, 'custom_exp_date', '');
            }
        }
    }
});

frappe.ui.form.on('BASIC MDB', { 

    refresh(frm) { 



        function load_saved_records() { 

            const wrapper = frm.get_field('saved_records').$wrapper; 

            wrapper.empty(); // Clear existing HTML 



            frappe.call({ 

                method: 'frappe.client.get_list', 

                args: { 

                    doctype: 'BASIC MDB', 

                    fields: [ 

                        'name', 

                        'select_component', 

                        'linkpartno', 

                        'select_pstyle', 

                        'basic_mdb', 

                        'partno_descripton', 

                        'status' 

                    ], 

                    filters: { 

                        status: ['!=', 'Inactive'] // ✅ Show only Active records 

                    }, 

                    limit_page_length: 50 

                }, 

                callback: function(r) { 

                    if (r.message && r.message.length) { 

                        let html = `<table class="table table-bordered"> 

                                        <tr> 

                                            <th>Sr. No.</th> 

                                            <th>Select Component Type</th> 

                                            <th>Enter Link Part NO</th> 

                                            <th>Select Pstyle</th> 

