                        r.message.forEach((row, index) => { 

                            const status = row.status || 'Active'; 

                            html += `<tr data-name="${row.name}"> 

                                        <td>${index + 1}</td> 

                                        <td>${row.select_component || ''}</td> 

                                        <td>${row.linkpartno || ''}</td> 

                                        <td>${row.select_pstyle || ''}</td> 

                                        <td>${row.basic_mdb || ''}</td> 

                                        <td>${row.partno_descripton || ''}</td> 

                                        <td class="status-cell">${status}</td> 

                                        <td><button class="btn btn-xs btn-primary edit-btn" data-name="${row.name}">Edit</button></td> 

                                        <td><button class="btn btn-xs btn-success copy-btn" data-name="${row.name}">Copy</button></td> 

                                        <td><button class="btn btn-xs btn-danger delete-btn" data-name="${row.name}">Delete</button></td> 

                                    </tr>`; 

                        }); 

                        html += `</table>`; 

                        wrapper.html(html); 



                        // EDIT button 

                        wrapper.find('.edit-btn').on('click', function() { 

                            frappe.set_route('Form', 'BASIC MDB', $(this).data('name')); 

                        }); 



                        // COPY button 

                        wrapper.find('.copy-btn').on('click', function() { 

                            const docname = $(this).data('name'); 

                            frappe.call({ 

                                method: 'frappe.client.get', 

                                args: { doctype: 'BASIC MDB', name: docname }, 

                                callback: function(r) { 

                                    if (r.message) { 

                                        const doc = r.message; 



                                        // Create a new doc with same field values 

                                        const new_doc = frappe.model.get_new_doc('BASIC MDB'); 

                                        new_doc.select_component = doc.select_component; 

                                        new_doc.linkpartno = doc.linkpartno; 

                                        new_doc.select_pstyle = doc.select_pstyle; 

                                        new_doc.basic_mdb = doc.basic_mdb; 

                                        new_doc.partno_descripton = doc.partno_descripton; 

                                        new_doc.status = 'Active'; 



                                        frappe.set_route('Form', 'BASIC MDB', new_doc.name); 



                                        frappe.show_alert({ 

                                            message: __('🧩 Record copied — edit and save as new'), 

                                            indicator: 'blue' 

                                        }); 

                                    } 

                                } 

                            }); 

                        }); 



                        // SOFT DELETE button (mark as Inactive) 

                        wrapper.find('.delete-btn').on('click', function() { 

                            const docname = $(this).data('name'); 

                            frappe.confirm( 

                                'Are you sure you want to mark this record as Inactive?', 

                                function() { 

                                    frappe.call({ 

                                        method: 'frappe.client.set_value', 

                                        args: { 

                                            doctype: 'BASIC MDB', 

                                            name: docname, 

                                            fieldname: 'status', 

                                            value: 'Inactive' 

                                        }, 

                                        callback: function() { 

                                            frappe.show_alert({ 

                                                message: __('⚠️ Record marked as Inactive'), 

                                                indicator: 'orange' 

                                            }); 

                                            load_saved_records(); // ✅ Refresh table to hide it 

                                        } 

                                    }); 

                                } 

                            ); 

                        }); 

                    } else { 

                        wrapper.html('<p>No active records found</p>'); 

                    } 

                } 

            }); 

        } 



        load_saved_records(); 

    } 

});

