frappe.ui.form.on("Add Project Card", {
  refresh(frm) {
    if (!frm.fields_dict.add_card_html) return;

    // --- Parse saved cards
    try {
      frm.created_cards = frm.doc.card_json ? JSON.parse(frm.doc.card_json) : [];
    } catch (e) {
      frm.created_cards = [];
    }

    // --- Build the unified UI
    const $w = frm.fields_dict.add_card_html.$wrapper;
    $w.empty().html(`
      <div class="card p-3 shadow-sm" style="max-width:1000px; margin:20px auto; border-radius:12px;">
        <h4 style="text-align:center; margin-bottom:15px;">🧾 ECAD Card Table</h4>
        <div style="text-align:center; margin-bottom:15px;">
          <button class="btn btn-primary" id="add-card-btn">
            ➕ Add / Generate Card
          </button>
        </div>
        <div id="card-table" style="margin-top:10px; overflow-x:auto;"></div>
      </div>
    `);

    // --- Helper: alphabet suffix generator
    function getAlphaSequence(index, isUpper) {
      const letters = isUpper ? "ABCDEFGHIJKLMNOPQRSTUVWXYZ" : "abcdefghijklmnopqrstuvwxyz";
      let seq = "";
      while (index >= 0) {
        seq = letters[index % 26] + seq;
        index = Math.floor(index / 26) - 1;
      }
      return seq;
    }

    // --- Helper: build card name
    function buildCardName(base, suffix, i) {
      if (!suffix) return `${base}${i}`;
      if (/^[A-Za-z]+$/.test(suffix)) {
        const isUpper = suffix === suffix.toUpperCase();
        return `${base}${getAlphaSequence(i - 1, isUpper)}`;
      }
      if (/[A-Za-z]+$/.test(suffix)) {
        const match = suffix.match(/([A-Za-z]+)$/);
        const letterPart = match ? match[1] : "";
        const prefix = suffix.slice(0, suffix.length - letterPart.length);
        const isUpper = letterPart === letterPart.toUpperCase();
        return `${base}${prefix}${getAlphaSequence(i - 1, isUpper)}`;
      }
      return `${base}${suffix}${i}`;
    }

    // --- Helper: color based on status
    function getStatusColor(status) {
      const colors = { Approve: "success", Reject: "danger", Initial: "secondary" };
      return colors[status] || "light";
    }

    // --- Render Grid/Table
    function renderCards() {
      const container = $w.find("#card-table");
      container.empty();

      if (!frm.created_cards.length) {
        container.html(`<p style="text-align:center; color:gray;">No cards added yet.</p>`);
        return;
      }

      let html = `
        <table class="table table-bordered table-sm">
          <thead class="thead-light">
            <tr>
              <th style="text-align:center;">#</th>
              <th>Card Name</th>
              <th>Status</th>
              <th style="text-align:center;">Actions</th>
            </tr>
          </thead>
          <tbody>
      `;

      frm.created_cards.forEach((c, idx) => {
        html += `
          <tr>
            <td style="text-align:center;">${idx + 1}</td>
            <td>${c.name || "-"}</td>
            <td style="text-align:center;">
              <span class="badge badge-${getStatusColor(c.status)}">${c.status}</span>
            </td>
            <td style="text-align:center;">
              <button class="btn btn-sm btn-success card-action" data-action="approve" data-index="${idx}" title="Approve">✔</button>
              <button class="btn btn-sm btn-warning card-action" data-action="initial" data-index="${idx}" title="Reset">↩</button>
              <button class="btn btn-sm btn-danger card-action" data-action="reject" data-index="${idx}" title="Reject">✖</button>
              <button class="btn btn-sm btn-outline-danger card-action" data-action="delete" data-index="${idx}" title="Delete">🗑</button>
            </td>
          </tr>
        `;
      });

      html += "</tbody></table>";
      container.html(html);
    }

    renderCards();

    // --- Add / Generate Button Logic
    $w.find("#add-card-btn").off("click").on("click", function () {
      if (frm.doc.select_card === "New") {
        // ---- Add single card manually
        const cardName = (frm.doc.card_names || "").trim();
        if (!cardName) {
          frappe.msgprint({
            title: "Missing Data",
            message: "Please enter Card Name.",
            indicator: "orange"
          });
          return;
        }

        frm.created_cards.push({ name: cardName, status: "Initial" });
        frm.set_value("card_json", JSON.stringify(frm.created_cards));
        frappe.show_alert({ message: "Card added successfully!", indicator: "green" });
        frm.set_value("card_names", "");
        renderCards();

      } else if (frm.doc.select_card === "Select From ECard") {
        // ---- Generate multiple cards
        const base = (frm.doc.ecad_card_name || "").trim();
        const count = parseInt(frm.doc.card_name || 0);
        const suffix = (frm.doc.card_count_suffix || "").trim();

        if (!base || !count) {
          frappe.msgprint({
            title: "Missing Information",
            message: "Please fill ECAD Card Name and Card Count before generating cards.",
            indicator: "orange"
          });
          return;
        }

        for (let i = 1; i <= count; i++) {
          const name = buildCardName(base, suffix, i);
          if (!frm.created_cards.some(c => c.name === name)) {
            frm.created_cards.push({ name, status: "Initial" });
          }
        }

        frm.set_value("card_json", JSON.stringify(frm.created_cards));
        frappe.show_alert({ message: `${count} card(s) generated.`, indicator: "green" });
        renderCards();
      } else {
        frappe.msgprint("Please select a valid Card Type (New / Select From ECard).");
      }
    });

    // --- Card Action Buttons
    $w.on("click", ".card-action", function () {
      const index = Number($(this).data("index"));
      const action = $(this).data("action");
      const card = frm.created_cards[index];
      if (!card) return;

      switch (action) {
        case "approve": card.status = "Approve"; break;
        case "reject": card.status = "Reject"; break;
        case "initial": card.status = "Initial"; break;
        case "delete":
          frm.created_cards.splice(index, 1);
          break;
      }

      frm.set_value("card_json", JSON.stringify(frm.created_cards));
      renderCards();
    });

    // --- Toggle visibility
    frm.toggle_display("card_names", frm.doc.select_card === "New");
    frm.toggle_display("ecad_card_name", frm.doc.select_card === "Select From ECard");
    frm.toggle_display("card_name", frm.doc.select_card === "Select From ECard");
    frm.toggle_display("card_count_suffix", frm.doc.select_card === "Select From ECard");
  },

  // --- Update field visibility on change
  select_card(frm) {
    frm.toggle_display("card_names", frm.doc.select_card === "New");
    frm.toggle_display("ecad_card_name", frm.doc.select_card === "Select From ECard");
    frm.toggle_display("card_name", frm.doc.select_card === "Select From ECard");
    frm.toggle_display("card_count_suffix", frm.doc.select_card === "Select From ECard");
  }
});

