frappe.ui.form.on('Purchase Receipt', {
    validate: function (frm) {
        let is_valid = true;

        // Loop through the items in the Purchase Receipt
        frm.doc.items.forEach(item => {
            // Check if the item has a linked Purchase Order
            if (!item.purchase_order) {
                // If the purchase_order is missing, show the error and set is_valid to false
                frappe.msgprint(__('Please select a Purchase Order for item: {0}', [item.item_code]));
                is_valid = false;
            }
        });

        // If there is a missing Purchase Order in any item, stop form submission
        if (!is_valid) {
            frappe.validated = false;
            return;
        }

        // If all items have a valid Purchase Order, proceed with other validation
        let received_qty_map = {};
        frm.doc.items.forEach(item => {
            if (received_qty_map[item.item_code]) {
                received_qty_map[item.item_code] += item.received_qty;
            } else {
                received_qty_map[item.item_code] = item.received_qty;
            }
        });

        // Call to the backend to validate PR against PO
        frappe.call({
            method: 'ursc_cms_app.ursc_cms_app.api.validate_pr_against_po',
            args: { doc: frm.doc },
            callback: function(response) {
                if (response.exc) {
                    frappe.msgprint(__('Validation failed: ') + response.exc);
                    frappe.validated = false;
                } else {
                    frappe.msgprint(__('Purchase Receipt validation successful!'));
                }
            }
        });
    },
});

