// Helper function to set up date code field
function setup_date_code_field(grid_row) {
  const date_code_field = grid_row?.grid_form?.fields_dict?.custom_date_code;
  if (!date_code_field || !date_code_field.$input) return;

  // Remove existing handlers to avoid duplicates
  date_code_field.$input.off('keypress.datecode input.datecode');

  // Only allow numeric input on keypress
  date_code_field.$input.on('keypress.datecode', function(e) {
    const key = e.key;
    // Allow: backspace, delete, tab, escape, enter, and arrow keys
    if ([8, 9, 27, 13, 46, 37, 38, 39, 40].includes(e.keyCode) ||
        // Allow Ctrl+A, Ctrl+C, Ctrl+V, Ctrl+X
        (e.ctrlKey && [65, 67, 86, 88].includes(e.keyCode))) {
      return;
    }
    // Only allow numeric keys (0-9)
    if (!/[0-9]/.test(key)) {
      e.preventDefault();
      return false;
    }
  });

  // Limit to 4 digits on input
  date_code_field.$input.on('input.datecode', function() {
    let value = $(this).val().replace(/\D/g, '');
    if (value.length > 4) {
      value = value.substring(0, 4);
      $(this).val(value);
    }
  });

  // Validate on blur (when user leaves the field)
  date_code_field.$input.on('blur.datecode', function() {
    const value = $(this).val().replace(/\D/g, '');
    if (value.length === 4) {
      const week_part = parseInt(value.substring(2, 4));
      if (week_part < 1 || week_part > 52) {
        frappe.msgprint({
          title: __('Invalid Date Code'),
          message: __('Week number must be between 01 and 52. Current value: {0}', [week_part.toString().padStart(2, '0')]),
          indicator: 'red'
        });
        $(this).val('');
        $(this).focus();
      }
    }
  });
}

