frappe.ui.form.on("SIV req for SRN Table", {
    async link_part_no(frm, cdt, cdn) {
        const row = frappe.get_doc(cdt, cdn);

        // Clear previous dropdown options for Basic MDB
        frm.fields_dict.siv_req_for_srn_table.grid.update_docfield_property(
            "basic_mdb",
            "options",
            []
        );

        // Clear value
        frappe.model.set_value(cdt, cdn, "basic_mdb", "");

        if (!row.link_part_no) return;

        try {
            // Fetch full Item document, including its child table srv_number
            const { message: item_doc } = await frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Item",
                    name: row.link_part_no,
                },
            });

            if (!item_doc || !item_doc.srv_number || item_doc.srv_number.length === 0) {
                frappe.msgprint(`⚠️ No Basic MDBs found for this Item.`);
                return;
            }

            // Extract Basic MDBs (enter_basic_mdb values)
            const mdb_list = item_doc.srv_number.map((d) => d.enter_basic_mdb);

