// =================================================
// LOAD MDB PART NUMBERS BASED ON COMPONENT link_part_number
// =================================================
function update_mdb_part_number_options(frm, cdt, cdn) {

    const row = locals[cdt][cdn];
    const link_part_number = row.link_part_number;

    if (!link_part_number) {
        frappe.model.set_value(cdt, cdn, "mdb_part_number", "");
        frappe.model.set_value(cdt, cdn, "date_code", "");
        return;
    }

    frappe.db.get_list("Stock Entry Detail", {
        fields: [
            "item_code",
            "custom_mdb_part_no",
            "custom_date_code"
        ],
        filters: {
            item_code: link_part_number
        },
        limit: 100
    }).then(res => {

        // Build Select options
        const options = res
            .map(r => r.custom_mdb_part_no)
            .filter(Boolean);

        // Update Select field options in child table
        if (frm.fields_dict.table_bnpa) {
            frm.fields_dict.table_bnpa.grid.update_docfield_property(
                "mdb_part_number",
                "options",
                ["", ...options]
            );
        }

        // Reset values if current MDB is invalid
        if (!options.includes(row.mdb_part_number)) {
            frappe.model.set_value(cdt, cdn, "mdb_part_number", "");
            frappe.model.set_value(cdt, cdn, "date_code", "");
        } else {
