// Client Script for: Update-Status

frappe.ui.form.on("Update-Status", {

    // 1️⃣ Auto-fetch data from Failure Request
    fa_request_no: function (frm) {
        if (!frm.doc.fa_request_no) return;

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Failure Request",
                name: frm.doc.fa_request_no
            },
            callback: function (r) {
                if (!r.message) {
                    frappe.msgprint("❌ Failure Request not found.");
                    return;
                }

                var source = r.message;

                var field_map = {
                    // COMPONENT DETAILS
                    comp_type:            "comp_type",
                    mdb_part_no:          "mdb_part_no",
                    package_style:        "package_style",
                    date_code:            "date_code",
                    manufacturer:         "manufacturer",
                    quality:              "quality",
                    sr_no:                "sr_no",
                    procurement_spec:     "procurement_spec",

                    // FAILURE DETAILS
                    failed_during:                "failed_during",
                    failure_type:                 "failure_type",
                    project_model:                "project_model",
                    project:                      "project",
                    subsystem:                    "subsystem",
                    package:                      "package",
                    card:                         "card",
                    failed_at:                    "failed_at",
                    failure_mode:                 "failure_mode",
                    environmental_test_condition: "environmental_test_condition",
                    reported_failure:             "reported_failure"
                };

                Object.keys(field_map).forEach(function (src) {
                    var target = field_map[src];
                    if (source[src] !== undefined && source[src] !== null) {
                        frm.set_value(target, source[src]);
                    }
                });

                frm.refresh_fields();
                frappe.show_alert("✅ Data fetched from Failure Request");
            },
            error: function (err) {
                console.error(err);
                frappe.msgprint("⚠ Error fetching Failure Request data.");
            }
        });
    },

    // 2️⃣ Approve button logic
    refresh: function (frm) {

        // wait for HTML field to render
        setTimeout(() => {

            // find the button inside html_approve_btn field
            const $btn = $(frm.fields_dict.html_approve_btn.wrapper).find("#btn_approve");

            // remove old handlers
            $btn.off("click");

            // APPROVE button click
            $btn.on("click", function () {

                if (!frm.doc.workflow_status || frm.doc.workflow_status === "Initial") {
                    frm.set_value("workflow_status", "Approve");
                    frm.refresh_field("workflow_status");
                    frm.save();
                }
            });

        }, 300);
    }
});

