async function fetch_basic_mdb_options(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    // Stop if no item selected
    if (!row.comp_code) return;

    try {
        // Fetch the selected Item document
        const { message: item_doc } = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Item",
                name: row.comp_code,  // comp_code → Link to Item
            },
        });

        if (!item_doc) {
            frappe.msgprint("Unable to fetch Item details.");
            return;
        }

        // Basic MDB child table from Item
        const mdb_rows = item_doc.custom_srv_number || [];

        if (!mdb_rows.length) {
            // No entries → clear dropdown
            frm.fields_dict.table_wvxq.grid.update_docfield_property(
                "basic_mdb",
                "options",
                [""]
            );
            frappe.msgprint("No Basic MDB values found for this Component.");
            return;
        }

        // Extract values from enter_basic_mdb
        const mdb_list = mdb_rows.map(r => r.enter_basic_mdb);

        // Update dropdown options (Your parent table = table_wvxq)
        frm.fields_dict.table_wvxq.grid.update_docfield_property(
            "basic_mdb",
            "options",
            ["", ...mdb_list]
        );

        // Auto-select first entry if empty
        if (!row.basic_mdb) {
            frappe.model.set_value(cdt, cdn, "basic_mdb", mdb_list[0] || "");
        }

        frm.refresh_field("table_wvxq");

    } catch (err) {
        console.error(err);
        frappe.msgprint("Error fetching Basic MDB from Item.");
    }
}

