    }

    // CLIENT-SIDE DB QUERY – get MDB Part Nos for this Comp Type
    frappe.db.get_list("Stock Entry Detail", {
        fields: ["custom_select_component_type", "custom_mdb_part_no"],
        filters: {
            custom_select_component_type: item_group
        },
        limit: 50
    }).then(res => {

        // Collect unique, non-empty MDB part numbers
        const options = [...new Set(
            res.map(r => r.custom_mdb_part_no).filter(Boolean)
        )];

        // Update MDB Part No (Select) options dynamically
        frm.set_df_property(
            "mdb_number",
            "options",
            ["", ...options].join("\n")
        );

