frappe.ui.form.on("SRN SPECIAL POSTING", {
    refresh(frm) {

        // Wait for HTML to fully render
        setTimeout(() => {

            // Get your HTML button by ID
            let btn = document.getElementById("btn_click");

            // If button exists, bind the event
            if (btn) {

                btn.onclick = function () {

                    // 1️⃣ Do not regenerate if already generated
                    if (frm.doc.srn_ref_no && frm.doc.srn_ref_no !== "0") {
                        frappe.msgprint({
                            title: "Already Generated",
                            message: "SRN Ref No is already generated.",
                            indicator: "orange"
                        });
                        return;
                    }

                    // 2️⃣ Generate SRN Ref client-side
                    let now = new Date();

                    let year = now.getFullYear().toString().slice(-2);  // YY
                    let month = (now.getMonth() + 1).toString().padStart(2, '0');
                    let day = now.getDate().toString().padStart(2, '0');

                    // Random 3 digits
                    let seq = Math.floor(1000 + Math.random() * 9000);

                    // Final format → SRN-SP-YYMMDD-SEQ
                    let srn_ref = `SRN-SP-${seq}`;

                    // 3️⃣ Apply into the field
                    frm.set_value("srn_ref_no", srn_ref);

                    frappe.msgprint({
                        title: "Success",
                        message: `SRN Ref No "${srn_ref}" generated successfully.`,
                        indicator: "green"
                    });

                };

            } // end if btn exists

        }, 300); // delay to allow HTML field to load

    }
});

frappe.ui.form.on("SIV Normal Request", {
    link_part_number(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.link_part_number) return;

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Bin",
                filters: { item_code: row.link_part_number },
                fields: ["warehouse", "actual_qty", "projected_qty", "reserved_qty"]
            },
            callback: function (r) {
                if (!r.message || r.message.length === 0) {
                    frappe.msgprint("No stock found for this Item");
                    return;
                }

                // If only one row: fill this child row
                if (r.message.length === 1) {
                    let s = r.message[0];

                    row.warehouse = s.warehouse;
                    row.actual_qty = s.actual_qty || 0;
                    row.projected_qty = s.projected_qty || 0;
                    row.reserved_qty = s.reserved_qty || 0;
                    row.balance_qty = (s.actual_qty || 0) - (s.reserved_qty || 0);

                    frm.refresh_field("table_bnpa");
                    return;
                }

                // If multiple warehouses → open a dialog to choose
                let dialog = new frappe.ui.Dialog({
                    title: "Select Warehouse Stock",
                    fields: [
                        {
                            fieldname: "warehouse",
                            label: "Warehouse",
                            fieldtype: "Table",
                            cannot_add_rows: true,
                            in_editable_grid: true,
                            fields: [
                                { fieldname: "wh", label: "Warehouse", fieldtype: "Data", read_only: 1 },
                                { fieldname: "actual", label: "Actual Qty", fieldtype: "Float", read_only: 1 },
                                { fieldname: "projected", label: "Projected Qty", fieldtype: "Float", read_only: 1 },
                                { fieldname: "reserved", label: "Reserved Qty", fieldtype: "Float", read_only: 1 }
                            ]
                        }
                    ],
                    primary_action: function () {
                        let data = dialog.get_values().warehouse;
                        if (data.length > 0) {
                            let selected = data[0];

                            row.warehouse = selected.wh;
                            row.actual_qty = selected.actual;
                            row.projected_qty = selected.projected;
                            row.reserved_qty = selected.reserved;
                            row.balance_qty = selected.actual - selected.reserved;

                            frm.refresh_field("table_bnpa");
                        }
                        dialog.hide();
                    },
                    primary_action_label: "Select"
                });

                // Load data into dialog table
                r.message.forEach(s => {
                    dialog.fields_dict.warehouse.df.data.push({
                        wh: s.warehouse,
                        actual: s.actual_qty,
                        projected: s.projected_qty,
                        reserved: s.reserved_qty
                    });
                });

                dialog.fields_dict.warehouse.grid.refresh();
                dialog.show();
            }
        });
    }
});

