// Helper: Load MDB list when category = "MDB List"
function maybe_show_mdb_list(frm) {
    if (frm.doc.category !== "MDB List" || !frm.doc.item_group) {
        frm.fields_dict.mdb_preview_html.$wrapper.html(
            //<!--`<p class="text-muted">Select <b>Category = MDB List</b> and an <b>Item Group</b> to view items.</p>`-->
        );
        return;
    }

    // Fetch items based on the selected item group
    frappe.call({
        method: "ursc_cms_app.api.get_items_for_group",  // Ensure this API method returns Item Code, Description, and Pstyle
        args: { item_group: frm.doc.item_group },
        callback: function(r) {
            const items = r.message || [];
            let html = `
                <div style="max-height:350px;overflow:auto;">
                    <h5 class="mb-2 text-primary">MDB List for ${frappe.utils.escape_html(frm.doc.item_group)}</h5>
                    <table class="table table-bordered table-sm">
                        <thead class="table-light">
                            <tr>
                                <th style="width:10%"><input type="checkbox" id="select-all"></th>
                                <th style="width:20%">Link Part</th>
                                <th>Description</th>
                                <th style="width:20%">Package Style</th>
                            </tr>
                        </thead>
                        <tbody>`;

            // Check if items exist and display them
            if (items.length) {
                items.forEach(i => {
                    const desc = frappe.utils.escape_html(i.description || "");
                    const pstyle = frappe.utils.escape_html(i.custom_pstylesave || "");  // Assuming "custom_pstylesave" holds the package style
                    html += `
                        <tr class="selectable-item">
                            <td><input type="checkbox" class="mdb-select" data-item="${i.name}" data-desc="${desc}" data-pstyle="${pstyle}" data-qty="1"></td>
                            <td>${i.name}</td>
                            <td>${desc}</td>
                            <td>${pstyle}</td>
                        </tr>`;
                });
            } else {
                html += `<tr><td colspan="4" class="text-center text-muted">
                            No items found for group ${frm.doc.item_group}.
                         </td></tr>`;
            }

            html += `</tbody></table></div>
                     <div class="mt-2">
                         <label>Quantity to Add:</label>
                         <input type="number" min="1" class="form-control d-inline-block" id="row-count" placeholder="1" style="width:120px;margin:0 10px;">
                         <button class="btn btn-primary btn-sm" id="add-to-list">Add Selected to Component List</button>
                     </div>`;

            frm.fields_dict.mdb_preview_html.$wrapper.html(html);

            // Select-all checkbox logic
            setTimeout(() => {
                const wrapper = frm.fields_dict.mdb_preview_html.$wrapper;
                wrapper.find("#select-all").on("change", function() {
                    const checked = $(this).is(":checked");
                    wrapper.find(".mdb-select").prop("checked", checked);
                });

                // Add selected items to the child table when the "Add Selected" button is clicked
                wrapper.find("#add-to-list").on("click", function() {
                    const selected = [];
                    const count = parseInt(wrapper.find("#row-count").val()) || 1;

                    wrapper.find(".mdb-select:checked").each(function() {
                        selected.push({
                            item_code: $(this).data("item"),
                            description: $(this).data("desc"),
                            pstyle: $(this).data("pstyle"),
                            qty: count
                        });
                    });

                    if (!selected.length) {
                        frappe.msgprint("Please select at least one item.");
                        return;
                    }

                    selected.forEach(sel => {
                        frm.add_child('component_list', {
                            link_part: sel.item_code,
                            part_desc: sel.description,
                            select_package_style: sel.pstyle,
                            qty: sel.qty,
                            package_style_save: sel.pstyle  // Add this to store package style in the child table
                        });
                    });

                    frm.refresh_field('component_list');
                    frappe.show_alert({ message: "Selected Component Type added to Project Component Card List", indicator: 'green' });
                });
            }, 400);
        }
    });
}

frappe.ui.form.on("Component Screening Req Wrt Project Cards and Req Generation", {
    refresh(frm) {
        // Find and bind the Get Data button
        $('button:contains("Get Data")').off('click').on('click', function() {
            frm.trigger("fetch_stock_quantities");
        });
    },

    async fetch_stock_quantities(frm) {
        if (!frm.doc.comp_type) {
            frappe.msgprint("Please select Component Type");
            return;
        }

        // Get items for selected Component Type
        let items_res = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Item",
                filters: { item_group: frm.doc.comp_type },
                fields: ["name"],
                limit_page_length: 5000
            }
        });

        if (!items_res.message || items_res.message.length === 0) {
            frappe.msgprint("No items found for this Component Type.");
            return;
        }

        // Extract item codes
        let items = items_res.message.map(i => i.name);

        // Warehouse Mapping for YOUR 8 fields
        const wh = {
            // Your actual field names from the form
            insat_fg1_ursc: "URSC-INSAT-Flight G1 - N",
            data_rnnj: "ISITE-INSAT-Flight G1 - N",
            data_ltqj: "URSC-INSAT-TO-SCR - N",
            data_wnae: "ISITE-INSAT-TO SCR - N",
            data_esko: "URSC-IRS-Flight G1 - N",
            data_udjk: "ISITE-IRS-Flight G1 - N",
            data_zjjx: "URSC-IRS-TO SCR - N",
            data_iyjc: "ISITE-IRS-TO SCR - N"  // Fixed this field name
        };

        frappe.show_alert("Fetching warehouse stock…");

        for (let fieldname in wh) {
            let warehouse = wh[fieldname];

            // Sum actual_qty from Bin for all items
            let stock = await frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Bin",
                    filters: [
                        ["item_code", "in", items],
                        ["warehouse", "=", warehouse]
                    ],
                    fields: ["actual_qty"]
                }
            });

            let total_qty = 0;
            if (stock.message && stock.message.length > 0) {
                stock.message.forEach(s => {
                    total_qty += s.actual_qty || 0;
                });
            }

            // Set value in form field
            frm.set_value(fieldname, total_qty);
        }

        frappe.msgprint("Stock updated for all warehouses!");
    }
});

