frappe.ui.form.on("Components Due For Screening Relifing FIFO Analysis", {
    refresh(frm) {
        // Bind the button click
        $(frm.fields_dict.html_eezn.wrapper)
            .find("#fetch_stock_btn")
            .off("click")
            .on("click", function () {
                frm.trigger("fetch_stock_quantities");
            });
    },

    async fetch_stock_quantities(frm) {
        if (!frm.doc.comp_type) {
            frappe.msgprint("Please select Component Type (Item Group)");
            return;
        }

        // Get all items under selected Item Group
        let items_res = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Item",
                filters: { item_group: frm.doc.comp_type },
                fields: ["name"],
                limit_page_length: 5000
            }
        });

        if (!items_res.message || items_res.message.length === 0) {
            frappe.msgprint("No items found for this Item Group.");
            return;
        }

        // Extract item codes
        let items = items_res.message.map(i => i.name);

        // Warehouse Mapping
        const wh = {
            insat_fg_1__ursc: "URSC-INSAT-Flight G1 - N",
            insat_fg_1__isite: "ISITE-INSAT-Flight G1 - N",
            insat_to_scr__ursc: "URSC-INSAT-TO-SCR - N",
            insat_to_scr_isite: "ISITE-INSAT-TO SCR - N",
            irs_fg_1__ursc: "URSC-IRS-Flight G1 - N",
            irs_fg_1__isite: "ISITE-IRS-Flight G1 - N",
            irs_to_scr_ursc: "URSC-IRS-TO SCR - N",
            irs_to_scr_isite: "ISITE-IRS-TO SCR - N"
        };

        frappe.show_alert("Fetching warehouse stock…");

        for (let fieldname in wh) {
            let warehouse = wh[fieldname];

            // Sum actual_qty from Bin for all items
            let stock = await frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Bin",
                    filters: [
                        ["item_code", "in", items],
                        ["warehouse", "=", warehouse]
                    ],
                    fields: ["actual_qty"]
                }
            });

            let total_qty = 0;
            if (stock.message && stock.message.length > 0) {
                stock.message.forEach(s => {
                    total_qty += s.actual_qty || 0;
                });
            }

            // Set value in form field
            frm.set_value(fieldname, total_qty);
        }

        frappe.msgprint("Stock updated for all warehouses!");
    }
});

