/* ============================================================
   LOAD PENDING DPA REQUEST GRID
============================================================ */
function load_dpa_grid(frm) {
    const w = frm.fields_dict.pending_list.$wrapper;
    w.off().empty().html("<p class='text-muted'>Loading pending DPA Requests...</p>");

    frappe.call({
        method: "ursc_cms_app.api.get_pending_dpa_grid",
        callback(r) {
            const rows = r.message || [];

            if (!rows.length) {
                w.html("<p class='text-muted'>No DPA Request is pending for approval.</p>");
                return;
            }

            let html = `
            <table class="table table-hover table-bordered">
                <thead style="background:#0f172a;color:#fff;">
                    <tr>
                        <th>Req No</th>
                        <th>Req Date</th>
                        <th>Part No</th>
                        <th>Date Code</th>
                        <th>Manufacturer</th>
                        <th>DPA Stage</th>
                        <th>Status</th>
                    </tr>
                </thead>
                <tbody>`;

            rows.forEach(r => {
                html += `
                <tr class="dpa-row" data-dpa="${r.dpa_name}" style="cursor:pointer">
                    <td><b>${r.dpa_name}</b></td>
                    <td>${r.requested_date || ""}</td>
                    <td>${r.basic_part_no || ""}</td>
                    <td>${r.date_code || ""}</td>
                    <td>${r.manufacturer || ""}</td>
                    <td>${r.dpa_stage || ""}</td>
                    <td><span class="badge badge-secondary">Initial</span></td>
                </tr>`;
            });

            html += `</tbody></table>`;
            w.html(html);

            // Expand / Collapse
            w.on("click", ".dpa-row", function () {
                const dpa = $(this).data("dpa");
                const existing = w.find(`.expand-row[data-dpa='${dpa}']`);

                if (existing.length) {
                    existing.remove();
                    $(this).removeClass("table-active");
                    return;
                }

                w.find(".expand-row").remove();
                w.find(".dpa-row").removeClass("table-active");

                $(this).addClass("table-active");
                load_dpa_child_row(frm, dpa, $(this));
            });
        }
    });
}

