frappe.ui.form.on("SRN_POST", {
    onload(frm) {
        if (!frm.is_new() || frm.doc.batch_no) return;

        // Get Financial Year (April–March)
        const today = frappe.datetime.nowdate();
        const year = parseInt(today.split("-")[0]);
        const month = parseInt(today.split("-")[1]);

        let fy_start, fy_end;

        if (month >= 4) {
            fy_start = year;
            fy_end = year + 1;
        } else {
            fy_start = year - 1;
            fy_end = year;
        }

        const fy = `${String(fy_start).slice(-2)}-${String(fy_end).slice(-2)}`;

        // Fetch last batch number for this FY
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "SRN_POST",
                fields: ["batch_no"],
                filters: {
                    batch_no: ["like", `%/${fy}`]
                },
                order_by: "creation desc",
                limit_page_length: 1
            },
            callback(r) {
                let next_seq = 1;

                if (r.message && r.message.length) {
                    const last_batch = r.message[0].batch_no;
                    const last_seq = parseInt(last_batch.split("/")[0]);
                    next_seq = last_seq + 1;
                }

                const batch_no = `${String(next_seq).padStart(3, "0")}/${fy}`;
                frm.set_value("batch_no", batch_no);
            }
        });
    }
});

frappe.ui.form.on("FMS Update", {
    fms_request_number: function (frm) {

        // 1️⃣ Safety check
        if (!frm.doc.fms_request_number) return;

        // 2️⃣ Fetch Input Request using its NAME (doc id)
        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Input Request",
                name: frm.doc.fms_request_number   // this is the doc ID
            },
            callback: function (r) {

                if (!r.message) {
                    frappe.msgprint("Input Request not found");
                    return;
                }

                const src = r.message;

                // ==============================
                // 3️⃣ COPY PARENT FIELDS (ONLY IF THEY EXIST)
                // ==============================
                const parent_fields = [
                    "project",
                    "subsystem",
                    "package",
                    "card",
                    "change_type",
                    "change_of_part"
                ];

                parent_fields.forEach(fieldname => {
                    if (frm.fields_dict[fieldname] && src[fieldname] !== undefined) {
                        frm.set_value(fieldname, src[fieldname]);
                    }
                });

                // ==============================
                // 4️⃣ COPY CHILD TABLE
                // ==============================
                // Source: Input Request → table_xheu
                // Target: FMS Update     → table_glor

                frm.clear_table("table_glor");

                (src.table_xheu || []).forEach(row => {
                    let child = frm.add_child("table_glor");

                    // fieldnames are SAME in both child tables
                    Object.keys(row).forEach(key => {
                        child[key] = row[key];
                    });
                });

                frm.refresh_field("table_glor");
            }
        });
    }
});

