// Client Script | Ref DocType: SIV RETURNED COMPONENTS BIN URSC
(() => {

  // ---------------- BASIC CONFIG ----------------
  const LINK_TO_SOURCE = "return_ref_number";   // Link field in BIN
  const TARGET_CHILD   = "table_fceo";          // Child table in BIN

  const SOURCE_DT      = "SIV RETURNED COMPONENTS POST URSC";
  const SRC_CHILD_TABLE_FN = "table_nojh";      // Child table in POST

  // ---------------- PARENT FIELD MAP ----------------
  // POST field -> BIN field
  const PARENT_MAP = {
    return_reference_number: "return_ref_number",
    stock:                   "from_stock",
    srn_reference_number:    "srn_no",
    from:                    "return_from",
    posted_to_stock:         "posting_to_stockposting_to_stock",
    project:                 "project",
    siv_no:                  "siv_no",
    siv_date:                "siv_date"
  };

  // ---------------- CHILD FIELD MAP ----------------
  // POST child field -> BIN child field
  const CHILD_MAP = {
    type:            "type",
    mdb_partno:      "mdb_partno",
    date_code:       "date_code",
    return_qty:      "return_qty",
    expiry_date:     "exp_date",
    mfr:             "mfr",
    siv_qty:         "issqty",
    card_id:         "card_id_bin",
    entry_by:        "entry_by",
    card_number:     "card_no",
    location:        "location",
    quality:         "quality",
    siv_return_id:   "siv_ret_id",
    packet_number:   "packet_no",
    card_id:         "card_id"
  };

  // ---------------- SOURCE RESOLVER ----------------
  async function resolveSource(ref_val) {
    // 1️⃣ Direct match
    if (await frappe.db.exists(SOURCE_DT, ref_val)) {
      return ref_val;
    }

    // 2️⃣ Match by return_reference_number
    let exact = await frappe.db.get_value(
      SOURCE_DT,
      { return_reference_number: ref_val },
      "name"
    );
    if (exact?.message?.name) return exact.message.name;

    return null;
  }

  // ---------------- PULL FUNCTION ----------------
  async function pullFromSource(frm) {
    if (frm.__pulling) return;
    frm.__pulling = true;

    try {
      const ref_val = (frm.doc[LINK_TO_SOURCE] || "").toString().trim();
      if (!ref_val) return;

      const docname = await resolveSource(ref_val);
      if (!docname) {
        frappe.msgprint({
          title: "Not Found",
          message: `No POST document found for <b>${ref_val}</b>`,
          indicator: "red"
        });
        return;
      }

      // Fetch POST document
      const { message: src } = await frappe.call({
        method: "frappe.client.get",
        args: { doctype: SOURCE_DT, name: docname }
      });

      if (!src) return;

      // ---------------- COPY PARENT ----------------
      Object.entries(PARENT_MAP).forEach(([from, to]) => {
        if (src[from] !== undefined) {
          frm.set_value(to, src[from]);
        }
      });

      // ---------------- COPY CHILD ----------------
      frm.clear_table(TARGET_CHILD);

      const rows = src[SRC_CHILD_TABLE_FN] || [];
      rows.forEach(r => {
        const row = frm.add_child(TARGET_CHILD);
        Object.entries(CHILD_MAP).forEach(([from, to]) => {
          row[to] = r[from] ?? null;
        });
      });

      frm.refresh_field(TARGET_CHILD);

      frappe.show_alert({
        message: `Fetched ${rows.length} row(s) from POST`,
        indicator: "green"
      });

    } catch (e) {
      console.error(e);
      frappe.msgprint({
        title: "Error",
        message: e.message || "Failed to fetch POST data",
        indicator: "red"
      });
    } finally {
      frm.__pulling = false;
    }
  }

  // ---------------- EVENTS ----------------
  frappe.ui.form.on("SIV RETURNED COMPONENTS BIN URSC", {
    return_ref_number(frm) {
      if (frm.doc.return_ref_number) {
        pullFromSource(frm);
      }
    }
  });

})();

