function set_child_warehouse_filters(frm) {
    const grid = frm.fields_dict.items.grid;

    grid.get_field("custom_source_stock").get_query = function () {
        return {
            filters: {
            name: ["in", ["CQCD - N", "CQCD - U"]]
            }
        };
    };
    // ==================================================
    // SOURCE STORE → ISITE - N, URSC - N
    // ==================================================
    grid.get_field("custom_store").get_query = function () {
        return {
            filters: {
                parent_warehouse: "STORE - N",
                is_group: 1
            }
        };
    };

    // ==================================================
    // SOURCE PROGRAM → must select Target Store first
    // ==================================================
    grid.get_field("custom_source_program").get_query = function (doc, cdt, cdn) {
        const row = locals[cdt][cdn];

        if (!row.custom_store) {
            frappe.msgprint("Please select the Source Store first.");
            return { filters: { name: "No Warehouse" } };
        }

        return {
            filters: {
                parent_warehouse: row.custom_store,
                is_group: 1
            }
        };
    };

    // ==================================================
