frappe.ui.form.on("On Box Component Item", {
    link_part_number(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.link_part_number) return;

        // Clear old values
        row.warehouse = "";
        row.actual_qty = 0;
        row.projected_qty = 0;
        row.reserved_qty = 0;
        row.balance_qty = 0;
        frm.refresh_field("table_yvva");

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Stock Ledger Entry",
                filters: {
                    item_code: row.link_part_number,
                    is_cancelled: 0
                },
                fields: ["warehouse", "actual_qty"],
                limit_page_length: 0
            },
            callback(r) {
                if (!r.message || r.message.length === 0) {
                    frappe.msgprint("No stock found in Stock Ledger");
                    return;
                }

                // 🔹 Aggregate qty by warehouse
                let wh_qty = {};
                r.message.forEach(d => {
                    wh_qty[d.warehouse] =
                        (wh_qty[d.warehouse] || 0) + (d.actual_qty || 0);
                });

                // 🔹 Pick warehouse with highest qty
                let selected_wh = null;
                let max_qty = -Infinity;

                Object.keys(wh_qty).forEach(wh => {
                    if (wh_qty[wh] > max_qty) {
                        max_qty = wh_qty[wh];
                        selected_wh = wh;
                    }
                });

                if (!selected_wh || max_qty <= 0) {
                    frappe.msgprint("No available stock");
                    return;
                }

                // ✅ Auto-fill child row
                row.warehouse = selected_wh;
                row.actual_qty = max_qty;
                row.balance_qty = max_qty;

                frm.refresh_field("table_yvva");
            }
        });
    }
});

