// =============================
// RENDER HTML (PARENT → CHILD)
// =============================
window.render_dpa_html = function (frm, data) {
  if (!frm.fields_dict.results_html) return;

  const rows = data.rows || [];
  const total = data.total_count || 0;
  const page_size = data.page_size || window.dpa_page_size;
  const total_pages = Math.max(1, Math.ceil(total / page_size));

  if (!rows.length) {
    frm.fields_dict.results_html.$wrapper.html(
      "<p style='color:red;'>No records found</p>"
    );
    return;
  }

  // GROUP BY DPA REQUEST
  const grouped = {};
  rows.forEach(r => {
    if (!grouped[r.name]) grouped[r.name] = [];
    grouped[r.name].push(r);
  });

  let html = `
  <style>
    .dpa-parent { background:#eef3f8; font-weight:600; }
    .dpa-parent:hover { background:#dde7f2; }
    .dpa-child { display:none; background:#fafafa; }
    .toggle-icon { width:22px; text-align:center; cursor:pointer; font-weight:bold; }
    .status-pending { color:#d9822b; }
    .status-approved { color:#1f8f4a; }
    .status-rejected { color:#c0392b; }

    .child-box {
      border:1px solid #ddd;
      background:#fff;
      padding:8px;
      margin:6px 0;
      border-radius:4px;
      font-size:13px;
    }
    .child-box td { padding:4px 8px; border:none; }
    .child-label { width:160px; font-weight:600; color:#555; }
  </style>

  <table class="table table-bordered">
    <thead>
      <tr>
        <th></th>
        <th>DPA Request No</th>
        <th>Status</th>
        <th>DPA Stage</th>
        <th>Requested By</th>
        <th>Request Date</th>

      </tr>
    </thead>
    <tbody>
  `;

  Object.keys(grouped).forEach(name => {
    const safe = window.safe_key(name);
    const parent = grouped[name][0];

    // ----------- PARENT ROW -----------
    html += `
      <tr class="dpa-parent">
        <td class="toggle-icon" id="icon-${safe}"
            onclick="toggle_dpa_children('${safe}')">▶</td>
        <td>${name}</td>
        <td>${window.get_dpa_status(parent.dpa_status_flag)}</td>
        <td>${parent.dpa_stage || ""}</td>
        <td>${parent.requested_by || ""}</td>
        <td>${parent.dpa_req_date || ""}</td>

        </td>
      </tr>
    `;

    // ----------- CHILD ROWS -----------
    grouped[name].forEach(c => {
      html += `
        <tr class="dpa-child child-${safe}">
          <td></td>
          <td colspan="6">
            <div class="child-box">
              <table>
                <tr><td class="child-label">Component Type</td><td>${c.comp_type || ""}</td></tr>
                <tr><td class="child-label">Basic Part No</td><td>${c.basic_part_no || ""}</td></tr>
                <tr><td class="child-label">Date Code</td><td>${c.dpa_dc || ""}</td></tr>
                <tr><td class="child-label">Manufacturer</td><td>${c.manufacturer || ""}</td></tr>
                <tr><td class="child-label">Quality</td><td>${c.quality || ""}</td></tr>
              </table>
            </div>
          </td>
        </tr>
      `;
    });
  });

  html += `
    </tbody>
  </table>
  ${window.render_dpa_pagination(total_pages)}
  `;

  frm.fields_dict.results_html.$wrapper.html(html);
};

// =============================
// TOGGLE CHILD ROWS (ONE AT A TIME)
// =============================
window.toggle_dpa_children = function (safe) {
  if (window.dpa_open_parent && window.dpa_open_parent !== safe) {
    document
      .querySelectorAll(`.child-${window.dpa_open_parent}`)
      .forEach(r => r.style.display = "none");
    const prev_icon = document.getElementById(`icon-${window.dpa_open_parent}`);
    if (prev_icon) prev_icon.innerText = "▶";
  }

  const rows = document.querySelectorAll(`.child-${safe}`);
  const icon = document.getElementById(`icon-${safe}`);
  let open = false;

  rows.forEach(r => {
    if (!r.style.display || r.style.display === "none") {
      r.style.display = "table-row";
      open = true;
    } else {
      r.style.display = "none";
    }
  });

  if (icon) icon.innerText = open ? "▼" : "▶";
  window.dpa_open_parent = open ? safe : null;
};

// =============================
// PAGINATION (NUMBERS + JUMP)
// =============================
window.render_dpa_pagination = function (total_pages) {
  const current = window.dpa_current_page;
  let html = `<div style="text-align:center;margin:14px 0;">`;

  html += `<button class="btn btn-sm btn-default"
    ${current <= 1 ? "disabled" : ""}
    onclick="change_dpa_page(${current - 1})">Prev</button> `;

  for (let i = 1; i <= total_pages; i++) {
    if (i === current) {
      html += `<button class="btn btn-sm btn-primary" disabled>${i}</button> `;
    } else {
      html += `<button class="btn btn-sm btn-default"
        onclick="change_dpa_page(${i})">${i}</button> `;
    }
  }

  html += `<button class="btn btn-sm btn-default"
    ${current >= total_pages ? "disabled" : ""}
    onclick="change_dpa_page(${current + 1})">Next</button>

    <span style="margin-left:12px;">
      Jump:
      <input id="jump_page" type="number" min="1" max="${total_pages}"
        style="width:60px">
      <button class="btn btn-sm btn-default"
        onclick="jump_to_page(${total_pages})">Go</button>
    </span>
  </div>`;

  return html;
};

window.change_dpa_page = function (page) {
  window.dpa_current_page = page;
  window.load_dpa_page(cur_frm);
};

window.jump_to_page = function (max) {
  const v = parseInt(document.getElementById("jump_page").value);
  if (!v || v < 1 || v > max) {
    frappe.msgprint("Invalid page number");
    return;
  }
  window.change_dpa_page(v);
};

