window.get_dpa_status = function (flag) {
  const f = String(flag);
  if (f === "0") return "<span class='status-pending'>Pending</span>";
  if (f === "1") return "<span class='status-approved'>Approved</span>";
  if (f === "2") return "<span class='status-rejected'>Rejected</span>";
  return "";
};

