// =======================================================
// STOCK ENTRY – AUTO SYNC CUSTOM ↔ SYSTEM WAREHOUSES
// =======================================================
/*
Priority Mapping:
custom_select_source_stock → s_warehouse
custom_source_stock        → s_warehouse
custom_target_stock        → t_warehouse
*/

frappe.ui.form.on("Stock Entry", {

    // --------------------------------------------------
    // SELECT SOURCE STOCK → s_warehouse (HIGH PRIORITY)
    // --------------------------------------------------
    custom_select_source_stock(frm, cdt, cdn) {
        if (cdt !== "Stock Entry Detail") return;

        const row = locals[cdt][cdn];

        if (!row.custom_select_source_stock) {
            frappe.model.set_value(cdt, cdn, "s_warehouse", "");
            return;
        }

        frappe.model.set_value(
            cdt,
            cdn,
            "s_warehouse",
            row.custom_select_source_stock
        );
    },

    // --------------------------------------------------
    // SOURCE STOCK → s_warehouse
    // --------------------------------------------------
    custom_source_stock(frm, cdt, cdn) {
        if (cdt !== "Stock Entry Detail") return;

        const row = locals[cdt][cdn];

        // If select source stock already exists, do not override
        if (row.custom_select_source_stock) return;

        if (!row.custom_source_stock) {
            frappe.model.set_value(cdt, cdn, "s_warehouse", "");
            return;
        }

        frappe.model.set_value(
            cdt,
            cdn,
            "s_warehouse",
            row.custom_source_stock
        );
    },

    // --------------------------------------------------
    // TARGET STOCK → t_warehouse
    // --------------------------------------------------
    custom_target_stock(frm, cdt, cdn) {
        if (cdt !== "Stock Entry Detail") return;

        const row = locals[cdt][cdn];

        if (!row.custom_target_stock) {
            frappe.model.set_value(cdt, cdn, "t_warehouse", "");
            return;
        }

        frappe.model.set_value(
            cdt,
            cdn,
            "t_warehouse",
            row.custom_target_stock
        );
    },

    // --------------------------------------------------
    // ROW ADD / COPY SAFETY
    // --------------------------------------------------
    items_add(frm, cdt, cdn) {
        const row = locals[cdt][cdn];

        // Source priority
        row.s_warehouse =
            row.custom_select_source_stock ||
            row.custom_source_stock ||
            "";

        // Target
        row.t_warehouse =
            row.custom_target_stock ||
            "";
    },

    // --------------------------------------------------
    // FINAL SAFETY NET (ERP VALIDATION SAFE)
    // --------------------------------------------------
    validate(frm) {
        (frm.doc.items || []).forEach(row => {

            // Source priority
            row.s_warehouse =
                row.custom_select_source_stock ||
                row.custom_source_stock ||
                "";

            // Target
            row.t_warehouse =
                row.custom_target_stock ||
                "";
        });
    }
});

