function toggle_child_fields(frm) {
    if (!frm.fields_dict.table_yvva) return;

    const grid = frm.fields_dict.table_yvva.grid;
    const card_type = frm.doc.card_type;

    // ---- ALL CHILD FIELDS ----
    const all_fields = [
        "position",
        "stack_reference",
        "mount_on",
        "add_option",
        "stock_grade",
        "available_qty",
        "requested_qty",
        "from_source_ref",
        "part_number",
        "stack"
    ];

    // ---- HIDE ALL FIELDS FIRST ----
    all_fields.forEach(field => {
        grid.update_docfield_property(field, "hidden", 1);
    });

    // ---- SHOW BASED ON CARD TYPE ----
    if (card_type === "On Box") {
        ["position", "stack_reference", "mount_on", "add_option"]
            .forEach(field => {
                grid.update_docfield_property(field, "hidden", 0);
            });
    }

    if (card_type === "On System") {
        ["stock_grade", "available_qty", "requested_qty"]
            .forEach(field => {
                grid.update_docfield_property(field, "hidden", 0);
            });
    }

    if (card_type === "Project Card Wise") {
        ["add_option", "mount_on", "from_source_ref", "part_number", "stack"]
            .forEach(field => {
                grid.update_docfield_property(field, "hidden", 0);
            });
    }

    // ---- FORCE GRID REFRESH ----
    frm.refresh_field("table_yvva");
}

