function update_fa_mdb_options(frm) {

    const comp_type = frm.doc.component_type;

    // Clear options if component type not selected
    if (!comp_type) {
        if (frm.fields_dict.fa_component_details) {
            frm.fields_dict.fa_component_details.grid.update_docfield_property(
                "mdb_part_no",
                "options",
                ""
            );
        }
        frm.refresh_field("fa_component_details");
        return;
    }

    // Fetch MDB part numbers from Stock Entry Detail
    frappe.db.get_list("Stock Entry Detail", {
        fields: ["custom_mdb_part_no"],
        filters: {
            custom_select_component_type: comp_type
        },
        limit: 500
    }).then(res => {

        const mdb_list = [
            ...new Set(res.map(r => r.custom_mdb_part_no).filter(Boolean))
        ];

        const options = ["", ...mdb_list].join("\n");

        if (frm.fields_dict.fa_component_details) {
            frm.fields_dict.fa_component_details.grid.update_docfield_property(
                "mdb_part_no",
                "options",
                options
            );
