function update_custom_fields(frm) {
  if (!frm.doc.items || frm.doc.items.length === 0) return;

  const po_list = [...new Set(frm.doc.items.map(d => d.purchase_order).filter(Boolean))];
  const project_list = [...new Set(frm.doc.items.map(d => d.project).filter(Boolean))];

  const po = po_list.length ? po_list[0] : "";
  const project = project_list.length ? project_list[0] : "";

  // --- Set PO No ---
  if (po && frm.doc.custom_enter_po_no !== po) {
    frm.set_value("custom_enter_po_no", po);
  } else if (!po && frm.doc.custom_enter_po_no) {
    frm.set_value("custom_enter_po_no", "");
  }

  // --- Set Project from child row if available ---
  if (project && frm.doc.custom_project_save !== project) {
    frm.set_value("custom_project_save", project);
  }

  // --- Fetch PO parent fields (transaction_date + custom_project_save) ---
  if (po) {
    frappe.db.get_value(
      "Purchase Order",
      po,
      ["transaction_date", "custom_project_save"]
    ).then(r => {
      if (!r || !r.message) return;
      const po_data = r.message;

      if (po_data.transaction_date) {
        frm.set_value("custom_select_po_date", po_data.transaction_date);
      }

      // 🔹 Fetch from PO parent field (overrides child)
      if (po_data.custom_project_save) {
        frm.set_value("custom_project_save", po_data.custom_project_save);
      }
    });
  } else {
    // Clear if no PO
    frm.set_value("custom_select_po_date", "");
    frm.set_value("custom_project_save", "");
  }
}

