/*************************************************************
 * STOCK ENTRY – CQCD → STORE FLEXIBLE FLOW
 *************************************************************/

// ------------------------------------------------------------
// 1. DEFINITIONS (MATCHING YOUR WAREHOUSES)
// ------------------------------------------------------------

// CQCD stages in order
const CQCD_ORDER = [
    "Incoming Area - N",
    "Storage Rack - N",
    "Packing Area - N",
    "Purging Area - N"
];

// Final store roots
const FINAL_STORE_ROOTS = ["ISITE - N", "URSC - N"];

// ------------------------------------------------------------
// 2. HELPER FUNCTIONS
// ------------------------------------------------------------

// Check if warehouse is CQCD
function is_cqcd(wh) {
    return CQCD_ORDER.includes(wh);
}

// Get allowed targets from a source warehouse
function get_allowed_targets(source) {
    let targets = [];

    if (!source) return targets;

    // -------------------------
    // CQCD → CQCD (forward only)
    // -------------------------
    if (is_cqcd(source)) {
        const idx = CQCD_ORDER.indexOf(source);

        // Forward CQCD stages
        for (let i = idx + 1; i < CQCD_ORDER.length; i++) {
            targets.push(CQCD_ORDER[i]);
        }

        // CQCD → Stores (always allowed)
        targets = targets.concat(FINAL_STORE_ROOTS);
    }

    return targets;
}

// ------------------------------------------------------------
// 3. APPLY TARGET WAREHOUSE FILTER
// ------------------------------------------------------------
frappe.ui.form.on("Stock Entry", {
    onload(frm) {
        apply_target_filter(frm);
    },
    refresh(frm) {
        apply_target_filter(frm);
    },

    validate(frm) {
        validate_flow(frm);
    }
});

function apply_target_filter(frm) {
    frm.set_query("custom_target_stock", "items", function (doc, cdt, cdn) {
        const row = locals[cdt][cdn];
        const source = row.custom_source_stock;

        const allowed = get_allowed_targets(source);

        if (!allowed.length) {
            return {
                filters: {
                    name: ["=", "__never__"]
                }
            };
        }

        return {
            filters: {
                name: ["in", allowed],
                //is_group: 0
            }
        };
    });
}

// ------------------------------------------------------------
// 4. VALIDATION (FINAL SAFETY)
// ------------------------------------------------------------
function validate_flow(frm) {
    if (!frm.doc.items || !frm.doc.items.length) {
        frappe.throw("Please add at least one item");
    }

    frm.doc.items.forEach(row => {
        const s = row.custom_source_stock;
        const t = row.custom_target_stock;

        if (!s || !t) {
            frappe.throw("Source and Target Stock are mandatory");
        }

        if (s === t) {
            frappe.throw("Source and Target Stock cannot be the same");
        }

        const allowed = get_allowed_targets(s);

        if (!allowed.includes(t)) {
            frappe.throw(
                __("Transfer from {0} to {1} is not allowed", [s, t])
            );
        }
    });
}

