function validate_remaining_cards(frm) {

    if (!frm.doc.pack_name || !frm.doc.card_name) {
        return;
    }

    let entered_cards = parseInt(frm.doc.card_name || 0);

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "PRJ_CARDS",
            filters: {
                pack_name: frm.doc.pack_name,
                name: ["!=", frm.doc.name]   // exclude current doc
            },
            fields: ["card_name"]
        },
        callback: function (r) {

            let used_cards = 0;

            (r.message || []).forEach(row => {
                used_cards += parseInt(row.card_name || 0);
            });

            let remaining = parseInt(frm.doc.package_card_count || 0) - used_cards;

            if (entered_cards > remaining) {
                frappe.msgprint({
                    title: __("Limit Exceeded"),
                    message: __(
                        `Only ${remaining} cards remaining for this Package`
                    ),
                    indicator: "red"
                });

                frm.set_value("card_name", "");
            }
        }
    });
}

