function update_mdb_options(frm) {

    const comp_type = frm.doc.component_type;

    // Clear options if no component type
    if (!comp_type) {
        if (frm.fields_dict.failure_components) {
            frm.fields_dict.failure_components.grid.update_docfield_property(
                "mdb_part_no",
                "options",
                ""
            );
        }
        frm.refresh_field("failure_components");
        return;
    }

    // Fetch MDB part numbers from Stock Entry Detail
    frappe.db.get_list("Stock Entry Detail", {
        fields: [
            "custom_mdb_part_no"
        ],
        filters: {
            custom_select_component_type: comp_type
        },
        limit: 500
    }).then(res => {

        // Remove duplicates and empty values
        const mdb_list = [
            ...new Set(res.map(r => r.custom_mdb_part_no).filter(Boolean))
        ];

        // Convert array to Select options (newline separated)
        const options = ["", ...mdb_list].join("\n");

        if (frm.fields_dict.failure_components) {
            frm.fields_dict.failure_components.grid.update_docfield_property(
                "mdb_part_no",
                "options",
                options
            );
        }

        frm.refresh_field("failure_components");
    });
}

