frappe.ui.form.on("Failure Request", {
    request_number(frm) {

        // Case 1: New Request
        if (!frm.doc.request_number || frm.doc.request_number === 0) {
            frm.clear_table("fa_component_details");
            frm.refresh_field("fa_component_details");

            frappe.msgprint("New Failure Request. Please enter details.");
            return;
        }

        // Case 2: Existing Request → Fetch Data
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Failure Request",
                filters: {
                    request_number: frm.doc.request_number
                },
                fields: ["name"],
                limit: 1
            },
            callback(r) {

                if (!r.message || r.message.length === 0) {
                    frappe.msgprint("No Failure Request found for this Request Number.");
                    return;
                }

                let old_docname = r.message[0].name;

                // Fetch full document
                frappe.call({
                    method: "frappe.client.get",
                    args: {
                        doctype: "Failure Request",
                        name: old_docname
                    },
                    callback(res) {

                        let old_doc = res.message;

                        // ----------------------------
                        // COPY FAILURE DETAILS (HEADER)
                        // ----------------------------
                        const header_fields = [
                            "failed_during",
                            "project_model",
                            "pack_code",
                            "failed_at",
                            "environmental_test_condition",
                            "failure_type",
                            "select_project",
                            "ecad_card_name",
                            "failure_mode",
                            "reported_failure",
                            "specify_failure_type",
                            "select_sub_system",
                            "specify_failure_mode",
                            "description"
                        ];

                        header_fields.forEach(f => {
                            frm.set_value(f, old_doc[f]);
                        });

                        // ----------------------------
                        // COPY CHILD TABLE
                        // ----------------------------
