function update_mdb_number_options(frm, cdt, cdn) {

    const row = locals[cdt][cdn];
    const item_group = row.type;

    if (!item_group) {
        frappe.model.set_value(cdt, cdn, "mdb_number", "");
        frappe.model.set_value(cdt, cdn, "date_code", "");
        frappe.model.set_value(cdt, cdn, "quality", "");
        return;
    }

    frappe.db.get_list("Stock Entry Detail", {
        fields: [
            "custom_select_component_type",
            "custom_mdb_part_no",
            "custom_date_code",
            "custom_quality"
        ],
        filters: {
            custom_select_component_type: item_group
        },
        limit: 100
    }).then(res => {

        const options = res
            .map(r => r.custom_mdb_part_no)
            .filter(Boolean);

        // Child table fieldname
        if (frm.fields_dict.table_bnpa) {
            frm.fields_dict.table_bnpa.grid.update_docfield_property(
                "mdb_number",
                "options",
                ["", ...options]
            );
        }

        // Reset if invalid
        if (!options.includes(row.mdb_number)) {
            frappe.model.set_value(cdt, cdn, "mdb_number", "");
            frappe.model.set_value(cdt, cdn, "date_code", "");
            frappe.model.set_value(cdt, cdn, "quality", "");
        } else {
            // Auto-fill date_code + quality if valid
            const matched = res.find(
                r => r.custom_mdb_part_no === row.mdb_number
            );

            if (matched) {
                frappe.model.set_value(
                    cdt,
                    cdn,
                    "date_code",
                    matched.custom_date_code || ""
                );
                frappe.model.set_value(
                    cdt,
                    cdn,
                    "quality",
                    matched.custom_quality || ""
                );
            }
        }

        frm.refresh_field("table_bnpa");
    });
}

