// Fetch from Stock Entry
// ==========================================================
function fetch_from_stock_entry(frm, stock_entry) {
    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Stock Entry",
            name: stock_entry
        },
        callback(r) {
            const doc = r.message;

            if (!doc || !doc.items || !doc.items.length) {
                frappe.msgprint("No items found in Stock Entry");
                return;
            }

            // Set parent field
            frm.set_value("stock_entry_id", stock_entry);

            // Clear child table
            frm.clear_table("table_jfmm");

            // Fill child table
            doc.items.forEach(se => {
                let row = frm.add_child("table_jfmm");

                row.component_type   = se.custom_select_component_type;
                row.link_part_number = se.item_code;
                row.date_code        = se.custom_date_code;
                row.quantity         = se.qty;
                row.mdb_part_number  = se.custom_mdb_part_no;
                row.quality          = se.custom_quality;

                // Defaults
                row.incoming_quantity = 0;
                row.pending_quantity  = se.qty;
            });

            frm.refresh_field("table_jfmm");

            // --------------------------------------------------
            // Make fetched fields READ ONLY (except Incoming Qty)
            // --------------------------------------------------
            const grid = frm.fields_dict.table_jfmm.grid;

            grid.docfields.forEach(df => {
                if (df.fieldname !== "incoming_quantity") {
                    grid.update_docfield_property(df.fieldname, "read_only", 1);
                }
            });

            frappe.show_alert({
                message: "Stock Entry fetched successfully",
                indicator: "green"
            });
        }
    });
}

