frappe.ui.form.on("SIV RETURN", {

    refresh(frm) {
        if (frm.fields_dict.add_html) {
            frm.fields_dict.add_html.$wrapper
                .find("#add_btn")
                .off("click")
                .on("click", function () {
                    frm.trigger("fetch_card_data");
                });
        }
    },

    async fetch_card_data(frm) {

        if (!frm.doc.pack_name || !frm.doc.card) {
            frappe.msgprint("Please select Package and Card first.");
            return;
        }

        frm.clear_table("table_feqz");
        frm.refresh_field("table_feqz");

        // STEP 1: Get Approved Designer Document
        let parent_docs = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Cardwise Component List Update and Approve - Designer",
                filters: {
                    pack_name: frm.doc.pack_name,
                    card_name: frm.doc.card,
                    docstatus: 1
                },
                fields: ["name"],
                limit_page_length: 1
            }
        });

        if (!parent_docs.message || parent_docs.message.length === 0) {
            frappe.msgprint("No approved data found.");
            return;
        }

        // STEP 2: Fetch Full Document
        let full_doc = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Cardwise Component List Update and Approve - Designer",
                name: parent_docs.message[0].name
            }
        });

        let doc = full_doc.message;

        // STEP 3: AUTO-DETECT CHILD TABLE
        let child_items = [];

        Object.keys(doc).forEach(key => {
            if (
                Array.isArray(doc[key]) &&
                doc[key].length &&
                typeof doc[key][0] === "object" &&
                doc[key][0].hasOwnProperty("component_type")
            ) {
                child_items = doc[key];
            }
        });

        if (!child_items.length) {
            frappe.msgprint("Component items exist, but child table not detected.");
            return;
        }

        // STEP 4: INSERT INTO SIV RETURN CHILD TABLE
        child_items.forEach(item => {

            let row = frm.add_child("table_feqz");

            row.type = item.component_type || "";
            row.mdb_partno = item.mdb_part_number || "";
            row.date_code = item.date_code || "";
            row.expiry_date = item.expiry_date || "";
            row.manufacturer = item.manufacturer || "";
        });

        frm.refresh_field("table_feqz");
    },

    validate(frm) {
        if (!frm.doc.table_feqz || frm.doc.table_feqz.length === 0) {
            frappe.msgprint("Please fetch items before saving.");
            frappe.validated = false;
        }
    }
});

