// =================================================
// LOAD MDB PART NUMBERS BASED ON COMPONENT TYPE
// =================================================
function update_mdb_part_number_options(frm, cdt, cdn) {

    const row = locals[cdt][cdn];
    const component_type = row.component_type;

    if (!component_type) {
        frappe.model.set_value(cdt, cdn, "mdb_part_number", "");
        frappe.model.set_value(cdt, cdn, "date_code", "");
        return;
    }

    frappe.db.get_list("Stock Entry Detail", {
        fields: [
            "custom_select_component_type",
            "custom_mdb_part_no",
            "custom_date_code"
        ],
        filters: {
            custom_select_component_type: component_type
        },
        limit: 100
    }).then(res => {

        // Build Select options
        const options = res
            .map(r => r.custom_mdb_part_no)
            .filter(Boolean);

        // Update Select field options in child table
        if (frm.fields_dict.table_yvva) {
            frm.fields_dict.table_yvva.grid.update_docfield_property(
                "mdb_part_number",
                "options",
                ["", ...options]
            );
        }

        // Reset values if current MDB is invalid
        if (!options.includes(row.mdb_part_number)) {
            frappe.model.set_value(cdt, cdn, "mdb_part_number", "");
            frappe.model.set_value(cdt, cdn, "date_code", "");
        } else {
            // Auto-fill date_code if valid
            const matched = res.find(
                r => r.custom_mdb_part_no === row.mdb_part_number
            );

            if (matched) {
                frappe.model.set_value(
                    cdt,
                    cdn,
                    "date_code",
                    matched.custom_date_code || ""
                );
            }
        }

        frm.refresh_field("table_yvva");
    });
}

