// ==========================================================
// Fetch from Purging Area
// ==========================================================
function fetch_from_purging_area(frm, purging_area) {
    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Purging Area",
            name: purging_area
        },
        callback(r) {
            const doc = r.message;

            if (!doc || !doc.table_assg || !doc.table_assg.length) {
                frappe.msgprint("No data found in Purging Area");
                return;
            }

            // Parent visibility
            frm.set_value("purging_area_id", purging_area);
            frm.set_df_property("purging_area_id", "hidden", 0);
            frm.set_df_property("stock_entry_id", "hidden", 1);
            frm.set_value("stock_entry_id", "");

            frm.clear_table("table_cngj");

            doc.table_assg.forEach(pa => {
                let row = frm.add_child("table_cngj");

                row.stock_entry_id   = doc.stock_entry_id;
                row.component_type   = pa.component_type;
                row.link_part_number = pa.link_part_number;
                row.date_code        = pa.date_code;
                row.quantity         = pa.quantity;
                row.purging_quantity = pa.purging_quantity;
                row.mdb_part_number  = pa.mdb_part_number;
                row.quality          = pa.quality;

                // defaults
                row.storage_rack_quantity = 0;
                row.pending_quantity = pa.quantity;
            });

            frm.refresh_field("table_cngj");

            // Show child Stock Entry ID & Purging Quantity
            toggle_child_columns(frm, {
                stock_entry_id: 0,
                purging_quantity: 0
            });

            set_read_only_except_storage_qty(frm);

            frappe.show_alert({
                message: "Purging Area data fetched successfully",
                indicator: "green"
            });
        }
    });
}

