// ==========================================================
// Storage Rack Quantity → Pending Quantity Calculation
// ==========================================================
frappe.ui.form.on("Storage Rack Table", {
    storage_rack_quantity(frm, cdt, cdn) {
        const r = locals[cdt][cdn];

        const qty = r.quantity || 0;
        const rack_qty = r.storage_rack_quantity || 0;

        if (rack_qty > qty) {
            frappe.msgprint(
                "Storage Rack Quantity cannot exceed Quantity"
            );
            r.storage_rack_quantity = 0;
        }

        // ✅ Pending Quantity = Quantity - Storage Rack Quantity
        r.pending_quantity = Math.max(
            (r.quantity || 0) - (r.storage_rack_quantity || 0),
            0
        );

        frm.refresh_field("table_cngj");
    }
});

// ==========================================================
// Storage Rack Quantity → Validation & Pending Calculation
// ==========================================================
frappe.ui.form.on("Storage Rack Table", {
    storage_rack_quantity(frm, cdt, cdn) {
        const r = locals[cdt][cdn];

        const rack_qty = r.storage_rack_quantity || 0;

        // =========================================
        // CASE 1: DATA FROM PURGING AREA
        // =========================================
        if (frm.doc.purging_area_id) {
            const purging_qty = r.purging_quantity || 0;

            if (rack_qty > purging_qty) {
                frappe.msgprint(
                    "Storage Rack Quantity cannot exceed Purging Quantity"
                );
                r.storage_rack_quantity = 0;
            }

            // Pending = Purging Quantity - Storage Rack Quantity
            r.pending_quantity = Math.max(
                (r.purging_quantity || 0) - (r.storage_rack_quantity || 0),
                0
            );
        }

        // =========================================
        // CASE 2: DATA FROM STOCK ENTRY
        // =========================================
        else {
            const qty = r.quantity || 0;

            if (rack_qty > qty) {
                frappe.msgprint(
                    "Storage Rack Quantity cannot exceed Quantity"
                );
                r.storage_rack_quantity = 0;
            }

            // Pending = Quantity - Storage Rack Quantity
            r.pending_quantity = Math.max(
                (r.quantity || 0) - (r.storage_rack_quantity || 0),
                0
            );
        }

        frm.refresh_field("table_cngj");
    }
});

