frappe.ui.form.on("Packing Area Table", {
    packing_quantity(frm, cdt, cdn) {
        const r = locals[cdt][cdn];

        // ❌ INVALID: Packing > Storage Rack
        if ((r.packing_quantity || 0) > (r.storage_rack_quantity || 0)) {
            frappe.msgprint(
                "Packing Quantity cannot exceed Storage Rack Quantity"
            );
            r.packing_quantity = 0;
        }

        // ✅ Pending = Storage Rack - Packing
        r.pending_quantity = Math.max(
            (r.storage_rack_quantity || 0) - (r.packing_quantity || 0),
            0
        );

        frm.refresh_field("table_oghs");
    }
});

