// ==========================================================
// Fetch from Stock Entry → Purging Area
// ==========================================================
function fetch_from_stock_entry_for_purging(frm, stock_entry) {
    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Stock Entry",
            name: stock_entry
        },
        callback(r) {
            const doc = r.message;

            if (!doc || !doc.items || !doc.items.length) {
                frappe.msgprint("No items found in Stock Entry");
                return;
            }

            // Set parent reference
            frm.set_value("stock_entry_id", stock_entry);

            // Clear child table (✅ FIXED)
            frm.clear_table("table_assg");

            // Populate child table
            doc.items.forEach(se => {
                let row = frm.add_child("table_assg");

                row.stock_entry_id   = doc.name;
                row.component_type   = se.custom_select_component_type;
                row.link_part_number = se.item_code;
                row.date_code        = se.custom_date_code;
                row.quantity         = se.qty;
                row.mdb_part_number  = se.custom_mdb_part_no;
                row.quality          = se.custom_quality;

                // Defaults
                //row.purged_quantity  = 0;
                //row.pending_quantity = se.qty;
            });

            frm.refresh_field("table_assg");

            // --------------------------------------------------
            // Make fetched fields READ ONLY (except Purged Qty)
            // --------------------------------------------------
            const grid = frm.fields_dict.table_assg.grid;

            grid.docfields.forEach(df => {
                if (df.fieldname !== "purged_quantity") {
                    grid.update_docfield_property(df.fieldname, "read_only", 1);
                }
            });

            frappe.show_alert({
                message: "Stock Entry fetched successfully",
                indicator: "green"
            });
        }
    });
}


