frappe.ui.form.on("Purging Area Table", {
    purged_quantity(frm, cdt, cdn) {
        const r = locals[cdt][cdn];

        if ((r.purged_quantity || 0) > (r.quantity || 0)) {
            frappe.msgprint("Purged Quantity cannot exceed Stock Quantity");
            r.purged_quantity = 0;
        }

        r.pending_quantity =
            (r.quantity || 0) - (r.purged_quantity || 0);

        frm.refresh_field("table_assg");
    }
});

