    custom_select_project(frm) {
        if (!frm.doc.custom_select_project) return;

        frappe.call({
            method: 'ursc_cms_app.api.make_pr_from_po_like_standard',
            args: {
                po_name: frm.doc.custom_select_project   // ✅ PASS ARGUMENT
            },
            freeze: true,
            callback: function (r) {
                if (!r.message || !r.message.doctype) {
                    frappe.msgprint(__('Failed to load Purchase Order'));
                    return;
                }

                // Load returned PR document into client
                frappe.model.sync(r.message);

                // Route to the created Purchase Receipt
                frappe.set_route(
                    'Form',
                    r.message.doctype,
                    r.message.name || frappe.model.get_new_name(r.message.doctype)
                );
            }
        });
    }
});

