// --------------------------------------------------
// 🔹 CHILD TABLE WAREHOUSE FILTER LOGIC (3 LEVEL)
// --------------------------------------------------
function set_child_warehouse_queries(frm) {

  const grid = frm.fields_dict.select_warehouse.grid;

  // 1️⃣ STORE → children of STORE - N
  grid.get_field("select_store").get_query = function () {
    return {
      filters: {
        parent_warehouse: "STORE - N",
        is_group: 1
      }
    };
  };

  // 2️⃣ PROGRAM → children of selected Store
  grid.get_field("select_program").get_query = function (doc, cdt, cdn) {
    const row = locals[cdt][cdn];
    if (!row.select_store) {
      frappe.msgprint("Please select Store first");
      return { filters: { name: "No Warehouse" } };
    }
    return {
      filters: {
        parent_warehouse: row.select_store,
        is_group: 1
      }
    };
  };

  // 3️⃣ STOCK → children of selected Program
  grid.get_field("select_stock").get_query = function (doc, cdt, cdn) {
    const row = locals[cdt][cdn];
    if (!row.select_program) {
      frappe.msgprint("Please select Program first");
      return { filters: { name: "No Warehouse" } };
    }
    return {
      filters: {
        parent_warehouse: row.select_program,
        is_group: 0
      }
    };
  };
}

