frappe.ui.form.on("Project Stock Grade Priority", {

    enabled: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        // When checkbox is checked

        if (row.enabled) {

            let max_order = 0;

            // find highest existing order

            frm.doc.warehouse_priority.forEach(d => {

                if (d.selection_order > max_order) {

                    max_order = d.selection_order;

                }

            });

            // next number

            row.selection_order = max_order + 1;

        } else {

            // Checkbox unchecked → clear order

            row.selection_order = 0;

        }

        frm.refresh_field("warehouse_priority");

    }

});

