frappe.ui.form.on("SCR Request Wrt Project", {
    refresh(frm) {

        // Render button inside HTML field
        frm.fields_dict.project_info.$wrapper.html(`
            <div style="margin-top: 20px;">
                <button class="btn btn-primary" id="get_data_btn">
                    Get Data
                </button>
            </div>
        `);

        // Bind click event safely
        frm.fields_dict.project_info.$wrapper
            .find("#get_data_btn")
            .on("click", function () {

                if (frm.doc.project !== "All On Going Projects") {
                    frappe.msgprint("Please select 'All On Going Projects'");
                    return;
                }

                frm.clear_table("table_avbb");
                frm.refresh_field("table_avbb");

                // STEP 1: Fetch OPEN Projects
                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Project",
                        filters: {
                            status: ["in", ["Open", "In Progress"]]
                        },
                        fields: ["name"],
                        limit_page_length: 0
                    }
                }).then(res => {

                    if (!res.message || !res.message.length) {
                        frappe.msgprint("No Open Projects found");
                        return;
                    }

                    const project_names = res.message.map(p => p.name);

                    // STEP 2: Fetch Cardwise Docs
                    return frappe.call({
                        method: "frappe.client.get_list",
                        args: {
                            doctype: "Cardwise Component List Update and Approve - Designer",
                            filters: {
                                select_project: ["in", project_names]
                            },
                            fields: ["name"],
                            limit_page_length: 0
                        }
                    });

                }).then(cardwise_res => {

                    if (!cardwise_res || !cardwise_res.message || !cardwise_res.message.length) {
                        frappe.msgprint("No Cardwise data found");
                        return;
                    }

                    // STEP 3: Fetch Cardwise child rows
                    const chain = cardwise_res.message.reduce((p, doc) => {
                        return p.then(() => {
                            return frappe.call({
                                method: "frappe.client.get",
                                args: {
                                    doctype: "Cardwise Component List Update and Approve - Designer",
                                    name: doc.name
                                }
                            }).then(d => {
                                if (d.message && d.message.table_yvva) {
                                    d.message.table_yvva.forEach(row => {
                                        let child = frm.add_child("table_avbb");
                                        child.component_type = row.component_type;
                                        child.link_part_number = row.link_part_number;
                                    });
                                }
                            });
                        });
                    }, Promise.resolve());

                    return chain;

                }).then(() => {
                    frm.refresh_field("table_avbb");
                    frappe.msgprint("Data fetched successfully");
                });
            });
    }
});

frappe.ui.form.on("SCR Request Wrt Project", {

    project_selection_type(frm) {

        // Hide all
        frm.set_df_property("single_project", "hidden", 1);
        frm.set_df_property("projects", "hidden", 1);

        // Clear values
        frm.set_value("single_project", null);
        frm.clear_table("projects");
        frm.refresh_field("projects");

        // Show based on selection
        if (frm.doc.project_selection_type === "Single Project") {
            frm.set_df_property("single_project", "hidden", 0);
        }

        if (frm.doc.project_selection_type === "Multiple Projects") {
            frm.set_df_property("projects", "hidden", 0);
        }
    },

    refresh(frm) {

        // Render button
        frm.fields_dict.project_info.$wrapper.html(`
            <div style="margin-top:20px;">
                <button class="btn btn-primary" id="get_data_btn">
                    Get Data
                </button>
            </div>
        `);

        frm.fields_dict.project_info.$wrapper
            .find("#get_data_btn")
            .off("click")
            .on("click", function () {

                /* ---------------- VALIDATION ---------------- */

                if (!frm.doc.project_selection_type) {
                    frappe.msgprint("Please select Project Selection Type");
                    return;
                }

                if (
                    frm.doc.project_selection_type === "Single Project" &&
                    !frm.doc.single_project
                ) {
                    frappe.msgprint("Please select a Project");
                    return;
                }

                if (
                    frm.doc.project_selection_type === "Multiple Projects" &&
                    (!frm.doc.projects || frm.doc.projects.length === 0)
                ) {
                    frappe.msgprint("Please select at least one Project");
                    return;
                }

                frm.clear_table("table_avbb");
                frm.refresh_field("table_avbb");

                let projectPromise;

                /* ---------------- PROJECT LIST ---------------- */

                if (frm.doc.project_selection_type === "All Projects") {

                    projectPromise = frappe.call({
                        method: "frappe.client.get_list",
                        args: {
                            doctype: "Project",
                            filters: {
                                status: ["in", ["Open", "In Progress"]]
                            },
                            fields: ["name"],
                            limit_page_length: 0
                        }
                    }).then(r => r.message.map(p => p.name));

                } else if (frm.doc.project_selection_type === "Single Project") {

                    projectPromise = Promise.resolve([frm.doc.single_project]);

                } else {

                    projectPromise = Promise.resolve(
                        frm.doc.projects.map(r => r.project)
                    );
                }

                /* ---------------- FETCH CARDWISE DOCS ---------------- */

                projectPromise
                    .then(projectNames => {
                        return frappe.call({
                            method: "frappe.client.get_list",
                            args: {
                                doctype: "Cardwise Component List Update and Approve - Designer",
                                filters: {
                                    select_project: ["in", projectNames]
                                },
                                fields: ["name"],
                                limit_page_length: 0
                            }
                        });
                    })

                    /* ---------------- FETCH CHILD ROWS (DEDUP) ---------------- */

                    .then(cardwiseRes => {

                        if (!cardwiseRes.message || !cardwiseRes.message.length) {
                            frappe.msgprint("No Cardwise data found");
                            return;
                        }

                        const addedKeys = new Set();

                        const chain = cardwiseRes.message.reduce((p, doc) => {
                            return p.then(() => {
                                return frappe.call({
                                    method: "frappe.client.get",
                                    args: {
                                        doctype: "Cardwise Component List Update and Approve - Designer",
                                        name: doc.name
                                    }
                                }).then(d => {
                                    if (d.message?.table_yvva) {
                                        d.message.table_yvva.forEach(row => {

                                            const key = `${row.component_type}|${row.link_part_number}`;

                                            if (addedKeys.has(key)) return;

                                            addedKeys.add(key);

                                            let child = frm.add_child("table_avbb");
                                            child.component_type = row.component_type;
                                            child.link_part_number = row.link_part_number;
                                        });
                                    }
                                });
                            });
                        }, Promise.resolve());

                        return chain;
                    })

                    .then(() => {
                        frm.refresh_field("table_avbb");
                        frappe.msgprint("Data fetched successfully");
                    });
            });
    }
});

frappe.ui.form.on('SIV Request Process', {
  refresh(frm) {
    // Filter Sub System based on selected Project
    frm.set_query('select_sub_system', () => {
      if (!frm.doc.select_project) {
        return { filters: [['name', '=', '__none__']] };
      }
      return { filters: [['select_project', '=', frm.doc.select_project]] };
    });

    // Filter Packages based on selected Sub System
    frm.set_query('pack_name', () => {
      if (!frm.doc.select_sub_system) {
        return { filters: [['name', '=', '__none__']] };
      }
      return { filters: [['select_sub_system', '=', frm.doc.select_sub_system]] };
    });

    // Init allowed cards
    frm.allowed_cards = [];

    // Filter select_card based on cards from SIV Request Approval
    frm.set_query('select_card', () => {
      if (!frm.doc.pack_name || !frm.allowed_cards.length) {
        return { filters: [['name', '=', '__none__']] };
      }
      return {
        filters: [['name', 'in', frm.allowed_cards]]
      };
    });
  },

  // When Package changes
  pack_name(frm) {
    frm.set_value('select_card', null);
    frm.allowed_cards = [];

    if (!frm.doc.pack_name) {
      frm.refresh_field('select_card');
      return;
    }

    // Fetch cards from SIV Request Approval
    frappe.db.get_list('SIV Request Approval', {
      filters: { pack_name: frm.doc.pack_name },
      fields: ['select_card'],
      limit_page_length: 0
    }).then(rows => {
      frm.allowed_cards = [
        ...new Set(
          rows.map(r => r.select_card).filter(Boolean)
        )
      ];
      frm.refresh_field('select_card');
    });
  },

  // When Project changes
  select_project(frm) {
    frm.set_value('select_sub_system', null);
    frm.set_value('pack_name', null);
    frm.set_value('select_card', null);
    frm.allowed_cards = [];
  },

  // When Sub System changes
  select_sub_system(frm) {
    frm.set_value('pack_name', null);
    frm.set_value('select_card', null);
    frm.allowed_cards = [];
  }
});

frappe.ui.form.on("SCR Request Wrt Project", {
    refresh(frm) {

        frm.add_custom_button(__("ADD"), function () {

            // Safety check
            if (!frm.doc.siv_dispatch) {
                frappe.msgprint("Please select SIV Dispatch first");
                return;
            }

            if (!frm.doc.table_avbb || frm.doc.table_avbb.length === 0) {
                frappe.msgprint("No items to fetch");
                return;
            }

            // 1️⃣ Fetch the SIV Dispatch document ONCE
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "SIV Dispatch",
                    name: frm.doc.siv_dispatch
                },
                callback: function (r) {

                    if (!r.message || !r.message.siv_dispatch_items) {
                        frappe.msgprint("No Dispatch Items found");
                        return;
                    }

                    const dispatch_items = r.message.siv_dispatch_items;

                    // 2️⃣ Loop through SCR child rows
                    frm.doc.table_avbb.forEach(row => {

                        if (!row.link_part_number) return;

                        // 3️⃣ Find matching dispatch item
                        const siv = dispatch_items.find(
                            d => d.link_part_number === row.link_part_number
                        );

                        if (!siv) {
                            console.warn(
                                "No Dispatch data for",
                                row.link_part_number
                            );
                            return;
                        }

                        // 4️⃣ Populate SCR fields
                        row.valid_available_stock = siv.available_qty || 0;
                        row.requested_quantity = siv.requested_qty || 0;
                        row.issued = siv.issued || 0;
                        row.balance_requried = siv.balance_qty || 0;
                    });

                    // 5️⃣ Refresh once
                    frm.refresh_field("table_avbb");
                    frappe.msgprint("Dispatch quantities fetched successfully");
                }
            });
        });
    }
});

