frappe.ui.form.on("Warehouse Rack Master", {
    select_warehouse(frm) {
        // Clear previously selected block
        frm.set_value("select_block", "");

        // Filter Block Master by selected warehouse
        frm.set_query("select_block", () => {
            return {
                filters: {
                    select_warehouse: frm.doc.select_warehouse
                }
            };
        });
    }
});

frappe.ui.form.on("Warehouse Block Master", {

  // --------------------------------------------
  // When Warehouse changes → filter Locations
  // --------------------------------------------
  select_warehouse(frm) {

    // Clear dependent fields
    frm.set_value("select_location", "");
    frm.set_value("enter_block", "");

    if (!frm.doc.select_warehouse) return;

    frm.set_query("select_location", function () {
      return {
        filters: {
          select_warehouse: frm.doc.select_warehouse
        }
      };
    });
  },

  // --------------------------------------------
  // Support "Add New Block" from other forms
  // --------------------------------------------
  select_location(frm) {
    if (!frm.doc.select_warehouse || !frm.doc.select_location) return;

    frappe.route_options = {
      select_warehouse: frm.doc.select_warehouse,
      select_location: frm.doc.select_location
    };
  }

});

