/*****************************************************
 * SRN_POST PRINT – REPORT FORMAT
 *****************************************************/
function srn_post_print_report(frm) {

    const d = frm.doc;
    const rows = d.table_agsm || [];
    const today = frappe.datetime.get_today();
    const month = frappe.datetime.str_to_obj(today).toLocaleString("en-IN",{month:"long"}).toUpperCase();
    const ref_code = "URSC-SRN-" + month;
    const username = frappe.session.user_fullname || frappe.session.user;


    // === FIELD ORDER (3-COLUMN INFO) ===
    const fields = [
        ["SRN Ref No", d.srn_ref_no],
        ["SIV No", d.siv_no],
        ["SIV Date", d.siv_date],
        ["Project", d.project],
        ["Posted From", d.posted_from],
        ["Screened At", d.screened_at],
        ["Batch No", d.batch_no],
    ];


    function renderAs3Columns(){
        let html = '<table style="width:100%; font-size:11px;">';
        for (let i = 0; i < fields.length; i+=3) {
            html += "<tr>";
            for (let j = i; j < i+3; j++){
                if(fields[j]){
                    html += `<td style="padding:4px;"><b>${fields[j][0]}:</b> ${fields[j][1] || ""}</td>`;
                } else {
                    html += "<td></td>";
                }
            }
            html += "</tr>";
        }
        html += "</table><div style='border-top:1px solid #000; margin:10px 0;'></div>";
        return html;
    }


    // === OPEN NEW PRINT WINDOW ===
    const win = window.open("", "_blank");
    win.document.write(`
