/**
 * Get ACTUAL warehouse from child table (select_stock)
 * Assumption: one active stock per Cardex
 */
function get_actual_stock(frm) {
    const rows = frm.doc.select_warehouse || [];

    for (let i = 0; i < rows.length; i++) {
        if (rows[i].select_stock) {
            return rows[i].select_stock;
        }
    }
    return null;
}

/**
 * Filter Block based on actual stock warehouse
 */
function filter_block(frm) {
    const stock = get_actual_stock(frm);

    if (!stock) {
        frm.set_query("block", () => {
            return { filters: {} };
        });
        return;
    }

    frm.set_query("block", () => {
        return {
            filters: {
                select_warehouse: stock
            }
        };
    });
}

/**
 * Filter Rack based on selected Block + actual stock
 */
function filter_rack(frm) {
    const stock = get_actual_stock(frm);

    if (!stock || !frm.doc.block) {
        frm.set_query("rack", () => {
            return { filters: {} };
        });
        return;
    }

    frm.set_query("rack", () => {
        return {
            filters: {
                select_warehouse: stock,
                select_block: frm.doc.block
            }
        };
    });
}

