frappe.ui.form.on('SIV Request Approval', {
  refresh(frm) {

    // Filter Sub System based on selected Project
    frm.set_query('select_sub_system', () => {
      if (!frm.doc.select_project) {
        return { filters: [['name', '=', '__none__']] };
      }
      return {
        filters: [['select_project', '=', frm.doc.select_project]]
      };
    });

    // Filter Packages based on selected Sub System
    frm.set_query('pack_name', () => {
      if (!frm.doc.select_sub_system) {
        return { filters: [['name', '=', '__none__']] };
      }
      return {
        filters: [['select_sub_system', '=', frm.doc.select_sub_system]]
      };
    });

    // ✅ Filter Cards based on Package + Approved only
    frm.set_query('select_card', () => {
      if (!frm.doc.pack_name) {
        return { filters: [['name', '=', '__none__']] };
      }
      return {
        filters: [
          ['pack_name', '=', frm.doc.pack_name],
          ['workflow_state', '=', 'Approved']
        ]
      };
    });
  },

  // When Project changes
  select_project(frm) {
    frm.set_value('select_sub_system', null);
    frm.set_value('pack_name', null);
    frm.set_value('select_card', null);
  },

  // When Sub System changes
  select_sub_system(frm) {
    frm.set_value('pack_name', null);
    frm.set_value('select_card', null);
  },

  // When Package changes
  pack_name(frm) {
    frm.set_value('select_card', null);
  }
});

frappe.ui.form.on("SIV", {

    refresh(frm) {
        const wrapper = frm.fields_dict.add_html?.$wrapper;
        if (!wrapper) return;

        wrapper.find("#add_btn")
            .off("click")
            .on("click", () => {
                frm.trigger("fetch_approved_data");
            });
    },

    async fetch_approved_data(frm) {

        // 1️⃣ Card mandatory
        if (!frm.doc.select_card) {
            frappe.msgprint("Please select a Card first.");
            return;
        }

        // 2️⃣ Prevent duplicate fetch for same card
        if (frm.doc.fetched_card === frm.doc.select_card && frm.doc.table_bnpa?.length) {
            frappe.msgprint({
                title: "Already Fetched",
                message: "Data for this Card is already loaded.",
                indicator: "orange"
            });
            return;
        }

        // 3️⃣ Fetch Card document
        const res = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Cardwise Component List Update and Approve - Designer",
                name: frm.doc.select_card
            }
        });

        const doc = res.message;
        if (!doc) {
            frappe.msgprint("No document found for selected Card.");
            return;
        }

        // 4️⃣ Auto-detect child table dynamically
        let child_items = [];
        Object.keys(doc).forEach(key => {
            if (Array.isArray(doc[key]) && doc[key].length && doc[key][0].requested_qty !== undefined) {
                child_items = doc[key];
            }
        });

        if (!child_items.length) {
            frappe.msgprint({
                title: "No Data",
                message: "No component rows found in selected Card.",
                indicator: "orange"
            });
            return;
        }

        // 5️⃣ Clear table for new fetch
        frm.clear_table("table_bnpa");

        // 6️⃣ Copy child rows
        child_items.forEach(row => {
            const child = frm.add_child("table_bnpa");

            child.type = row.component_type;
            child.link_part_number = row.link_part_number;
            child.symbol = row.symbol;
            child.package_style = row.package_style;
            child.category = row.category;
            child.requested_qty = row.requested_qty;
            child.remarks = row.remarks;
            child.actual_qty = row.actual_qty;
            child.add_option = row.add_option;
            child.stack_reference = row.stack_reference;
            child.entry_by = row.entry_by;
            child.rdc_reference_no = row.rdc_reference_no;
            child.stack = row.stack;
            child.functionality = row.functionality;
            child.part_number = row.part_number;
            child.serial_number = row.serial_number;
            child.expiry_date = row.expiry_date;
            child.date_code = row.date_code;
            child.mdb_part_number = row.mdb_part_number;
            child.fabricated_part_no_ceef = row.fabricated_part_no_ceef;
            child.from_source_ref = row.from_source_ref;
            child.select_issual_type = row.select_issual_type;
            child.mount_on = row.mount_on;
            child.stock_grade = row.stock_grade;
            child.position = row.position;
            child.manufacturer = row.manufacturer;
            child.remarks = row.remarks;
        });

        // 7️⃣ Store fetched card and refresh
        frm.set_value("fetched_card", frm.doc.select_card);
        frm.refresh_field("table_bnpa");

        frappe.show_alert({
            message: `Card ${frm.doc.select_card} loaded successfully`,
            indicator: "green"
        });
    },

    validate(frm) {
        if (!frm.doc.table_bnpa?.length) {
            frappe.msgprint("Please add at least one item before saving.");
            frappe.validated = false;
        }
    }
});

