frappe.ui.form.on("SCR Request Wrt Project", {
    refresh(frm) {

        frm.add_custom_button(__("ADD"), function () {

            // Safety check
            if (!frm.doc.siv_dispatch) {
                frappe.msgprint("Please select SIV Dispatch first");
                return;
            }

            if (!frm.doc.table_avbb || frm.doc.table_avbb.length === 0) {
                frappe.msgprint("No items to fetch");
                return;
            }

            // 1️⃣ Fetch the SIV Dispatch document ONCE
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "SIV Dispatch",
                    name: frm.doc.siv_dispatch
                },
                callback: function (r) {

                    if (!r.message || !r.message.siv_dispatch_items) {
                        frappe.msgprint("No Dispatch Items found");
                        return;
                    }

                    const dispatch_items = r.message.siv_dispatch_items;

                    // 2️⃣ Loop through SCR child rows
                    frm.doc.table_avbb.forEach(row => {

                        if (!row.link_part_number) return;

                        // 3️⃣ Find matching dispatch item
                        const siv = dispatch_items.find(
                            d => d.link_part_number === row.link_part_number
                        );

                        if (!siv) {
                            console.warn(
                                "No Dispatch data for",
                                row.link_part_number
                            );
                            return;
                        }

                        // 4️⃣ Populate SCR fields
                        row.valid_available_stock = siv.available_qty || 0;
                        row.requested_quantity = siv.requested_qty || 0;
                        row.issued = siv.issued || 0;
                        row.balance_requried = siv.balance_qty || 0;
                    });

                    // 5️⃣ Refresh once
                    frm.refresh_field("table_avbb");
                    frappe.msgprint("Dispatch quantities fetched successfully");
                }
            });
        });
    }
});

frappe.ui.form.on("SIV Request Approval", {

    refresh(frm) {
        const wrapper = frm.fields_dict.add_html?.$wrapper;
        if (!wrapper) return;

        wrapper.find("#add_btn")
            .off("click")
            .on("click", () => frm.trigger("fetch_approved_data"));
    },

    async fetch_approved_data(frm) {

        // 1️⃣ Card mandatory
        if (!frm.doc.select_card) {
            frappe.msgprint("Please select a Card first.");
            return;
        }

        // 2️⃣ Prevent duplicate fetch
        if (
            frm.doc.linked_siv &&            // ✅ FIX
            frm.doc.items &&
            frm.doc.items.length > 0
        ) {
            frappe.msgprint({
                title: "Already Linked",
                message: "This document is already linked with an SIV.",
                indicator: "orange"
            });
            return;
        }

        let siv_name = null;

        // =================================================
        // STEP 3: FIND SIV
        // =================================================

        let res = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "SIV",
                filters: [["reference_doc", "=", frm.doc.select_card]],
                limit_page_length: 1
            }
        });

        if (res.message?.length) {
            siv_name = res.message[0].name;
        }

        if (!siv_name) {
            res = await frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "SIV",
                    filters: [["select_card_copy", "=", frm.doc.select_card]],
                    limit_page_length: 1
                }
            });

            if (res.message?.length) {
                siv_name = res.message[0].name;
            }
        }

        // -----------------------------
        // STEP 4: Validation
        // -----------------------------
        if (!siv_name) {
            frappe.msgprint({
                title: "SIV Not Found",
                message: `No SIV linked with Card <b>${frm.doc.select_card}</b>`,
                indicator: "red"
            });
            return;
        }

        // =================================================
        // ✅ FIX: LINK SIV PERMANENTLY
        // =================================================
        await frm.set_value("linked_siv", siv_name);

        // =================================================
        // STEP 5: FETCH FULL SIV
        // =================================================
        let siv_doc = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "SIV",
                name: siv_name
            }
        });

        const doc = siv_doc.message;
        if (!doc) {
            frappe.msgprint("SIV document not found.");
            return;
        }

        // =================================================
        // STEP 6: AUTO-DETECT CHILD TABLE
        // =================================================
        let source_items = [];

        Object.keys(doc).forEach(key => {
            if (
                Array.isArray(doc[key]) &&
                doc[key].length &&
                doc[key][0].requested_qty !== undefined
            ) {
                source_items = doc[key];
            }
        });

        if (!source_items.length) {
            frappe.msgprint("No component data found in SIV.");
            return;
        }

        // =================================================
        // STEP 7: COPY DATA
        // =================================================
        frm.clear_table("items");

        source_items.forEach(row => {
            let child = frm.add_child("items");

            Object.assign(child, {
                item_code: row.type,
                component_type_copy: row.type_copy,
                link_part_number: row.link_part_number,
                link_part_number_copy: row.link_part_number_copy,
                package_style: row.package_style,
                symbol: row.symbol,
                symbol_copy: row.symbol_copy,
                mdb_part_number: row.mdb_part_number,
                category: row.category,
                mount_on: row.mount_on,
                stock_grade: row.stock_grade,
                position: row.position,
                requested_qty: row.requested_qty,
                from_source_ref: row.from_source_ref,
                select_issual_type: row.select_issual_type,
                fabricated_part_no_ceef: row.fabricated_part_no_ceef,
                part_number: row.part_number,
                add_option: row.add_option,
                stack: row.stack,
                actual_qty: row.actual_qty,
                expiry_date: row.expiry_date,
                manufacturer: row.manufacturer,
                serial_number: row.serial_number,
                rdc_reference_no: row.rdc_reference_no,
                stack_reference: row.stack_reference,
                date_code: row.date_code,
                entry_by: row.entry_by,
                functionality: row.functionality,
                remarks: row.remarks
            });
        });

        // =================================================
        // STEP 8: SAVE FETCHED CARD
        // =================================================
        frm.set_value("fetched_card", frm.doc.select_card);
        frm.refresh_field("items");

        frappe.show_alert({
            message: `SIV ${siv_name} linked & loaded successfully`,
            indicator: "green"
        });
    },

    validate(frm) {
        if (!frm.doc.items || frm.doc.items.length === 0) {
            frappe.msgprint("Please add at least one item before saving.");
            frappe.validated = false;
        }
    }
});

