// --- Move fetch function outside of frappe.ui.form.on to avoid server call confusion ---
async function fetch_approved_data(frm) {
    const card = frm.doc.select_card?.trim();
    if (!card) {
        frappe.msgprint("Please select a Card first.");
        return;
    }

    // Prevent duplicate fetch
    if (frm.doc.fetched_card === card && frm.doc.items?.length > 0) {
        frappe.msgprint({
            title: "Already Fetched",
            message: "This document is already linked with this Card.",
            indicator: "orange"
        });
        return;
    }

    // Fetch SIV Request Approval safely
    let approval_name = null;
    let res = null;

    const filters_list = [
        [["select_card", "=", card]],
        [["reference_doc", "=", card]]
    ];

    for (let filters of filters_list) {
        try {
            res = await frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "SIV Request Approval",
                    fields: ["name"],
                    filters: filters,
                    order_by: "creation desc",
                    limit_page_length: 1
                }
            });
            if (res.message?.length) {
                approval_name = res.message[0].name;
                break;
            }
        } catch (e) {
            frappe.msgprint("Access denied while searching SIV Request Approval. Check your permissions.");
            return;
        }
    }

    if (!approval_name) {
        frappe.msgprint({
            title: "SIV Request Approval Not Found",
            message: `No SIV Request Approval linked with Card <b>${card}</b>`,
            indicator: "red"
        });
        return;
    }

    // Fetch full approval document
    let approval_doc;
    try {
        const result = await frappe.call({
            method: "frappe.client.get",
            args: { doctype: "SIV Request Approval", name: approval_name },
            freeze: true
        });
        approval_doc = result.message;
    } catch (e) {
        frappe.msgprint("Unable to fetch SIV Request Approval document. Check permissions.");
        return;
    }

    if (!approval_doc) {
        frappe.msgprint("SIV Request Approval document not found.");
        return;
    }

    // Auto-detect child table
    let source_items = [];
    Object.keys(approval_doc).forEach(key => {
        if (Array.isArray(approval_doc[key]) && approval_doc[key].length && approval_doc[key][0].requested_qty !== undefined) {
            source_items = approval_doc[key];
        }
    });

    if (!source_items.length) {
        frappe.msgprint("No component data found in SIV Request Approval.");
        return;
    }

    // Copy items into child table
    frm.clear_table("items");
    source_items.forEach(row => {
        let child = frm.add_child("items");
        Object.assign(child, {
            type: row.item_code,
            component_type_copy: row.type_copy,
            link_part_number: row.link_part_number,
            package_style: row.package_style,
            symbol: row.symbol,
            mdb_part_number: row.mdb_part_number,
            category: row.category,
            mount_on: row.mount_on,
            stock_grade: row.stock_grade,
            position: row.position,
            requested_qty: row.requested_qty,
            from_source_ref: row.from_source_ref,
            select_issual_type: row.select_issual_type,
            fabricated_part_no_ceef: row.fabricated_part_no_ceef,
            part_number: row.part_number,
            add_option: row.add_option,
            stack: row.stack,
            actual_qty: row.actual_qty,
            expiry_date: row.expiry_date,
            manufacturer: row.manufacturer,
            serial_number: row.serial_number,
            rdc_reference_no: row.rdc_reference_no,
            stack_reference: row.stack_reference,
            date_code: row.date_code,
            entry_by: row.entry_by,
            functionality: row.functionality,
            remarks: row.remarks
        });
    });

    // Save fetched card
    await frm.set_value("fetched_card", card);
    frm.refresh_field("items");

    frappe.show_alert({
        message: `SIV Request Approval <b>${approval_name}</b> loaded successfully`,
        indicator: "green"
    });
}

frappe.ui.form.on("Production Cards Copy Components List", {

    refresh(frm) {
        // Bind COPY button click
        frm.fields_dict.copy.$wrapper
            .find("#copy_btn")
            .off("click")
            .on("click", function () {
                frm.trigger("copy_card_to_destination");
            });
    },

    async copy_card_to_destination(frm) {

        // -------------------------
        // Basic validations
        // -------------------------
        if (!frm.doc.card) {
            frappe.msgprint("Please select a Source Card.");
            return;
        }

        if (!frm.doc.d_subsystem) {
            frappe.msgprint("Please select a Destination Subsystem.");
            return;
        }

        // -------------------------
        // ALL checkbox logic
        // -------------------------
        if (frm.doc.all) {

            // ✅ CONFIRMED FIELDNAME INSIDE PRJ_PACK
            const SUBSYSTEM_LINK_FIELD = "select_sub_system";

            let packages = await frappe.db.get_list("PRJ_PACK", {
                filters: {
                    [SUBSYSTEM_LINK_FIELD]: frm.doc.d_subsystem
                },
                fields: ["name", "pack_name"]
            });

            if (!packages.length) {
                frappe.msgprint("No packages found under selected Subsystem.");
                return;
            }

            packages.forEach(pkg => {
                let exists = (frm.doc.table_hkbw || []).some(row =>
                    row.package === pkg.pack_name &&
                    row.cards === frm.doc.card_copy
                );

                if (!exists) {
                    let row = frm.add_child("table_hkbw");
                    row.package = pkg.pack_name;    // Package NAME
                    row.cards = frm.doc.card_copy; // Card NAME
                }
            });

            frm.refresh_field("table_hkbw");

            frappe.show_alert({
                message: "Card copied to all packages under selected Subsystem",
                indicator: "green"
            });

            return;
        }

        // -------------------------
        // Single package copy
        // -------------------------
        if (!frm.doc.d_package) {
            frappe.msgprint("Please select a Destination Package.");
            return;
        }

        let exists = (frm.doc.table_hkbw || []).some(row =>
            row.package === frm.doc.copy_pack &&
            row.cards === frm.doc.card_copy
        );

        if (exists) {
            frappe.msgprint({
                title: "Already Exists",
                message: "This Card already exists for the selected Package.",
                indicator: "orange"
            });
            return;
        }

        let row = frm.add_child("table_hkbw");
        row.package = frm.doc.copy_pack;
        row.cards = frm.doc.card_copy;

        frm.refresh_field("table_hkbw");

        frappe.show_alert({
            message: "Card copied successfully",
            indicator: "green"
        });
    }
});

