        // Bind click event safely
        wrapper.find("#add_btn")
            .off("click")
            .on("click", () => frm.trigger("fetch_siv_request_process_data"));
    },

    async fetch_siv_request_process_data(frm) {
        // 1️⃣ Card mandatory
        if (!frm.doc.select_card) {
            frappe.msgprint("Please select a Card first.");
            return;
        }

        const card = frm.doc.select_card.trim();

        // 2️⃣ Prevent duplicate fetch
        if (frm.doc.fetched_card === card && frm.doc.items?.length > 0) {
            frappe.msgprint({
                title: "Already Fetched",
                message: "This document is already linked with this Card.",
                indicator: "orange"
            });
            return;
        }

        // 3️⃣ Find SIV Request Process linked to this card
        let process_name = null;
        let res = null;

        try {
            res = await frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "SIV Request Process",
                    fields: ["name"],
                    filters: [["select_card", "=", card]], // safe field
                    order_by: "creation desc",
                    limit_page_length: 1
                }
            });

            if (res.message?.length) {
                process_name = res.message[0].name;
            }

            // fallback: check reference_doc if exists
            if (!process_name) {
                res = await frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "SIV Request Process",
                        fields: ["name"],
                        filters: [["reference_doc", "=", card]],
                        order_by: "creation desc",
                        limit_page_length: 1
                    }
                });
                if (res.message?.length) {
                    process_name = res.message[0].name;
                }
            }

        } catch (e) {
            frappe.msgprint("Access denied while searching SIV Request Process. Check your permissions.");
            console.error(e);
            return;
        }

        // 4️⃣ Validation
        if (!process_name) {
            frappe.msgprint({
                title: "SIV Request Process Not Found",
