frappe.ui.form.on("Purging Area Table", {
    purging_quantity(frm, cdt, cdn) {
        const r = locals[cdt][cdn];

        if ((r.purging_quantity || 0) > (r.quantity || 0)) {
            frappe.msgprint("Purging Quantity cannot exceed Stock Quantity");
            r.purging_quantity = 0;
        }

        r.pending_quantity =
            (r.quantity || 0) - (r.purging_quantity || 0);

        frm.refresh_field("table_assg");
    }
});

