frappe.ui.form.on("Copy Project Package", {

    // --------------------------------------------------
    // When Source Package is selected → fetch cards
    // --------------------------------------------------
    package(frm) {

        // Clear existing cards
        frm.clear_table("table_wpqx");
        frm.refresh_field("table_wpqx");

        if (!frm.doc.project || !frm.doc.subsystem || !frm.doc.package) {
            return;
        }

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Add Project Card",
                filters: {
                    select_project: frm.doc.project,
                    select_sub_system: frm.doc.subsystem,
                    pack_name: frm.doc.package,
                    card_type: "Project Card Wise"
                },
                fields: ["name"]
            },
            callback(r) {

                if (!r.message || r.message.length === 0) {
                    frappe.msgprint(
                        __("No cards found for the selected package")
                    );
                    return;
                }

                // --------------------------------------------------
                // Fetch cards child table from each Add Project Card
                // --------------------------------------------------
                r.message.forEach(apc => {

                    frappe.call({
                        method: "frappe.client.get",
                        args: {
                            doctype: "Add Project Card",
                            name: apc.name
                        },
                        callback(res) {

                            const doc = res.message;
                            if (!doc || !doc.table_cpgj) return;

                            doc.table_cpgj.forEach(c => {

                                let row = frm.add_child("table_wpqx");

                                row.card = c.card_name;
                                row.ecad_card = c.card_name;   // adjust if ECAD differs
                                row.status = c.status || "Initial";
                                row.updated_by = frappe.session.user;
                                row.updated_date = frappe.datetime.nowdate();
                            });

                            frm.refresh_field("table_wpqx");
                        }
                    });

                });
            }
        });
    },

    // --------------------------------------------------
    // Reset dependency chain
    // --------------------------------------------------
    project(frm) {
        frm.set_value("subsystem", null);
        frm.set_value("package", null);
        frm.clear_table("table_wpqx");
        frm.refresh_field("table_wpqx");
    },

    subsystem(frm) {
        frm.set_value("package", null);
        frm.clear_table("table_wpqx");
        frm.refresh_field("table_wpqx");
    }
});

