function bind_copy_pack_button(frm) {

    if (!frm.fields_dict.html_htbk) return;

    const wrapper = frm.fields_dict.html_htbk.$wrapper;

    // Remove old handler to avoid duplicate clicks
    wrapper.off("click", "#copy_pack_btn");

    // Bind click
    wrapper.on("click", "#copy_pack_btn", function () {
        copy_pack_to_destination(frm);
    });
}


// ==========================================================
// Copy Source → Destination
// ==========================================================
function copy_pack_to_destination(frm) {

    console.log("HTML COPY PACK CLICKED"); // 🔍 DEBUG

    // -------------------------
    // Validation
    // -------------------------
    if (!frm.doc.d_project) {
        frappe.msgprint("Select Destination Project");
        return;
    }

    if (!frm.doc.d_subsystem) {
        frappe.msgprint("Select Destination Subsystem");
        return;
    }

    if (!frm.doc.package) {
        frappe.msgprint("Source Package not selected");
        return;
    }

    if (!frm.doc.table_wpqx || frm.doc.table_wpqx.length === 0) {
        frappe.msgprint("No cards available in source table");
        return;
    }

    // -------------------------
    // Clear destination table
    // -------------------------
    frm.clear_table("table_hvnr");

    // -------------------------
    // Copy rows
    // -------------------------
    frm.doc.table_wpqx.forEach(src => {

        let row = frm.add_child("table_hvnr");

        row.subsystem    = frm.doc.d_susystem_copy; // DEST subsystem
        row.package      = frm.doc.package_copy;     // SOURCE package
        row.card         = src.card;
        row.ecad_card    = src.ecad_card;
        row.updated_by   = src.updated_by;
        row.updated_date = src.updated_date;
        row.status       = src.status;
    });

    frm.refresh_field("table_hvnr");

    frappe.show_alert({
        message: "Package copied successfully",
        indicator: "green"
    });
}

