// ==========================================================
// Add ONLY SELECTED source rows → destination
// ==========================================================
function add_selected_cards_to_destination(frm) {

    console.log("ADD PACK CLICKED"); // 🔍 Debug

    // -------------------------
    // Validations
    // -------------------------
    if (!frm.doc.d_subsystem) {
        frappe.msgprint("Select Destination Subsystem");
        return;
    }

    if (!frm.doc.package) {
        frappe.msgprint("Source Package not selected");
        return;
    }

    const source_rows = frm.doc.table_wpqx || [];

    // Get selected rows
    const selected_rows = source_rows.filter(row => row.__checked);

    if (selected_rows.length === 0) {
        frappe.msgprint("Select at least one card in Source table");
        return;
    }

    // -------------------------
    // Add selected rows
    // -------------------------
    selected_rows.forEach(src => {

        let row = frm.add_child("table_hvnr");

        row.subsystem    = frm.doc.d_susystem_copy; // DEST subsystem
        row.package      = frm.doc.package_copy;     // SOURCE package
        row.card         = src.card;
        row.ecad_card    = src.ecad_card;
        row.updated_by   = src.updated_by;
        row.updated_date = src.updated_date;
        row.status       = src.status;
    });

    frm.refresh_field("table_hvnr");

    frappe.show_alert({
        message: `${selected_rows.length} card(s) added to destination`,
        indicator: "green"
    });
}

