frappe.ui.form.on('Screening  Relifing Request', {

    project: function(frm) {

        if (!frm.doc.project) return;

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Project",
                name: frm.doc.project
            },
            callback: function(r) {

                if (!r.message) return;

                let rows = r.message.custom_warehouse_priority || [];

                // Get enabled stock grades
                let enabled_rows = rows.filter(row => row.enabled);
                let stocks = [...new Set(enabled_rows.map(row => row.stock))];

                // Case: ONLY Flight-G1 assigned
                if (stocks.length === 1 && stocks[0] === "Flight-G1") {

                    frm.set_query("store", function() {
                        return {
                            filters: [
                                ["Custom Warehouse Priority", "enabled", "=", 1],
                                ["Custom Warehouse Priority", "stock", "in", ["Flight-G1", "To-Screen"]]
                            ]
                        };
                    });

                    frappe.msgprint({
                        message: "Only Flight-G1 is assigned to this project. Allowed stores: Flight-G1 and To-Screen.",
                        indicator: "blue"
                    });

                } else {

                    // Otherwise allow only project-mapped warehouses
                    frm.set_query("store", function() {
                        return {
                            filters: [
                                ["Custom Warehouse Priority", "enabled", "=", 1],
                                ["Custom Warehouse Priority", "stock", "in", stocks]
                            ]
                        };
                    });
                }
            }
        });
    }
});

