function render_project_card_stock_ui(frm) {
  if (!frm.fields_dict.available_stock_html_card) return;
  if (!frm.doc.project__card) return;

  const $w = frm.fields_dict.available_stock_html_card.$wrapper;
  $w.empty();

  $w.html(`
    <div style="margin-bottom:10px; display:flex; gap:10px; flex-wrap:wrap;">
      <input type="text"
             id="pc_search_item"
             class="form-control"
             placeholder="Search Item Code"
             style="width:220px;">

      <select id="pc_filter_component"
              class="form-control"
              style="width:200px;">
        <option value="">All Component Types</option>
      </select>

      <select id="pc_filter_warehouse"
              class="form-control"
              style="width:240px;">
        <option value="">All Warehouses</option>
      </select>

      <button class="btn btn-sm btn-primary" id="pc_add_selected">
        Add Selected
      </button>
    </div>

    <div style="max-height:360px; overflow:auto;">
      <table class="table table-bordered table-sm">
        <thead>
          <tr>
            <th style="width:30px;">
              <input type="checkbox" id="pc_select_all">
            </th>
            <th>Component Type</th>
            <th>Item Code</th>
            <th>Project Warehouse</th>
            <th class="text-right">Available Qty</th>
          </tr>
        </thead>
        <tbody id="pc_rows"></tbody>
      </table>
    </div>
  `);

  let raw_rows = [];
  let debounce;

  function render_rows(rows) {
    let html = "";

    rows.forEach(row => {
      html += `
        <tr>
          <td>
            <input type="checkbox"
                   class="pc_row_check"
                   data-row='${JSON.stringify(row)}'>
          </td>
          <td>${row.component_type || ""}</td>
          <td>${row.item_code}</td>
          <td>${row.project_warehouse || ""}</td>
          <td class="text-right">${row.available_qty}</td>
        </tr>
      `;
    });

    $("#pc_rows").html(
      html || `<tr>
        <td colspan="5" class="text-center text-muted">
          No Components Found
        </td>
      </tr>`
    );
  }

  function apply_filters() {
    const search = ($("#pc_search_item").val() || "").toLowerCase();
    const comp = $("#pc_filter_component").val();
    const wh = $("#pc_filter_warehouse").val();

    const filtered = raw_rows.filter(r => {
      if (search && !r.item_code.toLowerCase().includes(search)) return false;
      if (comp && r.component_type !== comp) return false;
      if (wh && r.project_warehouse !== wh) return false;
      return true;
    });

    render_rows(filtered);
  }

  function load_card_items() {
    frappe.call({
      method: "ursc_cms_app.api.get_project_card_component_list_flight_lifo_soft",
      args: {
        project_card: frm.doc.project__card
      },
      callback(r) {
        raw_rows = r.message || [];

        // Populate filter dropdowns
        const components = [...new Set(raw_rows.map(r => r.component_type).filter(Boolean))];
        const warehouses = [...new Set(raw_rows.map(r => r.project_warehouse).filter(Boolean))];

        const $comp = $("#pc_filter_component").empty().append(`<option value="">All Component Types</option>`);
        components.forEach(c => $comp.append(`<option value="${c}">${c}</option>`));

        const $wh = $("#pc_filter_warehouse").empty().append(`<option value="">All Warehouses</option>`);
        warehouses.forEach(w => $wh.append(`<option value="${w}">${w}</option>`));

        apply_filters();
      }
    });
  }

  load_card_items();

  $("#pc_search_item").on("input", function () {
    clearTimeout(debounce);
    debounce = setTimeout(apply_filters, 300);
  });

  $("#pc_filter_component, #pc_filter_warehouse").on("change", apply_filters);

  $("#pc_select_all").on("change", function () {
    $(".pc_row_check").prop("checked", this.checked);
  });

  $("#pc_add_selected").on("click", function () {
    $(".pc_row_check:checked").each(function () {
      const r = JSON.parse($(this).attr("data-row"));
      const c = frm.add_child("table_reas");

      c.component_type = r.component_type;
      c.link_part_number = r.item_code;
      c.stock_grade = r.project_warehouse;
    });

    frm.refresh_field("table_reas");

    frappe.show_alert({
      message: "Project Card components added",
      indicator: "green"
    });
  });
}

