  }
});

function call_kit_action(frm, method) {
  console.log("🟠 Calling", method);

  frappe.call({
    method: `ursc_cms_app.api.${method}`,
    args: { docname: frm.doc.name },
    freeze: true,
    callback(r) {
      console.log("🟢 API OK", r.message);
      frm.reload_doc();
    },
    error(e) {
      console.error("🔴 API FAIL", e);
      frappe.msgprint({
        title: "Server Error",
        message: e?.message || "Check console / server logs",
        indicator: "red"
      });
    }
  });
}

