frappe.ui.form.on('Screening Relifing Request', {

    project: function(frm) {
        populate_stock_grades(frm);
        reset_component(frm);
    },

    component_type: function(frm) {
        reset_component(frm);
        set_component_query(frm);
    },

    component: function(frm) {
        fetch_stock_details(frm);
    },

    selected_stock_grade: function(frm) {
        fetch_stock_details(frm);
    }
});

/* ------------------------------------------------ */
/* Reset component & dependent fields               */
/* ------------------------------------------------ */
function reset_component(frm) {
    frm.set_value('component', '');
    frm.set_value('stock_qty', 0);
    frm.set_value('date_code', '');
    frm.set_value('expiry_date', '');
}

/* ------------------------------------------------ */
/* Component filter based on Project + Type         */
/* ------------------------------------------------ */
function set_component_query(frm) {

    if (!frm.doc.project || !frm.doc.component_type) return;

    frm.set_query('component', function() {
        return {
            query: 'ursc_cms_app.api.get_project_components',
            filters: {
                project: frm.doc.project,
                component_type: frm.doc.component_type
            }
        };
    });
}

/* ------------------------------------------------ */
/* Populate Selected Stock Grade from Project       */
/* Uses Project child table field: row.stock        */
/* ------------------------------------------------ */
function populate_stock_grades(frm) {

    // clear old options
    frm.set_df_property('selected_stock_grade', 'options', '');
    frm.set_value('selected_stock_grade', '');

    if (!frm.doc.project) return;

    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Project',
            name: frm.doc.project
        },
        callback: function(r) {

            if (!r.message) return;

            let rows = r.message.custom_warehouse_priority || [];
            let grades = [];

            rows.forEach(row => {

                if (row.enabled == 1 && row.stock) {

                    let stock = row.stock;

                    // Allow only Flight-G1 and To-Screen
                    if (
                        stock.includes('Flight') ||
                        stock.toLowerCase().includes('to-screen')
                    ) {
                        grades.push(stock);
                    }
                }
            });

            grades = [...new Set(grades)];

            if (grades.length === 0) {
                frappe.msgprint(
                    __('No Flight-G1 or To-Screen stock grades found for this Project')
                );
                return;
            }

            frm.set_df_property(
                'selected_stock_grade',
                'options',
                grades.join('\n')
            );

            frm.refresh_field('selected_stock_grade');
        }
    });
}

/* ------------------------------------------------ */
/* Fetch Stock Qty + Date Code + Expiry Date        */
/* ------------------------------------------------ */
function fetch_stock_details(frm) {

    if (!frm.doc.project ||
        !frm.doc.component ||
        !frm.doc.selected_stock_grade) {
        return;
    }

    frappe.call({
        method: 'ursc_cms_app.api.get_lowest_date_code_stock',
        args: {
            project: frm.doc.project,
            item: frm.doc.component,
            stock_grade: frm.doc.selected_stock_grade
        },
        callback: function(r) {

            let data = r.message || {};

            frm.set_value('stock_qty', data.qty || 0);
            frm.set_value('date_code', data.date_code || '');
            frm.set_value('expiry_date', data.expiry_date || '');
        }
    });
}

