/*****************************************************
 * IDENTIFY STOCK TYPE FROM SOURCE STOCK NAME
 *****************************************************/
function get_stock_type(warehouse) {
    if (!warehouse) return null;

    if (warehouse.endsWith("TO SCR - N")) return "TO-SCR";
    if (warehouse.endsWith("Ground - N")) return "GROUND";
    if (warehouse.endsWith("Flight G2 - N")) return "FG2";
    if (warehouse.endsWith("Flight G1 - N")) return "FG1";

    return null;
}

/*****************************************************
 * SOURCE → TARGET STOCK SUFFIX RULES
 *****************************************************/
const STOCK_SUFFIX_RULES = {
    "TO-SCR": ["TO SCR - N"],
    "GROUND": ["Ground - N"],
    "FG2": ["Flight G2 - N", "Ground - N"],
    "FG1": ["Flight G1 - N", "Flight G2 - N", "Ground - N"]
};

