function set_child_warehouse_filters(frm) {
    const grid = frm.fields_dict.items.grid;

    // ==================================================
    // SOURCE STORE
    // ==================================================
    grid.get_field("custom_store").get_query = () => ({
        filters: {
            parent_warehouse: "STORE - N",
            is_group: 1
        }
    });

    // ==================================================
    // SOURCE PROGRAM
    // ==================================================
    grid.get_field("custom_source_program").get_query = (doc, cdt, cdn) => {
        const row = locals[cdt][cdn];

        if (!row.custom_store) {
            frappe.msgprint("Please select the Source Store first.");
            return { filters: { name: "__none__" } };
        }

        return {
            filters: {
                parent_warehouse: row.custom_store,
                is_group: 1
            }
        };
    };

    // ==================================================
    // SOURCE STOCK
    // ==================================================
    grid.get_field("custom_select_source_stock").get_query = (doc, cdt, cdn) => {
        const row = locals[cdt][cdn];

        if (!row.custom_source_program) {
            frappe.msgprint("Please select the Source Program first.");
            return { filters: { name: "__none__" } };
        }

        return {
            filters: {
                parent_warehouse: row.custom_source_program,
                is_group: 0
            }
        };
    };

    // ==================================================
    // TARGET STORE
    // ==================================================
    grid.get_field("custom_target_store_").get_query = () => ({
        filters: {
            parent_warehouse: "STORE - N",
            is_group: 1
        }
    });

    // ==================================================
    // TARGET PROGRAM
    // ==================================================
    grid.get_field("custom_target_program").get_query = (doc, cdt, cdn) => {
        const row = locals[cdt][cdn];

        if (!row.custom_target_store_) {
            frappe.msgprint("Please select the Target Store first.");
            return { filters: { name: "__none__" } };
        }

        return {
            filters: {
                parent_warehouse: row.custom_target_store_,
                is_group: 1
            }
        };
    };

    // ==================================================
    // TARGET STOCK (FINAL – EXACT NAME MATCH)
    // ==================================================
    grid.get_field("custom_target_stock").get_query = (doc, cdt, cdn) => {
        const row = locals[cdt][cdn];

        if (!row.custom_target_program || !row.custom_select_source_stock) {
            frappe.msgprint("Please select Source Stock and Target Program first.");
            return { filters: { name: "__none__" } };
        }

        const source_type = get_stock_type(row.custom_select_source_stock);
        const suffixes = STOCK_SUFFIX_RULES[source_type];

        if (!suffixes) {
            frappe.msgprint("Invalid Source Stock selected.");
            return { filters: { name: "__none__" } };
        }

        // ✅ FIXED: remove " - N" and trailing spaces
        const program_base = row.custom_target_program
            .replace(/ - N$/, "")
            .trim();

        const target_names = suffixes.map(suffix => {
            return `${program_base}-${suffix}`;
        });

        return {
            filters: {
                name: ["in", target_names]
            }
        };
    };
}

