frappe.ui.form.on("Update Failure Request", {

    // ----------------------------------
    // FETCH DATA WHEN REQUEST NO SELECTED
    // ----------------------------------
    async request_no(frm) {

        if (!frm.doc.request_no) return;

        let res = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Failure Request",
                name: frm.doc.request_no
            }
        });

        let fr = res.message;
        if (!fr) {
            frappe.msgprint("Failure Request not found");
            return;
        }

        // ===== Parent Fields =====
        frm.set_value("request_date", fr.req_date);
        frm.set_value("requested_by", fr.requested_by);
        frm.set_value("status", fr.status);

        frm.set_value("project", fr.select_project);
        frm.set_value("subsystem", fr.subsystem);
        frm.set_value("package", fr.pack_name);
        frm.set_value("card", fr.ecad_card_name);
        frm.set_value("data_cmte", fr.failed_during);
        frm.set_value("failure_type", fr.failure_type);
        frm.set_value("specify_failure_type", fr.specify_failure_type);
        frm.set_value("failure_mode", fr.failure_mode);
        frm.set_value("specify_failure_mode", fr.specify_failure_mode);
        frm.set_value("environmental_test_condition", fr.environmental_test_condition);
        frm.set_value("project_model", fr.project_model);
        frm.set_value("reported_failure", fr.reported_failure);
        frm.set_value("description", fr.description);

        // ===== Component Details (Child → Parent) =====
        if (fr.table_bnpa && fr.table_bnpa.length > 0) {

            let comp = fr.table_bnpa[0];

            frm.set_value("component_type", comp.type);
            frm.set_value("mdb_part_no", comp.mdb_part_number || comp.mdb_number);
            frm.set_value("package_style", comp.package_style);
            frm.set_value("date_code", comp.date_code);
            frm.set_value("manufacturer", comp.manufacturer);
            frm.set_value("quality", comp.quality);
            frm.set_value("specify_quality", comp.specify_quality);
            frm.set_value("sr_no", comp.sr_no);
            frm.set_value("procurement_spec", comp.procurement_spec);
            frm.set_value("specify_procurement_specification", comp.specify_procurement_spec);
        }

        frappe.show_alert({ message: "Data fetched successfully", indicator: "green" });
    },

    // ----------------------------------
    // UPDATE ORIGINAL FAILURE REQUEST
    // ----------------------------------
    async update_failure_request(frm) {

        if (!frm.doc.request_no) {
            frappe.msgprint("Please select Request No");
            return;
        }

        // -----------------------------
        // Update Parent Fields
        // -----------------------------
        await frappe.call({
            method: "frappe.client.set_value",
            args: {
                doctype: "Failure Request",
                name: frm.doc.request_no,
                fieldname: {
                    status: frm.doc.status,
                    failure_type: frm.doc.failure_type,
                    specify_failure_type: frm.doc.specify_failure_type,
                    failure_mode: frm.doc.failure_mode,
                    specify_failure_mode: frm.doc.specify_failure_mode,
                    environmental_test_condition: frm.doc.environmental_test_condition,
                    reported_failure: frm.doc.reported_failure,
                    description: frm.doc.description
                }
            }
        });

        // -----------------------------
        // Update Child Table (1st row)
        // -----------------------------
        let fr_doc = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Failure Request",
                name: frm.doc.request_no
            }
        });

        let fr = fr_doc.message;

        if (fr.table_bnpa && fr.table_bnpa.length > 0) {

            let row_name = fr.table_bnpa[0].name;

            await frappe.call({
                method: "frappe.client.set_value",
                args: {
                    doctype: "FA Component Details",
                    name: row_name,
                    fieldname: {
                        type: frm.doc.component_type,
                        package_style: frm.doc.package_style,
                        manufacturer: frm.doc.manufacturer,
                        quality: frm.doc.quality,
                        specify_quality: frm.doc.specify_quality,
                        sr_no: frm.doc.sr_no,
                        procurement_spec: frm.doc.procurement_spec,
                        specify_procurement_spec: frm.doc.specify_procurement_specification
                    }
                }
            });
        }

        frappe.msgprint({
            title: "Success",
            message: "Failure Request updated successfully",
            indicator: "green"
        });
    },

    // ----------------------------------
    // VALIDATION
    // ----------------------------------
    validate(frm) {
        if (!frm.doc.component_type) {
            frappe.msgprint("Component Type is mandatory");
            frappe.validated = false;
        }
    }
});

