frappe.ui.form.on('Alternate Part Disable', {

  refresh(frm) {
    if (frm.doc.link_part_number) {
      frm.trigger('render_alt_html');
    }
  },

  link_part_number(frm) {
    // reset when main item changes
    frm.set_value('selected_alternatives', '[]');
    frm.trigger('render_alt_html');
  },

  render_alt_html(frm) {
    if (!frm.doc.link_part_number) {
      frm.set_df_property('alternate_part_data', 'options', '');
      return;
    }

    frappe.call({
      method: "ursc_cms_app.api.get_item_alternatives",
      args: { item_code: frm.doc.link_part_number },
      callback(r) {

        const list = r.message || [];
        const selected = JSON.parse(frm.doc.selected_alternatives || '[]');

        let html = `
          <div style="padding:8px">
            <b>Alternate Part Disable</b><br><br>

            <input type="text"
                   id="alt-search"
                   placeholder="Search alternate part..."
                   style="width:100%; padding:6px; margin-bottom:8px;">

            <div id="alt-list">
        `;

        if (!list.length) {
          html += `<p>No alternate parts found</p>`;
        } else {
          list.forEach(row => {
            const code = row.alternative_item_code;
            const checked = selected.includes(code) ? "checked" : "";
            html += `
              <div class="alt-row" data-code="${code}">
                <label>
                  <input type="checkbox" class="alt-checkbox" value="${code}" ${checked}>
                  ${code}
                </label>
              </div>
            `;
          });
        }

        html += `</div></div>`;
        frm.set_df_property('alternate_part_data', 'options', html);

        // attach handlers
        setTimeout(() => {
          const wrap = frm.fields_dict.alternate_part_data.$wrapper;

          // search
          wrap.find('#alt-search').on('keyup', function () {
            const q = this.value.toLowerCase();
            wrap.find('.alt-row').each(function () {
              $(this).toggle($(this).data('code').toLowerCase().includes(q));
            });
          });

          // checkbox persist
          wrap.find('.alt-checkbox').on('change', function () {
            let sel = JSON.parse(frm.doc.selected_alternatives || '[]');
            const code = this.value;

            if (this.checked && !sel.includes(code)) sel.push(code);
            if (!this.checked) sel = sel.filter(x => x !== code);

            frm.set_value('selected_alternatives', JSON.stringify(sel));
          });

        }, 100);
      }
    });
  },

  before_submit(frm) {
    const selected = JSON.parse(frm.doc.selected_alternatives || '[]');
    if (!selected.length) {
      frappe.throw(__('Please select at least one alternate part'));
    }
  }
});

