function update_mdb_number_options_parent(frm) {

    const component_type = frm.doc.component_type;

    if (!component_type) {
        frm.set_value("mdb_part_no", "");
        frm.set_value("date_code", "");
        frm.set_value("quality", "");

        frm.set_df_property("mdb_part_no", "options", []);
        return;
    }

    frappe.db.get_list("Stock Entry Detail", {
        fields: [
            "custom_select_component_type",
            "custom_mdb_part_no",
            "custom_date_code",
            "custom_quality"
        ],
        filters: {
            custom_select_component_type: component_type
        },
        limit: 100
    }).then(res => {

        const options = res
            .map(r => r.custom_mdb_part_no)
            .filter(Boolean);

        // 🔹 Update SELECT options in parent field
        frm.set_df_property(
            "mdb_part_no",
            "options",
            ["", ...options].join("\n")
        );

        // 🔹 Reset if invalid
        if (!options.includes(frm.doc.mdb_part_no)) {
            frm.set_value("mdb_part_no", "");
            frm.set_value("date_code", "");
            frm.set_value("quality", "");
        } else {
            // 🔹 Auto-fill if still valid
            const matched = res.find(
                r => r.custom_mdb_part_no === frm.doc.mdb_part_no
            );

            if (matched) {
                frm.set_value("date_code", matched.custom_date_code || "");
                frm.set_value("quality", matched.custom_quality || "");
            }
        }
    });
}

