frappe.ui.form.on("Screening  Relifing Request", {

    refresh(frm) {
        // Ensure select field starts clean
        frm.set_df_property("stock_grade_sequence", "options", []);
    },
        stock_grade_sequence(frm) {

        frm.set_value("selected_stock_grade", null);

        if (!frm.doc.stock_grade_sequence) {
            return;
        }

        frm.set_query("selected_stock_grade", () => ({
            query: "ursc_cms_app.project_api.get_warehouse_by_stock_grade",
            filters: {
                stock_grade: frm.doc.stock_grade_sequence
            }
        }));
    },

    project(frm) {

        // Reset dependent fields
        frm.set_value("type", null);
        frm.set_value("link_part_number", null);
        frm.set_value("stock_grade_sequence", null);
        frm.set_df_property("stock_grade_sequence", "options", []);

        if (!frm.doc.project) {
            return;
        }

        /* -----------------------------
         * Project → Item Group
         * ----------------------------- */
        frm.set_query("type", () => ({
            query: "ursc_cms_app.item_api.get_item_groups_by_project",
            filters: {
                project: frm.doc.project
            }
        }));

        /* -----------------------------
         * Project → Item (initial)
         * ----------------------------- */
        frm.set_query("link_part_number", () => ({
            query: "ursc_cms_app.item_api.get_items_by_project",
            filters: {
                project: frm.doc.project
            }
        }));

        /* -----------------------------
         * Project → Warehouses (Select)
         * ----------------------------- */
        frappe.call({
            method: "ursc_cms_app.project_api.get_project_warehouses",
            args: {
                project: frm.doc.project
            },
            freeze: false,
            callback(r) {
                const rows = r.message || [];

                if (!rows.length) {
                    return;
                }

                // rows = [ ['WH-01'], ['WH-02'] ]
                const options = rows.map(d => d[0]).filter(Boolean);

                frm.set_df_property(
                    "stock_grade_sequence",
                    "options",
                    options.join("\n")
                );
            }
        });
    },

    type(frm) {

        // Reset item when type changes
        frm.set_value("link_part_number", null);

        if (!frm.doc.type || !frm.doc.project) {
            return;
        }

        /* -----------------------------
         * Project + Item Group → Item
         * ----------------------------- */
        frm.set_query("link_part_number", () => ({
            query: "ursc_cms_app.item_api.get_items_by_project",
            filters: {
                project: frm.doc.project,
                item_group: frm.doc.type
            }
        }));
    }
});

