function fetch_cardex(frm, cdt, cdn) {
    // Gate condition
    if (frm.doc.stock_entry_type !== "Stock Entry") {
        frappe.model.set_value(cdt, cdn, "custom_select_location", "");
        return;
    }

    const row = locals[cdt][cdn];
    if (!row) return;

    if (
        !row.custom_target_store_ ||
        !row.custom_target_program ||
        !row.custom_target_stock ||
        !row.custom_mdb_part_no
    ) {
        frappe.model.set_value(cdt, cdn, "custom_select_location", "");
        return;
    }

    frappe.call({
        method: "ursc_cms_app.cardex.api.get_cardex_by_mapping",
        args: {
            select_store: row.custom_target_store_,
            select_program: row.custom_target_program,
            select_stock: row.custom_target_stock,
            mdb_part_no: row.custom_mdb_part_no
        },
        callback: function (r) {
            if (r && r.message) {
                const cardex_name = r.message.name || r.message;
                frappe.model.set_value(
                    cdt,
                    cdn,
                    "custom_select_location",
                    cardex_name
                );
            } else {
                // New MDB for this location → no cardex yet
                frappe.model.set_value(
                    cdt,
                    cdn,
                    "custom_select_location",
                    ""
                );
            }
        }
    });
}


