/* =========================================================
   BUILD PROJECTED QTY TABLE
   ========================================================= */
function buildProjectedQtyTable(projectedMap) {
  let html = "";

  Object.keys(projectedMap).forEach(item => {
    const rec = projectedMap[item];

    html += `
      <tr>
        <td colspan="4"><b>Item :</b> ${item}</td>
      </tr>
      <tr>
        <td colspan="2"><b>Total Projected Qty (All Warehouses)</b></td>
        <td colspan="2" class="center"><b>${rec.total_projected_qty_all_wh}</b></td>
      </tr>
    `;

    if (rec.priority_warehouse_projected.length) {
      html += `
        <tr>
          <td colspan="4"><b>Priority Warehouses</b></td>
        </tr>
      `;
      rec.priority_warehouse_projected.forEach(r => {
        html += `
          <tr>
            <td>${r.warehouse}</td>
            <td colspan="2">Priority ${r.priority}</td>
            <td class="center">${r.projected_qty}</td>
          </tr>
        `;
      });
    }

    if (rec.other_warehouse_projected.length) {
      html += `
        <tr>
          <td colspan="4"><b>Other Warehouses</b></td>
        </tr>
      `;
      rec.other_warehouse_projected.forEach(r => {
        html += `
          <tr>
            <td>${r.warehouse}</td>
            <td colspan="2"></td>
            <td class="center">${r.projected_qty}</td>
          </tr>
        `;
      });
    }

    html += `<tr><td colspan="4">&nbsp;</td></tr>`;
  });

  return html;
}

