frappe.ui.form.on("Add BAN", {

    component_type(frm) {
        frm.trigger("load_mfr");
    },

    stock(frm) {
        frm.trigger("load_mfr");
    },

    mfr(frm) {
        frm.trigger("load_datecode");
    },

    // --------------------------
    // Load Manufacturer (Select)
    // --------------------------
    load_mfr(frm) {

        frm.set_value("mfr", "");
        frm.set_value("datecode", "");

        frm.set_df_property("mfr", "options", "");
        frm.set_df_property("datecode", "options", "");

        if (!frm.doc.component_type || !frm.doc.stock) return;

        frappe.call({
            method: "ursc_cms_app.item_api.get_mfr_by_component_and_stock",
            args: {
                component_type: frm.doc.component_type,
                stock: frm.doc.stock
            },
            callback(r) {

                const rows = r.message || [];
                if (!rows.length) return;

                const options = rows
                    .map(d => d[0])
                    .filter(Boolean)
                    .join("\n");

                frm.set_df_property("mfr", "options", options);
            }
        });
    },

    // --------------------------
    // Load Date Code (Select)
    // --------------------------
    load_datecode(frm) {

        frm.set_value("datecode", "");
        frm.set_df_property("datecode", "options", "");

        if (!frm.doc.component_type || !frm.doc.stock || !frm.doc.mfr) return;

        frappe.call({
            method: "ursc_cms_app.item_api.get_datecode_by_mfr_component_stock",
            args: {
                component_type: frm.doc.component_type,
                stock: frm.doc.stock,
                mfr: frm.doc.mfr
            },
            callback(r) {

                const rows = r.message || [];
                if (!rows.length) return;

                const options = rows
                    .map(d => d[0])
                    .filter(Boolean)
                    .join("\n");

                frm.set_df_property("datecode", "options", options);
            }
        });
    }

});

frappe.ui.form.on("Purchase Order", {

  refresh(frm) {
    setup_po_number_validation(frm);
  },

  custom_po_number(frm) {
    validate_po_number_field(frm);
  },

  validate(frm) {
    // Hard validation before save
    if (!frm.doc.custom_po_number) {
      frappe.throw(__('PO Number is mandatory.'));
    }

    const value = frm.doc.custom_po_number;

    if (!/^[A-Za-z0-9]+$/.test(value)) {
      frappe.throw(__('PO Number must contain only alphanumeric characters (A-Z, a-z, 0-9). No spaces or special characters allowed.'));
    }
  }
});


/* =========================================================
   CLEAN + REALTIME VALIDATION
   ========================================================= */

function validate_po_number_field(frm) {
  let value = (frm.doc.custom_po_number || '').toString();

  // Remove spaces
  value = value.replace(/\s+/g, '');

  // Remove special characters
  value = value.replace(/[^A-Za-z0-9]/g, '');

  if (value !== frm.doc.custom_po_number) {
    frm.set_value("custom_po_number", value);
  }
}

function setup_po_number_validation(frm) {
  const field = frm.fields_dict.custom_po_number;
  if (!field || !field.$input) return;

  field.$input.off('input.ponum keypress.ponum');

  // Prevent special characters while typing
  field.$input.on('keypress.ponum', function(e) {
    const key = e.key;

    // Allow backspace, delete, arrows, tab, ctrl combos
    if (
      [8, 9, 27, 13, 46, 37, 38, 39, 40].includes(e.keyCode) ||
      (e.ctrlKey && [65, 67, 86, 88].includes(e.keyCode))
    ) {
      return;
    }

    if (!/[A-Za-z0-9]/.test(key)) {
      e.preventDefault();
      return false;
    }
  });

  // Auto-clean on input
  field.$input.on('input.ponum', function() {
    let value = $(this).val();
    value = value.replace(/\s+/g, '');
    value = value.replace(/[^A-Za-z0-9]/g, '');
    $(this).val(value);
  });
}

