function render_action_table(frm) {

    if (!frm.fields_dict.action) return;

    let data = frm.doc.gd_approval_items || [];

    let html = `
        <div class="card p-3 shadow-sm" style="border-radius:10px;">
            <h4 style="margin-bottom:15px;">Card Approval</h4>

            <table class="table table-bordered">
                <thead style="background:#f5f5f5;">
                    <tr>
                        <th style="width:40%">Card</th>
                        <th style="width:20%">Status</th>
                        <th style="width:40%">Action</th>
                    </tr>
                </thead>
                <tbody>
    `;

    if (data.length === 0) {
        html += `
            <tr>
                <td colspan="3" class="text-center text-muted">
                    No Records Found
                </td>
            </tr>
        `;
    } else {

        data.forEach(row => {

            let badge_color = "secondary";

            if (row.status === "Approved") badge_color = "success";
            if (row.status === "Rejected") badge_color = "danger";
            if (row.status === "Pending") badge_color = "warning";

            html += `
                <tr>
                    <td>${row.card_name || ""}</td>
                    <td>
                        <span class="badge badge-${badge_color}">
                            ${row.status || "Pending"}
                        </span>
                    </td>
                    <td>
                        <button class="btn btn-success btn-sm approve-btn"
                            data-name="${row.name}">
                            Approve
                        </button>

                        <button class="btn btn-danger btn-sm reject-btn"
                            data-name="${row.name}">
                            Reject
                        </button>
                    </td>
                </tr>
            `;
        });
    }

    html += `
                </tbody>
            </table>
        </div>
    `;

    frm.fields_dict.action.$wrapper.html(html);

// ✅ Approve
frm.fields_dict.action.$wrapper.find(".approve-btn").click(function () {

    let rowname = $(this).attr("data-name");

    // Status field
    frappe.model.set_value(
